/**
 * Benchmark comparativo CutLayout — mede impacto das melhorias de nesting
 * (chapas, desperdício, micro-gaps, ilhas, tempo, regressão TCN estrutural).
 *
 * Uso:
 *   node --loader ts-node/esm scripts/benchmark-cutlayout-impact.ts --phase before
 *   node --loader ts-node/esm scripts/benchmark-cutlayout-impact.ts --phase after
 *   node --loader ts-node/esm scripts/benchmark-cutlayout-impact.ts --merge
 */

import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { performance } from "node:perf_hooks";
import { cutlistToPieces, runCutLayout } from "../src/core/cutlayout/cutLayoutEngine";
import type { CutLayoutResult, CutPiece, SheetDefinition } from "../src/core/cutlayout/cutLayoutTypes";
import { computeTightnessScore } from "../src/core/cutlayout/scoring/rotationScoring";
import { validateIndustrialLayout } from "../src/core/cutlayout/integration/industrialLayoutContract";
import { buildCutlistItemsForIndustrialExport } from "../src/core/fabrication/buildCutlistItemsForIndustrialExport";
import { buildIndustrialDataForProject } from "../src/core/fabrication/industrialPipeline";
import {
  buildCncFromCutlistItems,
  getDefaultCncLayoutOptions,
  getSheetDefinitionFromSettings,
} from "../src/core/cnc/cncPipeline";
import { defaultRulesConfig } from "../src/core/rules/rulesConfig";
import {
  buildDrawerOnlyBox,
  buildFullIndustrialScenario,
  inferIndustrialPieceKind,
} from "../src/validation/industrialPipelineTestHelpers";

type Phase = "before" | "after";

type Rect = { x: number; y: number; w: number; h: number; partName: string };

type SheetAnalysis = {
  sheetIndex: number;
  usedAreaMm2: number;
  wastePercent: number;
  microGapsLt5mm: number;
  internalIslands: number;
  wasteScatterIndex: number;
  bboxUsedMaxX: number;
  bboxUsedMaxY: number;
  selectedStrategy?: string;
};

type ScenarioMetrics = {
  scenarioId: string;
  description: string;
  pieceCount: number;
  mode: "SPM" | "MPM" | "IMPORT";
  executionMs: number;
  totalSheets: number;
  avgWastePercent: number;
  totalMicroGapsLt5mm: number;
  totalInternalIslands: number;
  avgWasteScatterIndex: number;
  utilizationPercent: number;
  selectedStrategy?: string;
  selectedBinHeuristic?: string;
  perSheet: SheetAnalysis[];
  tcnRegression: {
    ok: boolean;
    fileCount: number;
    totalPiecesInTcn: number;
    structuralHash: string;
    fullHash: string;
    validationErrors: string[];
  };
  labelsContract: {
    pieceKindsSample: Record<string, string>;
    industrialLayoutValid: boolean;
    layoutValidationErrors: string[];
  };
};

type BenchmarkPayload = {
  phase: Phase;
  baselineCommit: string;
  generatedAt: string;
  layoutOptions: string;
  scenarios: ScenarioMetrics[];
};

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_DIR = join(__dirname, "cnc-examples-output");
const BEFORE_JSON = join(OUT_DIR, "CUTLAYOUT_IMPACT_BEFORE.json");
const AFTER_JSON = join(OUT_DIR, "CUTLAYOUT_IMPACT_AFTER.json");
const MERGED_JSON = join(OUT_DIR, "CUTLAYOUT_IMPACT_BENCHMARK.json");
const REPORT_TXT = join(OUT_DIR, "CUTLAYOUT_IMPACT_BENCHMARK.txt");
const REPORT_MD = join(OUT_DIR, "CUTLAYOUT_IMPACT_BENCHMARK.md");
const TEST1_FILE = join(OUT_DIR, "TEST 1.txt");
const BASELINE_COMMIT = "aecf802";

function parseArgs(): { phase: Phase | "merge" } {
  const idx = process.argv.indexOf("--phase");
  const raw = idx >= 0 ? process.argv[idx + 1] : "after";
  if (raw === "before" || raw === "after" || raw === "merge") return { phase: raw };
  throw new Error(`Fase inválida: ${raw}. Use --phase before|after|merge`);
}

function parseHeader(content: string): { dl: number; dh: number; ds: number } {
  const m = content.match(/::UNm\s+DL=(\d+)\s+DH=(\d+)\s+DS=(\d+)/);
  if (!m) throw new Error("Header ::UNm DL/DH/DS não encontrado.");
  return { dl: Number(m[1]), dh: Number(m[2]), ds: Number(m[3]) };
}

function parsePiecesFromTcn(content: string, thickness: number): CutPiece[] {
  const lines = content.split(/\r?\n/);
  const pieces: CutPiece[] = [];

  for (let i = 0; i < lines.length; i++) {
    const pieceMatch = lines[i].match(/^;PIECE\s+(.+?)\s+\((.*?)\)\s+#\d+/);
    if (!pieceMatch) continue;
    const partName = pieceMatch[1];
    const boxId = pieceMatch[2];
    const points: Array<{ x: number; y: number }> = [];

    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].startsWith(";PIECE")) break;
      const w2200 = lines[j].match(/^W#2200\s+X=([0-9]+(?:\.[0-9]+)?)\s+Y=([0-9]+(?:\.[0-9]+)?)/);
      if (w2200) {
        points.push({ x: Number(w2200[1]), y: Number(w2200[2]) });
        if (points.length >= 5) break;
      }
    }
    if (points.length < 4) continue;
    const xs = points.map((p) => p.x);
    const ys = points.map((p) => p.y);
    pieces.push({
      partName,
      boxId,
      largura_mm: Math.round(Math.max(...xs) - Math.min(...xs)),
      altura_mm: Math.round(Math.max(...ys) - Math.min(...ys)),
      espessura_mm: thickness,
      materialId: "mdf_branco",
    });
  }
  return pieces;
}

function hashText(value: string): string {
  return createHash("sha256").update(value).digest("hex").slice(0, 16);
}

function normalizeTcnStructural(tcn: string): string {
  return tcn
    .split(/\r?\n/)
    .filter((line) => !/^W#2200\s+X=/.test(line) && !/^W#2201\s+X=/.test(line))
    .map((line) => line.replace(/\s+/g, " ").trim())
    .join("\n");
}

function countTcnPieces(tcn: string): number {
  return (tcn.match(/^;PIECE\s+/gm) ?? []).length;
}

function analyzeSheet(
  sheetIndex: number,
  sheet: SheetDefinition,
  placements: Rect[],
  kerf: number
): SheetAnalysis {
  const sw = sheet.largura_mm;
  const sh = sheet.altura_mm;
  const usedArea = placements.reduce((acc, r) => acc + r.w * r.h, 0);
  const wastePercent = sw * sh > 0 ? ((sw * sh - usedArea) / (sw * sh)) * 100 : 0;
  const gapTolerance = Math.max(0.5, kerf + 0.3);

  let microGapsLt5mm = 0;
  for (let i = 0; i < placements.length; i++) {
    for (let j = i + 1; j < placements.length; j++) {
      const a = placements[i];
      const b = placements[j];
      const sameRow = a.y < b.y + b.h + gapTolerance && a.y + a.h > b.y - gapTolerance;
      if (sameRow) {
        const gap = a.x < b.x ? b.x - (a.x + a.w) : a.x - (b.x + b.w);
        if (gap > gapTolerance && gap < 5) microGapsLt5mm++;
      }
      const sameCol = a.x < b.x + b.w + gapTolerance && a.x + a.w > b.x - gapTolerance;
      if (sameCol) {
        const gap = a.y < b.y ? b.y - (a.y + a.h) : a.y - (b.y + b.h);
        if (gap > gapTolerance && gap < 5) microGapsLt5mm++;
      }
    }
  }

  const placedLite = placements.map((p) => ({ x: p.x, y: p.y, w: p.w, h: p.h }));
  let internalIslands = 0;
  for (const r of placements) {
    const tightness = computeTightnessScore(r.x, r.y, r.w, r.h, sheet, placedLite, kerf);
    if (tightness < 0.2 && r.x > sw * 0.04 && r.y > sh * 0.04) internalIslands++;
  }

  const bboxUsedMaxX = placements.length ? Math.max(...placements.map((r) => r.x + r.w)) : 0;
  const bboxUsedMaxY = placements.length ? Math.max(...placements.map((r) => r.y + r.h)) : 0;
  const bboxArea = bboxUsedMaxX * bboxUsedMaxY;
  const bboxWaste = Math.max(0, bboxArea - usedArea);
  const totalWaste = Math.max(0, sw * sh - usedArea);
  const wasteOutsideBbox = Math.max(0, totalWaste - bboxWaste);
  const wasteScatterIndex = totalWaste > 0 ? wasteOutsideBbox / totalWaste : 0;

  return {
    sheetIndex,
    usedAreaMm2: Math.round(usedArea),
    wastePercent: Number(wastePercent.toFixed(2)),
    microGapsLt5mm,
    internalIslands,
    wasteScatterIndex: Number(wasteScatterIndex.toFixed(3)),
    bboxUsedMaxX: Math.round(bboxUsedMaxX),
    bboxUsedMaxY: Math.round(bboxUsedMaxY),
  };
}

function analyzeLayout(result: CutLayoutResult, kerf: number): Omit<ScenarioMetrics, "scenarioId" | "description" | "pieceCount" | "mode" | "executionMs" | "tcnRegression" | "labelsContract"> {
  const perSheet = result.sheets.map((s, idx) =>
    analyzeSheet(
      idx + 1,
      s.sheet,
      s.placements.map((p) => ({
        x: p.x_mm,
        y: p.y_mm,
        w: p.largura_mm,
        h: p.altura_mm,
        partName: p.partName,
      })),
      kerf
    )
  );

  const totalSheetArea = result.sheets.reduce(
    (acc, s) => acc + s.sheet.largura_mm * s.sheet.altura_mm,
    0
  );
  const totalUsedArea = result.sheets.reduce(
    (acc, s) => acc + s.placements.reduce((inner, p) => inner + p.largura_mm * p.altura_mm, 0),
    0
  );

  return {
    totalSheets: result.sheets.length,
    avgWastePercent: perSheet.length
      ? Number((perSheet.reduce((a, s) => a + s.wastePercent, 0) / perSheet.length).toFixed(2))
      : 0,
    totalMicroGapsLt5mm: perSheet.reduce((a, s) => a + s.microGapsLt5mm, 0),
    totalInternalIslands: perSheet.reduce((a, s) => a + s.internalIslands, 0),
    avgWasteScatterIndex: perSheet.length
      ? Number((perSheet.reduce((a, s) => a + s.wasteScatterIndex, 0) / perSheet.length).toFixed(3))
      : 0,
    utilizationPercent: totalSheetArea > 0 ? Number(((totalUsedArea / totalSheetArea) * 100).toFixed(2)) : 0,
    selectedStrategy: result.diagnostics?.flow.selectedStrategy,
    selectedBinHeuristic: result.diagnostics?.flow.selectedBinHeuristic,
    perSheet,
  };
}

function runTcnRegression(
  pieces: CutPiece[],
  sheet: SheetDefinition,
  layoutOptions: ReturnType<typeof getDefaultCncLayoutOptions>
): ScenarioMetrics["tcnRegression"] {
  const items = pieces.map((p) => ({
    nome: p.partName,
    boxId: p.boxId ?? "box",
    dimensoes: { largura: p.largura_mm, altura: p.altura_mm, profundidade: p.espessura_mm },
    espessura: p.espessura_mm,
    quantidade: 1,
    materialId: p.materialId ?? "mdf_branco",
    tipo: p.pieceTipo ?? "generic",
  }));

  try {
    const bundle = buildCncFromCutlistItems({ projectName: "BENCH" }, items, sheet, layoutOptions);
    if (!bundle?.cnc?.files?.length) {
      return {
        ok: false,
        fileCount: 0,
        totalPiecesInTcn: 0,
        structuralHash: "",
        fullHash: "",
        validationErrors: ["Sem ficheiros TCN gerados"],
      };
    }

    const fullText = bundle.cnc.files.map((f) => f.tcn ?? "").join("\n---\n");
    const structuralText = bundle.cnc.files.map((f) => normalizeTcnStructural(f.tcn ?? "")).join("\n---\n");
    const validationErrors: string[] = [];
    for (const file of bundle.cnc.files) {
      if (!file.tcn || !file.tcn.includes("::UNm")) validationErrors.push("TCN sem header ::UNm");
      if (!/^;PIECE/m.test(file.tcn ?? "")) validationErrors.push("TCN sem blocos ;PIECE");
    }

    return {
      ok: validationErrors.length === 0,
      fileCount: bundle.cnc.files.length,
      totalPiecesInTcn: bundle.cnc.files.reduce((acc, f) => acc + countTcnPieces(f.tcn ?? ""), 0),
      structuralHash: hashText(structuralText),
      fullHash: hashText(fullText),
      validationErrors,
    };
  } catch (err) {
    const msg = String(err);
    const matErr = /Matéria-prima|chapa/i.test(msg);
    return {
      ok: matErr,
      fileCount: 0,
      totalPiecesInTcn: 0,
      structuralHash: "",
      fullHash: "",
      validationErrors: matErr ? [msg] : [msg],
    };
  }
}

function runLabelsContract(
  snap: ReturnType<typeof buildFullIndustrialScenario>["snap"],
  layout: CutLayoutResult
): ScenarioMetrics["labelsContract"] {
  const all = buildCutlistItemsForIndustrialExport(snap);
  const sampleItems = all.filter((i) =>
    ["remate", "rodape", "divisorio", "gaveta_frente"].includes(String(i.tipo))
  );
  const pieceKindsSample = Object.fromEntries(
    sampleItems.slice(0, 6).map((i) => [String(i.nome ?? i.tipo), inferIndustrialPieceKind(i)])
  );

  const validation = validateIndustrialLayout(layout, { mode: "full" });
  return {
    pieceKindsSample,
    industrialLayoutValid: validation.ok,
    layoutValidationErrors: validation.errors,
  };
}

type ScenarioDef = {
  id: string;
  description: string;
  mode: "SPM" | "MPM" | "IMPORT";
  run: () => { pieces: CutPiece[]; sheet: SheetDefinition; snap?: ReturnType<typeof buildFullIndustrialScenario>["snap"] };
};

function buildScenarios(): ScenarioDef[] {
  const full = buildFullIndustrialScenario();
  const drawerBox = buildDrawerOnlyBox();
  const mpmSnap = {
    ...full.snap,
    boxes: [full.box, { ...drawerBox, id: "box-mpm-second", nome: "Gaveta_Second" }],
  };

  return [
    {
      id: "TEST_1_IMPORT",
      description: "Projeto real importado (TEST 1.txt) — mix heterogéneo de peças",
      mode: "IMPORT",
      run: () => {
        throw new Error("TEST_1 handled async");
      },
    },
    {
      id: "SPM_FULL_INDUSTRIAL",
      description: "Pipeline industrial SPM — caixa completa (DIV/SEP/gaveta/remate/rodapé)",
      mode: "SPM",
      run: () => {
        const items = buildCutlistItemsForIndustrialExport(full.snap);
        const pieces = cutlistToPieces(items, {
          projectName: full.snap.projectName ?? "Projeto",
          boxes: full.snap.boxes,
        });
        return { pieces, sheet: getSheetDefinitionFromSettings(), snap: full.snap };
      },
    },
    {
      id: "MPM_DUAL_BOX",
      description: "Pipeline industrial MPM — duas caixas (meta-heurísticas + compactor)",
      mode: "MPM",
      run: () => {
        const items = buildCutlistItemsForIndustrialExport(mpmSnap);
        const pieces = cutlistToPieces(items, {
          projectName: mpmSnap.projectName ?? "Projeto",
          boxes: mpmSnap.boxes,
        });
        return { pieces, sheet: getSheetDefinitionFromSettings(), snap: mpmSnap };
      },
    },
  ];
}

async function runScenario(
  def: ScenarioDef,
  layoutOptions: ReturnType<typeof getDefaultCncLayoutOptions>,
  test1Pieces?: CutPiece[],
  test1Sheet?: SheetDefinition
): Promise<ScenarioMetrics> {
  let pieces: CutPiece[];
  let sheet: SheetDefinition;
  let snap: ReturnType<typeof buildFullIndustrialScenario>["snap"] | undefined;

  if (def.id === "TEST_1_IMPORT") {
    if (!test1Pieces || !test1Sheet) throw new Error("TEST_1 não carregado");
    pieces = test1Pieces;
    sheet = test1Sheet;
  } else {
    const ctx = def.run();
    pieces = ctx.pieces;
    sheet = ctx.sheet;
    snap = ctx.snap;
  }

  const t0 = performance.now();
  const layout = runCutLayout(pieces, sheet, layoutOptions);
  const executionMs = Number((performance.now() - t0).toFixed(1));
  const kerf = layoutOptions.kerf_mm ?? 4;
  const layoutMetrics = analyzeLayout(layout, kerf);

  const tcnRegression = runTcnRegression(pieces, sheet, layoutOptions);
  const labelsContract = snap
    ? runLabelsContract(snap, layout)
    : {
        pieceKindsSample: {},
        industrialLayoutValid: validateIndustrialLayout(layout, { mode: "full" }).ok,
        layoutValidationErrors: validateIndustrialLayout(layout, { mode: "full" }).errors,
      };

  return {
    scenarioId: def.id,
    description: def.description,
    pieceCount: pieces.length,
    mode: def.mode,
    executionMs,
    ...layoutMetrics,
    tcnRegression,
    labelsContract,
  };
}

async function runPhase(phase: Phase): Promise<BenchmarkPayload> {
  await mkdir(OUT_DIR, { recursive: true });
  const layoutOptions = getDefaultCncLayoutOptions();
  const scenarios = buildScenarios();

  const raw = await readFile(TEST1_FILE, "utf8");
  const { dl, dh, ds } = parseHeader(raw);
  const test1Pieces = parsePiecesFromTcn(raw, ds);
  const test1Sheet: SheetDefinition = { largura_mm: dl, altura_mm: dh, espessura_mm: ds, materialName: "TEST1" };

  const results: ScenarioMetrics[] = [];
  for (const def of scenarios) {
    results.push(await runScenario(def, layoutOptions, test1Pieces, test1Sheet));
  }

  // Regressão pipeline industrial completo (SPM)
  const full = buildFullIndustrialScenario();
  try {
    buildIndustrialDataForProject(full.snap, { projectName: full.snap.projectName }, layoutOptions);
  } catch {
    // matéria-prima em CI/local — ignorar se esperado
  }

  return {
    phase,
    baselineCommit: BASELINE_COMMIT,
    generatedAt: new Date().toISOString(),
    layoutOptions: "getDefaultCncLayoutOptions()",
    scenarios: results,
  };
}

function delta(a: number, b: number): number {
  return Number((b - a).toFixed(3));
}

function formatPct(n: number): string {
  return `${n.toFixed(2)}%`;
}

async function mergeReports(): Promise<void> {
  const beforeRaw = await readFile(BEFORE_JSON, "utf8");
  const afterRaw = await readFile(AFTER_JSON, "utf8");
  const before = JSON.parse(beforeRaw) as BenchmarkPayload;
  const after = JSON.parse(afterRaw) as BenchmarkPayload;

  const comparisons = before.scenarios.map((b) => {
    const a = after.scenarios.find((s) => s.scenarioId === b.scenarioId)!;
    return {
      scenarioId: b.scenarioId,
      description: b.description,
      mode: b.mode,
      before: b,
      after: a,
      delta: {
        sheets: delta(b.totalSheets, a.totalSheets),
        avgWastePercent: delta(b.avgWastePercent, a.avgWastePercent),
        microGaps: delta(b.totalMicroGapsLt5mm, a.totalMicroGapsLt5mm),
        islands: delta(b.totalInternalIslands, a.totalInternalIslands),
        wasteScatterIndex: delta(b.avgWasteScatterIndex, a.avgWasteScatterIndex),
        utilizationPercent: delta(b.utilizationPercent, a.utilizationPercent),
        executionMs: delta(b.executionMs, a.executionMs),
      },
      tcnStability: {
        structuralHashUnchanged: b.tcnRegression.structuralHash === a.tcnRegression.structuralHash,
        fileCountUnchanged: b.tcnRegression.fileCount === a.tcnRegression.fileCount,
        pieceCountUnchanged: b.tcnRegression.totalPiecesInTcn === a.tcnRegression.totalPiecesInTcn,
        fullHashChanged: b.tcnRegression.fullHash !== a.tcnRegression.fullHash,
        beforeStructuralHash: b.tcnRegression.structuralHash,
        afterStructuralHash: a.tcnRegression.structuralHash,
      },
      labelsStable:
        b.labelsContract.industrialLayoutValid &&
        a.labelsContract.industrialLayoutValid &&
        JSON.stringify(b.labelsContract.pieceKindsSample) === JSON.stringify(a.labelsContract.pieceKindsSample),
    };
  });

  const merged = {
    title: "CutLayout Engine v2 — Benchmark Antes vs Depois",
    baselineCommit: BASELINE_COMMIT,
    beforeGeneratedAt: before.generatedAt,
    afterGeneratedAt: after.generatedAt,
    comparisons,
    summary: {
      scenariosImproved: comparisons.filter(
        (c) =>
          c.delta.sheets < 0 ||
          c.delta.avgWastePercent < 0 ||
          c.delta.microGaps < 0 ||
          c.delta.islands < 0 ||
          c.delta.wasteScatterIndex < 0
      ).length,
      allTcnStructuralStable: comparisons.every((c) => c.tcnStability.structuralHashUnchanged),
      allLabelsValid: comparisons.every((c) => c.labelsStable),
    },
    testArtifacts: {
      beforeJson: BEFORE_JSON,
      afterJson: AFTER_JSON,
      scenarios: ["TEST 1.txt", "SPM_FULL_INDUSTRIAL", "MPM_DUAL_BOX"],
    },
    generatedAt: new Date().toISOString(),
  };

  await writeFile(MERGED_JSON, JSON.stringify(merged, null, 2), "utf8");

  const tableLines = [
    "CUTLAYOUT IMPACT BENCHMARK — ANTES vs DEPOIS",
    `Baseline (antes): commit ${BASELINE_COMMIT}`,
    `Antes medido: ${before.generatedAt}`,
    `Depois medido: ${after.generatedAt}`,
    "",
    "Cenário | Modo | Chapas Δ | Desperdício médio Δ | Micro-gaps Δ | Ilhas Δ | Scatter desperdício Δ | Utilização Δ | Tempo Δ (ms)",
    "---",
  ];

  for (const c of comparisons) {
    tableLines.push(
      [
        c.scenarioId,
        c.mode,
        c.delta.sheets,
        `${c.delta.avgWastePercent} pp`,
        c.delta.microGaps,
        c.delta.islands,
        c.delta.wasteScatterIndex,
        `${c.delta.utilizationPercent} pp`,
        c.delta.executionMs,
      ].join(" | ")
    );
  }

  const observations: string[] = [];
  for (const c of comparisons) {
    if (c.delta.wasteScatterIndex < 0) {
      observations.push(
        `${c.scenarioId}: desperdício mais concentrado (scatter ${c.before.avgWasteScatterIndex} → ${c.after.avgWasteScatterIndex}).`
      );
    }
    if (c.delta.microGaps < 0) {
      observations.push(`${c.scenarioId}: micro-gaps <5mm reduzidos (${c.before.totalMicroGapsLt5mm} → ${c.after.totalMicroGapsLt5mm}).`);
    }
    if (c.delta.islands < 0) {
      observations.push(`${c.scenarioId}: ilhas internas reduzidas (${c.before.totalInternalIslands} → ${c.after.totalInternalIslands}).`);
    }
    if (c.delta.sheets < 0) {
      observations.push(`${c.scenarioId}: ${Math.abs(c.delta.sheets)} chapa(s) poupada(s).`);
    }
    if (c.delta.sheets === 0 && c.delta.avgWastePercent < -0.5) {
      observations.push(`${c.scenarioId}: mesma chapa count, mas densidade superior (desperdício médio ↓).`);
    }
  }

  const regressions = comparisons.filter(
    (c) => !c.labelsStable || !c.after.tcnRegression.ok
  );
  const edgeCases = comparisons.filter(
    (c) => c.delta.executionMs > 500 || (c.delta.sheets === 0 && c.delta.avgWastePercent >= 0)
  );

  const txt = [
    ...tableLines,
    "",
    "DETALHE ANTES → DEPOIS:",
    ...comparisons.flatMap((c) => [
      "",
      `## ${c.scenarioId} (${c.mode})`,
      `Peças: ${c.before.pieceCount}`,
      `Chapas: ${c.before.totalSheets} → ${c.after.totalSheets}`,
      `Desperdício médio/chapa: ${formatPct(c.before.avgWastePercent)} → ${formatPct(c.after.avgWastePercent)}`,
      `Micro-gaps (<5mm): ${c.before.totalMicroGapsLt5mm} → ${c.after.totalMicroGapsLt5mm}`,
      `Ilhas internas: ${c.before.totalInternalIslands} → ${c.after.totalInternalIslands}`,
      `Scatter desperdício: ${c.before.avgWasteScatterIndex} → ${c.after.avgWasteScatterIndex} (↓ = mais concentrado numa zona)`,
      `Utilização: ${formatPct(c.before.utilizationPercent)} → ${formatPct(c.after.utilizationPercent)}`,
      `Tempo: ${c.before.executionMs}ms → ${c.after.executionMs}ms`,
      `Estratégia: ${c.before.selectedStrategy ?? "?"} → ${c.after.selectedStrategy ?? "?"}`,
      `TCN estrutural hash: ${c.tcnStability.beforeStructuralHash} → ${c.tcnStability.afterStructuralHash} (igual=${c.tcnStability.structuralHashUnchanged})`,
      `TCN full hash mudou (coords layout): ${c.tcnStability.fullHashChanged}`,
    ]),
    "",
    "OBSERVAÇÕES:",
    ...(observations.length ? observations.map((o) => `- ${o}`) : ["- Sem melhorias métricas claras nestes cenários; motor estável."]),
    "",
    "REGRESSÃO SPM/MPM/PDF:",
    `- Contrato industrial (validateIndustrialLayout): ${merged.summary.allLabelsValid ? "OK em todos os cenários" : "FALHA"}`,
    `- Hash TCN estrutural (sem coordenadas): ${merged.summary.allTcnStructuralStable ? "estável" : "alterado — rever"}`,
    `- Coordenadas TCN (full hash): esperado mudar quando o layout melhora`,
    ...(regressions.length
      ? regressions.map((c) => `- ATENÇÃO ${c.scenarioId}: ${c.after.labelsContract.layoutValidationErrors.join("; ")}`)
      : []),
    "",
    "CASOS LIMITE:",
    ...(edgeCases.length
      ? edgeCases.map(
          (c) =>
            `- ${c.scenarioId}: tempo +${c.delta.executionMs}ms ou ganho de densidade ainda marginal (desperdício Δ=${c.delta.avgWastePercent}pp).`
        )
      : ["- Nenhum caso crítico identificado nesta amostra."]),
    "",
    "Ficheiros:",
    `- ${BEFORE_JSON}`,
    `- ${AFTER_JSON}`,
    `- ${MERGED_JSON}`,
    `- ${TEST1_FILE}`,
  ].join("\n");

  const md = `# Relatório técnico — CutLayout Impact Benchmark

## Objetivo
Validar impacto das melhorias de sorting, skyline, shelf, compactação e scoring **sem novas heurísticas**.

## Metodologia
- **Antes**: \`src/core/cutlayout/\` no commit \`${BASELINE_COMMIT}\` (pré-optimizações Fase A).
- **Depois**: estado actual do motor (inclui melhorias incrementais uncommitted).
- **Opções**: \`getDefaultCncLayoutOptions()\` (produção SPM/MPM).
- **Cenários**: TEST 1.txt, SPM caixa completa, MPM 2 caixas.

## Tabela comparativa

| Cenário | Modo | Chapas (antes→depois) | Desperdício médio | Micro-gaps | Ilhas | Scatter | Utilização | Tempo (ms) |
|---------|------|------------------------|-------------------|------------|-------|---------|------------|------------|
${comparisons
  .map(
    (c) =>
      `| ${c.scenarioId} | ${c.mode} | ${c.before.totalSheets}→${c.after.totalSheets} (${c.delta.sheets >= 0 ? "+" : ""}${c.delta.sheets}) | ${formatPct(c.before.avgWastePercent)}→${formatPct(c.after.avgWastePercent)} | ${c.before.totalMicroGapsLt5mm}→${c.after.totalMicroGapsLt5mm} | ${c.before.totalInternalIslands}→${c.after.totalInternalIslands} | ${c.before.avgWasteScatterIndex}→${c.after.avgWasteScatterIndex} | ${formatPct(c.before.utilizationPercent)}→${formatPct(c.after.utilizationPercent)} | ${c.before.executionMs}→${c.after.executionMs} |`
  )
  .join("\n")}

## Observações
${observations.map((o) => `- ${o}`).join("\n") || "- Sem deltas significativos nesta amostra."}

## Regressão SPM / MPM / PDF-etiquetas
- **TCN estrutural** (peças, dimensões, headers — sem XY): ${merged.summary.allTcnStructuralStable ? "✅ estável" : "⚠️ divergência"}
- **Coordenadas TCN**: alteração esperada quando o nesting optimiza posições (full hash muda).
- **Contrato industrial / etiquetas**: ${merged.summary.allLabelsValid ? "✅ válido antes e depois" : "⚠️ validação falhou"}

## Casos limite
${edgeCases.map((c) => `- **${c.scenarioId}**: tempo +${c.delta.executionMs}ms ou ganho ainda marginal.`).join("\n") || "- Nenhum bloqueador identificado."}

## Artefactos
- \`${BEFORE_JSON}\`
- \`${AFTER_JSON}\`
- \`${MERGED_JSON}\`
- \`${TEST1_FILE}\`
`;

  await writeFile(REPORT_TXT, txt, "utf8");
  await writeFile(REPORT_MD, md, "utf8");
  console.log("Relatório merge:", MERGED_JSON);
  console.log("Relatório TXT:", REPORT_TXT);
  console.log("Relatório MD:", REPORT_MD);
}

async function main(): Promise<void> {
  const { phase } = parseArgs();
  if (phase === "merge") {
    await mergeReports();
    return;
  }

  const payload = await runPhase(phase);
  const out = phase === "before" ? BEFORE_JSON : AFTER_JSON;
  await writeFile(out, JSON.stringify(payload, null, 2), "utf8");
  console.log(`Fase ${phase} gravada em`, out);
  for (const s of payload.scenarios) {
    console.log(
      `[${s.scenarioId}] chapas=${s.totalSheets} waste=${s.avgWastePercent}% gaps=${s.totalMicroGapsLt5mm} ilhas=${s.totalInternalIslands} scatter=${s.avgWasteScatterIndex} ${s.executionMs}ms`
    );
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import * as THREE from "three";
import type { PanelMaterialOptions } from "./BoxMaterialApplier";
import type { BoxModel, BoxOptions, BoxPanelLayoutSpecs } from "./BoxBuilder";
import type { DoorSpec } from "./DoorFactory";
import type { DrawerSpec } from "./DrawerFactory";
import { resolveDrawerFrontMaterialId } from "../../core/drawers/drawerFrontMaterial";
import type { DoorLayerItem, DrawerLayerItem } from "../../models/BoxLayers";
import type { TechnicalDrillHole } from "../../core/types";
import { isPiBaseCabinetId } from "../../data/moveisUnificados/pi/models";
import {
  computeWardrobeLocalLayout,
  getWardrobeGroupFromBaseCabinetId,
  hasWardrobeLowerDrawers,
} from "../../core/wardrobe/wardrobeRules";
import { getDivSepMeshSpecs } from "../../core/divSep/visualSpecs";
import { resolveNoBackPanelFromOptions } from "../../core/box/backPanelFlags";
import { DISABLE_DRAWER_RENDERING } from "./drawerRenderingFlags";
import type { PanelType } from "./PanelFactory";
import {
  filterDivisorViewerShelfHoles,
  resolveDivisorViewerDrillHoles,
  resolveDivisorViewerPanelType,
} from "../viewer-engine/drill/divSepViewerDrillLookup";

type BoxUpdaterDeps = {
  resolveDimensions: (_options?: BoxOptions) => { width: number; height: number; depth: number };
  getPanelSpecs: (_width: number, _height: number, _depth: number) => BoxPanelLayoutSpecs;
  getShelfSpecs: (
    _width: number,
    _height: number,
    _depth: number,
    _shelves?: number,
    _opts?: BoxOptions
  ) => Array<{ size: [number, number, number]; pos: [number, number, number] }>;
  panelFactory: {
    createPanel: (
      _width: number,
      _height: number,
      _depth: number,
      _name: string,
      _panelType: PanelType,
      _options?: PanelMaterialOptions | null
    ) => THREE.Mesh;
    updatePanelGeometry: (_mesh: THREE.Mesh, _w: number, _h: number, _d: number) => void;
  };
  getFallbackPBRMaterial: () => THREE.Material;
  applyDrillHolesToPanelGeometry: (_panel: THREE.Mesh, _panelType: PanelType, _holes: TechnicalDrillHole[] | undefined) => void;
  buildDoorSpecs: (_items: DoorLayerItem[]) => DoorSpec[];
  buildDrawerSpecs: (
    _items: DrawerLayerItem[],
    _options?: { showDrillingMarkers?: boolean; profundidadeUtilM?: number; profundidadeExternaM?: number }
  ) => DrawerSpec[];
  getDoorSpecFingerprint: (_spec: DoorSpec, _materialName?: string) => string;
  getDrawerSpecFingerprint: (_spec: DrawerSpec, _materialName?: string) => string;
  getDrawerStructureFingerprint: (
    _spec: DrawerSpec,
    _materials?: import("./DrawerFactory").DrawerStructureMaterials | string
  ) => string;
  getDrawerMotionKey: (_spec: Pick<DrawerSpec, "isOpen" | "pullDistanceM">) => string;
  syncDrawerLayerMotion: (_drawerLayerGroup: THREE.Object3D, _spec: DrawerSpec) => boolean;
  createDoorObject: (_spec: DoorSpec, _material: THREE.Material, _doorHoles?: TechnicalDrillHole[]) => THREE.Object3D;
  createDrawerObject: (
    _spec: DrawerSpec,
    _materials: import("./DrawerFactory").DrawerObjectMaterials | THREE.Material
  ) => THREE.Object3D;
  getMaterialForOfficialId: (_idOrLabel: string) => THREE.Material;
  getDefaultOfficialMaterialId: () => string;
  thicknessM: number;
  panelNames: readonly string[];
  lastDimsKey: string;
  doorSpecFingerprintKey: string;
  drawerSpecFingerprintKey: string;
};

export function dimensionsEqual(a: { width: number; height: number; depth: number }, b: { width: number; height: number; depth: number }): boolean {
  return Math.abs(a.width - b.width) < 1e-9 && Math.abs(a.height - b.height) < 1e-9 && Math.abs(a.depth - b.depth) < 1e-9;
}

const LATERAL_PANEL_NAMES = ["left", "right"] as const;

function disposePanelGeometry(panel: THREE.Mesh): void {
  panel.traverse((child) => {
    if (child instanceof THREE.Mesh && child.geometry) {
      child.geometry.dispose();
    }
  });
}

/** Mantém um único mesh estrutural por nome; remove duplicados do grupo. */
function dedupeStructuralPanel(group: THREE.Group, panelName: string): THREE.Mesh | undefined {
  const matches = group.children.filter(
    (c): c is THREE.Mesh => c instanceof THREE.Mesh && c.name === panelName
  );
  if (matches.length === 0) return undefined;
  const [keeper, ...duplicates] = matches;
  for (const duplicate of duplicates) {
    group.remove(duplicate);
    disposePanelGeometry(duplicate);
  }
  return keeper;
}

function applyLateralPanelLayout(
  panel: THREE.Mesh,
  panelName: (typeof LATERAL_PANEL_NAMES)[number],
  spec: { size: readonly [number, number, number]; pos: readonly [number, number, number] },
  panelFactory: BoxUpdaterDeps["panelFactory"]
): void {
  panelFactory.updatePanelGeometry(panel, spec.size[0], spec.size[1], spec.size[2]);
  panel.position.set(spec.pos[0], spec.pos[1], spec.pos[2]);
  panel.rotation.y = panelName === "right" ? Math.PI : 0;
  panel.rotation.z = 0;
  delete (panel.userData as Record<string, unknown>).explodedBasePosition;
  panel.updateMatrix();
}

function ensureLateralPanel(
  group: THREE.Group,
  panelName: (typeof LATERAL_PANEL_NAMES)[number],
  spec: { size: readonly [number, number, number]; pos: readonly [number, number, number] },
  mat: THREE.Material,
  deps: BoxUpdaterDeps
): THREE.Mesh {
  let panel = dedupeStructuralPanel(group, panelName);
  if (!panel) {
    panel = deps.panelFactory.createPanel(
      spec.size[0],
      spec.size[1],
      spec.size[2],
      panelName,
      panelName,
      { singleMaterial: mat }
    );
    group.add(panel);
  }
  applyLateralPanelLayout(panel, panelName, spec, deps.panelFactory);
  return panel;
}

export function updateBoxModelWithDeps(model: BoxModel, options: BoxOptions | undefined, deps: BoxUpdaterDeps): BoxModel {
  const opts = options ?? {};
  const { width, height, depth } = deps.resolveDimensions(opts);
  const material = opts.material ?? model.panels.left.material;
  const specs = deps.getPanelSpecs(width, height, depth);
  const skipBack = resolveNoBackPanelFromOptions(opts);
  const panelKeys: (keyof typeof model.panels)[] = ["left", "right", "top", "bottom", "back"];
  panelKeys.forEach((key) => {
    if (key === "back" && skipBack) {
      if (model.panels.back.parent) model.panels.back.parent.remove(model.panels.back);
      return;
    }
    const [wx, hy, dz] = specs[key].size;
    const [px, py, pz] = specs[key].pos;
    deps.panelFactory.updatePanelGeometry(model.panels[key], wx, hy, dz);
    model.panels[key].position.set(px, py, pz);
    if (key === "right") {
      model.panels[key].rotation.y = Math.PI;
      // Manter Y consistente entre porta e lateral: não inverter no eixo Z.
      model.panels[key].rotation.z = 0;
    } else {
      model.panels[key].rotation.y = 0;
      model.panels[key].rotation.z = 0;
    }
  });
  if (opts.material != null) {
    Object.values(model.panels).forEach((panel) => {
      (panel as THREE.Mesh).material = material as THREE.Material;
    });
  }
  model.dimensions = { width, height, depth, thickness: deps.thicknessM };
  return model;
}

export function updateBoxGroupWithDeps(group: THREE.Group, options: BoxOptions | undefined, deps: BoxUpdaterDeps): { width: number; height: number; depth: number } {
  const opts = options ?? {};
  const { width, height, depth } = deps.resolveDimensions(opts);
  const dims = { width, height, depth };
  const lastDims = (group.userData as Record<string, unknown>)[deps.lastDimsKey] as { width: number; height: number; depth: number } | undefined;
  const dimensionsUnchanged = lastDims != null && dimensionsEqual(lastDims, dims);
  (group.userData as Record<string, unknown>)[deps.lastDimsKey] = dims;

  const specs = deps.getPanelSpecs(width, height, depth);
  const skipBack = resolveNoBackPanelFromOptions(opts);
  const baseMaterial = group.children[0] instanceof THREE.Mesh ? (group.children[0] as THREE.Mesh).material : deps.getFallbackPBRMaterial();
  const mat = Array.isArray(baseMaterial) ? baseMaterial[0] : baseMaterial;

  let backPanel = group.children.find((c) => c instanceof THREE.Mesh && c.name === "back") as THREE.Mesh | undefined;
  if (skipBack) {
    if (backPanel) group.remove(backPanel);
    backPanel = undefined;
  } else if (!backPanel) {
    backPanel = deps.panelFactory.createPanel(
      specs.back.size[0],
      specs.back.size[1],
      specs.back.size[2],
      "back",
      "back",
      { singleMaterial: mat as THREE.Material }
    );
    group.add(backPanel);
  }

  const drillMap = opts.drillMarkersByPanel ?? { cima: [], fundo: [], lateral_esquerda: [], lateral_direita: [], porta: [], frente_fixa: [] };
  const shelfCountForDrill = Math.max(0, Math.floor(opts.shelves ?? 0));
  // Roupeiro: prateleiras existem na zona superior mesmo que existam gavetas na zona inferior.
  const useLateralShelfHoles = shelfCountForDrill > 0;
  const hasLateralDrillMarkers =
    (drillMap.lateral_esquerda?.length ?? 0) > 0 || (drillMap.lateral_direita?.length ?? 0) > 0;
  const forcePiLateralDrillGeometry = isPiBaseCabinetId(opts.baseCabinetId);
  const applyLateralDrillHoles =
    forcePiLateralDrillGeometry || hasLateralDrillMarkers || useLateralShelfHoles;
  const lateralLeftHoles = applyLateralDrillHoles
    ? drillMap.lateral_esquerda
    : [];
  const lateralRightHoles = applyLateralDrillHoles
    ? drillMap.lateral_direita
    : [];

  const leftPanel = ensureLateralPanel(group, "left", specs.left, mat as THREE.Material, deps);
  const rightPanel = ensureLateralPanel(group, "right", specs.right, mat as THREE.Material, deps);

  if (!dimensionsUnchanged) {
    for (const panelName of deps.panelNames) {
      if (panelName === "back" && skipBack) continue;
      if (panelName === "left" || panelName === "right") continue;
      const child = group.children.find((c) => c.name === panelName);
      if (!(child instanceof THREE.Mesh) || !child.geometry) continue;
      const spec = specs[panelName as keyof BoxPanelLayoutSpecs];
      if (!spec) continue;
      deps.panelFactory.updatePanelGeometry(child, spec.size[0], spec.size[1], spec.size[2]);
      child.position.set(spec.pos[0], spec.pos[1], spec.pos[2]);
      child.rotation.y = 0;
      child.rotation.z = 0;
      delete (child.userData as Record<string, unknown>).explodedBasePosition;
      child.updateMatrix();
    }
  }

  const topPanel = group.children.find((c) => c instanceof THREE.Mesh && c.name === "top") as THREE.Mesh | undefined;
  const bottomPanel = group.children.find((c) => c instanceof THREE.Mesh && c.name === "bottom") as THREE.Mesh | undefined;
  if (topPanel) deps.applyDrillHolesToPanelGeometry(topPanel, "top", drillMap.cima);
  if (bottomPanel) deps.applyDrillHolesToPanelGeometry(bottomPanel, "bottom", drillMap.fundo);
  if (leftPanel) deps.applyDrillHolesToPanelGeometry(leftPanel, "left", lateralLeftHoles);
  if (rightPanel) deps.applyDrillHolesToPanelGeometry(rightPanel, "right", lateralRightHoles);

  const ffPanel = group.children.find(
    (c) => c instanceof THREE.Mesh && c.name === "frente-fixa"
  ) as THREE.Mesh | undefined;
  const ffHoles = drillMap.frente_fixa ?? [];
  const existingFfId =
    typeof (ffPanel?.userData as { frenteFixaMaterialId?: string } | undefined)?.frenteFixaMaterialId ===
    "string"
      ? String((ffPanel!.userData as { frenteFixaMaterialId?: string }).frenteFixaMaterialId).trim()
      : "";
  // Só aplica override explícito do layer. Vazio/undefined → preservar mesh (nunca módulo).
  const ffExplicitFromOpts =
    typeof opts.frenteFixaMaterialId === "string" && opts.frenteFixaMaterialId.trim().length > 0
      ? opts.frenteFixaMaterialId.trim()
      : "";
  const ffMaterialId = ffExplicitFromOpts || existingFfId;
  if (ffPanel && ffMaterialId) {
    const ffUserData = ffPanel.userData as Record<string, unknown>;
    if (ffUserData.frenteFixaMaterialId !== ffMaterialId) {
      const ffMat = deps.getMaterialForOfficialId(ffMaterialId) as THREE.Material;
      ffPanel.material = ffMat;
      ffUserData.frenteFixaMaterialId = ffMaterialId;
    }
    if (ffHoles.length > 0) {
      deps.applyDrillHolesToPanelGeometry(ffPanel, "front", ffHoles);
    }
  } else if (ffPanel && ffHoles.length > 0) {
    deps.applyDrillHolesToPanelGeometry(ffPanel, "front", ffHoles);
  }

  const doorLayerItems = Array.isArray(opts.doorLayerItems) ? opts.doorLayerItems : [];
  const doorSpecs = deps.buildDoorSpecs(doorLayerItems);
  const requiredDoorIds = new Set(doorSpecs.map((s) => s.id));
  for (const c of group.children.filter((c) => c.name.startsWith("door-layer-"))) {
    const id = c.name.replace("door-layer-", "");
    if (!requiredDoorIds.has(id)) group.remove(c);
  }
  doorSpecs.forEach((spec, doorIndex) => {
    const item = doorLayerItems[doorIndex];
    const materialName = item?.material ?? item?.materialId ?? deps.getDefaultOfficialMaterialId();
    const newFingerprint = deps.getDoorSpecFingerprint(spec, materialName);
    const existingDoor = group.children.find((c) => c.name === `door-layer-${spec.id}`) as THREE.Object3D | undefined;
    const doorUserData = existingDoor?.userData as Record<string, unknown> | undefined;
    if (doorUserData?.[deps.doorSpecFingerprintKey] === newFingerprint) return;
    if (existingDoor) group.remove(existingDoor);
    const doorMaterial = deps.getMaterialForOfficialId(materialName);
    const newDoor = deps.createDoorObject(spec, doorMaterial as THREE.Material, drillMap.portaPerDoor?.[doorIndex] ?? drillMap.porta);
    (newDoor.userData as Record<string, unknown>)[deps.doorSpecFingerprintKey] = newFingerprint;
    group.add(newDoor);
  });

  const drawerLayerItems = Array.isArray(opts.drawerLayerItems) ? opts.drawerLayerItems : [];
  if (DISABLE_DRAWER_RENDERING) {
    for (const c of group.children.filter((child) => child.name.startsWith("drawer-layer-"))) {
      group.remove(c);
    }
  } else {
    const drawerSpecs = deps.buildDrawerSpecs(drawerLayerItems, {
      showDrillingMarkers: opts.showDrawerDrilling === true,
      profundidadeUtilM: opts.carcassDepthM ?? depth,
      profundidadeExternaM: opts.layoutDepthM,
    });
    const requiredDrawerIds = new Set(drawerSpecs.map((s) => s.id));
    for (const c of group.children.filter((c) => c.name.startsWith("drawer-layer-"))) {
      const id = c.name.replace("drawer-layer-", "");
      if (!requiredDrawerIds.has(id)) group.remove(c);
    }
    drawerSpecs.forEach((spec, drawerIndex) => {
      const drawerItem = drawerLayerItems[drawerIndex];
      const defaultMaterialId = deps.getDefaultOfficialMaterialId();
      const bodyMaterialId =
        typeof opts.materialName === "string" && opts.materialName.trim().length > 0
          ? opts.materialName.trim()
          : defaultMaterialId;
      const explicitFrontMaterialId = resolveDrawerFrontMaterialId(drawerItem, "").trim();
      const existingDrawer = group.children.find((c) => c.name === `drawer-layer-${spec.id}`) as THREE.Object3D | undefined;
      let preservedFrontId = "";
      if (existingDrawer) {
        existingDrawer.traverse((child) => {
          if (preservedFrontId) return;
          if (!(child instanceof THREE.Mesh)) return;
          const ud = child.userData as { drawerPart?: string; drawerFrontMaterialId?: string };
          if (ud.drawerPart === "front" && ud.drawerFrontMaterialId?.trim()) {
            preservedFrontId = ud.drawerFrontMaterialId.trim();
          }
        });
      }
      // Explicito do layer → mesh existente → nunca matéria do módulo no fingerprint da frente.
      const frontIdentityId = explicitFrontMaterialId || preservedFrontId || "__unset__";
      const frontPaintId = explicitFrontMaterialId || preservedFrontId || defaultMaterialId;
      const structureFingerprint = deps.getDrawerStructureFingerprint(spec, {
        frontMaterial: frontIdentityId,
        bodyMaterial: bodyMaterialId,
      });
      const motionKey = deps.getDrawerMotionKey(spec);
      const drawerUserData = existingDrawer?.userData as Record<string, unknown> | undefined;
      if (existingDrawer && drawerUserData?.[deps.drawerSpecFingerprintKey] === structureFingerprint) {
        if (drawerUserData?.drawerMotionKey !== motionKey) {
          deps.syncDrawerLayerMotion(existingDrawer, spec);
          drawerUserData.drawerMotionKey = motionKey;
        }
        // Garantir userData da frente após load sem rebuild.
        if (explicitFrontMaterialId) {
          existingDrawer.traverse((child) => {
            if (!(child instanceof THREE.Mesh)) return;
            const ud = child.userData as { drawerPart?: string; drawerFrontMaterialId?: string };
            if (ud.drawerPart === "front") {
              ud.drawerFrontMaterialId = explicitFrontMaterialId;
            }
          });
        }
        return;
      }
      if (existingDrawer) group.remove(existingDrawer);
      const frontMaterial = deps.getMaterialForOfficialId(frontPaintId);
      const bodyMaterial = deps.getMaterialForOfficialId(bodyMaterialId);
      const newDrawer = deps.createDrawerObject(spec, {
        front: frontMaterial as THREE.Material,
        body: bodyMaterial as THREE.Material,
        frontMaterialId: explicitFrontMaterialId || preservedFrontId || undefined,
      });
      const newUserData = newDrawer.userData as Record<string, unknown>;
      newUserData[deps.drawerSpecFingerprintKey] = structureFingerprint;
      newUserData.drawerMotionKey = motionKey;
      group.add(newDrawer);
      newDrawer.traverse((child) => {
        if (
          child instanceof THREE.Mesh &&
          (child as THREE.Mesh & { userData: { drawerPart?: string } }).userData?.drawerPart === "front"
        ) {
          const idToStore = explicitFrontMaterialId || preservedFrontId;
          if (idToStore) {
            child.userData.drawerFrontMaterialId = idToStore;
          }
        }
      });
    });
  }

  const shelfCount = Math.max(0, Math.floor(opts.shelves ?? 0));
  const shelfSpecs = deps.getShelfSpecs(width, height, depth, shelfCount, opts);
  group.children.filter((c) => /^shelf-\d+$/.test(c.name)).forEach((obj) => group.remove(obj));
  shelfSpecs.forEach((spec, i) => {
    const shelfMat = mat as THREE.Material;
    const mesh = deps.panelFactory.createPanel(spec.size[0], spec.size[1], spec.size[2], `shelf-${i}`, "top", { singleMaterial: shelfMat });
    mesh.position.set(spec.pos[0], spec.pos[1], spec.pos[2]);
    mesh.userData.shelfIndex = i;
    group.add(mesh);
  });

  group.children.filter((c) => c.name.startsWith("divsep-")).forEach((obj) => group.remove(obj));
  const divSepBoxLike = {
    dimensoes: {
      largura: width * 1000,
      altura: height * 1000,
      profundidade: (opts.layoutDepthM ?? depth) * 1000,
    },
    espessura: deps.thicknessM * 1000,
    profundidadeExterna: (opts.layoutDepthM ?? depth) * 1000,
    portaTipo: opts.portaTipo,
    costaAtiva: opts.costaAtiva,
    doorsLayer: opts.doorLayerItems,
    drawersLayer: opts.drawerLayerItems,
    gavetas: opts.gavetas,
    divisores: opts.divisores ?? [],
    separadores: opts.separadores ?? [],
  };
  let divSepDivIndex = 0;
  getDivSepMeshSpecs(divSepBoxLike, width, height, depth, deps.thicknessM).forEach((spec) => {
    const isDivMesh = spec.name.startsWith("divsep-div-");
    const isSepMesh = spec.name.startsWith("divsep-sep-");
    let meshPanelType: PanelType = "top";
    let divItemId = "";
    let divIndex = -1;
    let divShelfHoles: TechnicalDrillHole[] = [];
    if (isDivMesh) {
      divItemId = spec.name.slice("divsep-div-".length);
      divIndex = divSepDivIndex;
      divSepDivIndex += 1;
      const lado = opts.divisores?.[divIndex]?.prateleiraLado;
      meshPanelType = resolveDivisorViewerPanelType(lado);
      divShelfHoles = filterDivisorViewerShelfHoles(
        resolveDivisorViewerDrillHoles(drillMap.divisoresById, {
          divItemId,
          divIndex,
          panelIds: opts.panelIds,
        })
      );
    }

    const mesh = deps.panelFactory.createPanel(
      spec.size[0],
      spec.size[1],
      spec.size[2],
      spec.name,
      meshPanelType,
      { singleMaterial: mat as THREE.Material }
    );
    mesh.position.set(spec.pos[0], spec.pos[1], spec.pos[2]);
    mesh.userData.divSepId = spec.name;
    mesh.userData.panelType = meshPanelType;
    mesh.userData.authoredSize = [spec.size[0], spec.size[1], spec.size[2]] as [number, number, number];
    if (isSepMesh) {
      mesh.userData.divSepKind = "sep";
      const sepItemId = spec.name.slice("divsep-sep-".length);
      mesh.userData.divSepItemId = sepItemId;
      const sepHoles = drillMap.separadoresById?.[sepItemId];
      if (sepHoles?.length) {
        deps.applyDrillHolesToPanelGeometry(mesh, "top", sepHoles);
      }
    } else if (isDivMesh) {
      mesh.userData.divSepKind = "div";
      mesh.userData.divSepItemId = divItemId;
      mesh.userData.divSepIndex = divIndex;
      // DIV: só marcadores de overlay (sem CSG). Sem prateleiras → array vazio.
      mesh.userData.divViewerHoles = divShelfHoles;
    }
    group.add(mesh);
  });

  // Roupeiro (H/J): reconstruir divisores e varões de cabides na renderização incremental.
  const wardrobeGroup = getWardrobeGroupFromBaseCabinetId(opts.baseCabinetId);
  if (wardrobeGroup && wardrobeGroup !== "T") {
    group.children
      .filter((c) => c.name.startsWith("wardrobe-divider-") || c.name.startsWith("wardrobe-rail-"))
      .forEach((c) => group.remove(c));

    const feetHeightMm = Math.max(40, opts.feetHeight ?? (opts.pe_cm ?? 10) * 10);
    const widthMm = width * 1000;
    const heightMm = height * 1000;
    const depthMm = depth * 1000;

    const layout = computeWardrobeLocalLayout({
      baseCabinetId: opts.baseCabinetId,
      widthMm,
      heightMm,
      depthMm,
      feetHeightMm,
    });

    const dividerMat = mat as THREE.Material;

    if (layout.horizontalDividerCenterY_mm != null) {
      const dividerH = new THREE.Mesh(
        new THREE.BoxGeometry(width, deps.thicknessM, depth),
        dividerMat
      );
      dividerH.name = "wardrobe-divider-horizontal";
      dividerH.position.set(0, layout.horizontalDividerCenterY_mm / 1000, 0);
      group.add(dividerH);
    }

    if (layout.verticalDividerEnabled) {
      const dividerV = new THREE.Mesh(
        new THREE.BoxGeometry(deps.thicknessM, height, depth),
        dividerMat
      );
      dividerV.name = "wardrobe-divider-vertical";
      dividerV.position.set((layout.verticalDividerCenterX_mm ?? 0) / 1000, 0, 0);
      group.add(dividerV);
    }

    const hasDrawersLower = hasWardrobeLowerDrawers(opts.baseCabinetId);
    const railThicknessM = 6 / 1000;
    const railRadiusM = Math.max(0.001, railThicknessM / 2);
    const railZ = layout.shelfAndRailCenterZ_mm / 1000;
    const railY = layout.lowerCabideCenterY_mm != null ? layout.lowerCabideCenterY_mm / 1000 : -height / 4;

    const createRail = (name: string, x: number, lengthM: number) => {
      const cyl = new THREE.Mesh(
        new THREE.CylinderGeometry(railRadiusM, railRadiusM, Math.max(0.001, lengthM), 12),
        dividerMat
      );
      cyl.name = name;
      cyl.position.set(x, railY, railZ);
      cyl.rotation.z = Math.PI / 2;
      group.add(cyl);
    };

    if (layout.verticalDividerEnabled) {
      const leftX = layout.leftCompartmentCenterX_mm / 1000;
      const rightX = layout.rightCompartmentCenterX_mm / 1000;
      const lenLeft = layout.railWidthPerSide_mm / 1000;
      const lenRight = layout.railWidthPerSide_mm / 1000;
      if (hasDrawersLower) {
        createRail("wardrobe-rail-left", leftX, lenLeft);
      } else {
        createRail("wardrobe-rail-left", leftX, lenLeft);
        createRail("wardrobe-rail-right", rightX, lenRight);
      }
    } else {
      createRail("wardrobe-rail-center", 0, layout.railWidthFull_mm / 1000);
    }
  } else {
    group.children
      .filter((c) => c.name.startsWith("wardrobe-divider-") || c.name.startsWith("wardrobe-rail-"))
      .forEach((c) => group.remove(c));
  }

  group.updateMatrixWorld(true);
  return { width, height, depth };
}

export function updateBoxGeometryWithDeps(mesh: THREE.Mesh, options: BoxOptions | undefined, deps: BoxUpdaterDeps): { width: number; height: number; depth: number } {
  const { width, height, depth } = deps.resolveDimensions(options);
  mesh.geometry.dispose();
  const geometry = new THREE.BoxGeometry(width, height, depth);
  if (!geometry.attributes.uv2 && geometry.attributes.uv) geometry.setAttribute("uv2", geometry.attributes.uv);
  mesh.geometry = geometry;
  return { width, height, depth };
}

import * as THREE from "three";
import type { ViewerBoxEntry } from "./types";
import {
  runWithAllLayoutBoundsProxiesVisible,
  runWithLayoutBoundsProxiesVisible,
} from "./box/boxAabbUtils";

export type ViewerCoreCameraOpsDeps = {
  cameraManager: {
    camera: any;
    setTarget: (x: number, y: number, z: number) => void;
    getTarget: () => THREE.Vector3;
  };
  controls: { controls: { target: THREE.Vector3 }; update: () => void } | null;
  boxes: Map<string, ViewerBoxEntry>;
  cameraViewPreset: string | null;
  boundingBox: THREE.Box3;
  center: THREE.Vector3;
  boxSingle: THREE.Box3;
  size: THREE.Vector3;
  projScreenMatrix: THREE.Matrix4;
  frustum: THREE.Frustum;
};

export function syncCameraTargetImpl(
  deps: ViewerCoreCameraOpsDeps,
  center: THREE.Vector3,
  options?: { updateLookAt?: boolean }
): void {
  const updateLookAt = options?.updateLookAt !== false;
  if (updateLookAt) {
    deps.cameraManager.setTarget(center.x, center.y, center.z);
  } else {
    deps.cameraManager.getTarget().copy(center);
  }
  if (deps.controls) {
    deps.controls.controls.target.copy(center);
    deps.controls.update();
  }
}

export function updateCameraTargetImpl(deps: ViewerCoreCameraOpsDeps): void {
  if (deps.boxes.size === 0) {
    if (deps.cameraViewPreset == null) {
      syncCameraTargetImpl(deps, new THREE.Vector3(0, 0, 0));
    }
    return;
  }

  const camBboxRoots = Array.from(deps.boxes.values()).map((e) => e.mesh);
  runWithAllLayoutBoundsProxiesVisible(camBboxRoots, () => {
    deps.boundingBox.makeEmpty();
    deps.boxes.forEach((entry) => {
      deps.boundingBox.expandByObject(entry.mesh);
    });
  });

  deps.boundingBox.getCenter(deps.center);

  if (deps.cameraViewPreset != null) {
    syncCameraTargetImpl(deps, deps.center, { updateLookAt: false });
    return;
  }

  syncCameraTargetImpl(deps, deps.center);
}

export function getBoxBoundingBoxCenterImpl(
  deps: ViewerCoreCameraOpsDeps,
  boxId: string
): THREE.Vector3 | null {
  const entry = deps.boxes.get(boxId);
  if (!entry) return null;
  entry.mesh.updateMatrixWorld(true);

  runWithLayoutBoundsProxiesVisible(entry.mesh, () => {
    deps.boxSingle.setFromObject(entry.mesh);
  });

  deps.boxSingle.getCenter(deps.center);
  return deps.center.clone();
}

export function isBoxInCameraFrameImpl(deps: ViewerCoreCameraOpsDeps, boxId: string): boolean {
  const entry = deps.boxes.get(boxId);
  if (!entry) return false;

  entry.mesh.updateMatrixWorld(true);
  deps.cameraManager.camera.updateMatrixWorld(true);

  deps.projScreenMatrix.multiplyMatrices(
    deps.cameraManager.camera.projectionMatrix,
    deps.cameraManager.camera.matrixWorldInverse
  );
  deps.frustum.setFromProjectionMatrix(deps.projScreenMatrix);

  runWithLayoutBoundsProxiesVisible(entry.mesh, () => {
    deps.boxSingle.setFromObject(entry.mesh);
  });

  return deps.frustum.intersectsBox(deps.boxSingle);
}

export function adjustCameraPositionToIncludeBoxImpl(
  deps: ViewerCoreCameraOpsDeps,
  boxId: string
): void {
  const entry = deps.boxes.get(boxId);
  if (!entry) return;

  entry.mesh.updateMatrixWorld(true);
  runWithLayoutBoundsProxiesVisible(entry.mesh, () => {
    deps.boxSingle.setFromObject(entry.mesh);
  });

  deps.boxSingle.getCenter(deps.center);
  deps.boxSingle.getSize(deps.size);

  const cam = deps.cameraManager.camera;
  const dir = new THREE.Vector3().subVectors(cam.position, deps.center).normalize();

  const maxDim = Math.max(deps.size.x, deps.size.y, deps.size.z, 0.1);
  const fovRad = (cam.fov * Math.PI) / 180;
  const distance = Math.max(0.3, (maxDim / (2 * Math.tan(fovRad * 0.5))) * 1.1);

  cam.position.copy(deps.center).addScaledVector(dir, distance);
  syncCameraTargetImpl(deps, deps.center, { updateLookAt: false });
  cam.lookAt(deps.center);
  deps.controls?.update();
}

export function updateCameraTargetToBoxImpl(
  deps: ViewerCoreCameraOpsDeps,
  boxId: string,
  options?: { onlyMovePositionIfOutOfFrame?: boolean }
): void {
  const center = getBoxBoundingBoxCenterImpl(deps, boxId);
  if (!center) return;

  if (deps.cameraViewPreset != null) {
    syncCameraTargetImpl(deps, center, { updateLookAt: false });
    return;
  }

  syncCameraTargetImpl(deps, center);
  const onlyIfOut = options?.onlyMovePositionIfOutOfFrame === true;

  if (onlyIfOut && !isBoxInCameraFrameImpl(deps, boxId)) {
    adjustCameraPositionToIncludeBoxImpl(deps, boxId);
  }
}

