      listRematePieces: () => projectRef.current.remates ?? [],
      getBoxConfig: (boxId) => {
        const dims = buildFinishBoxDims(boxId);
        if (!dims) return null;
        const wsBox = projectRef.current.workspaceBoxes.find((b) => b.id === boxId);
        return {
          ...dims,
          box: wsBox
            ? {
                cabinetType: wsBox.cabinetType,
                feetEnabled: wsBox.feetEnabled,
                feetHeight: wsBox.feetHeight,
                pe_cm: wsBox.pe_cm,
              }
            : undefined,
        };
      },
      getBoxWorldMatrix,
    });

    core?.setOnMultiSelectToggle?.((encodedId) => {
      const decoded = decodeSelectionId(encodedId);
      if (!decoded) return;
      toggleSelectedObject(encodedId);
      const selected = uiStore.getState().selectedObjects;
      if (decoded.kind === "box") {
        const boxId = decoded.id;
        multiSelectedBoxIdsRef.current = selected
          .filter((id) => id.startsWith("box:"))
          .map((id) => id.replace(/^box:/, ""));
        if (selected.includes(encodedId)) {
          actionsRef.current.selectBox(boxId);
          setSelectedObject({ type: "box", id: boxId });
        } else {
          const fallback = multiSelectedBoxIdsRef.current[multiSelectedBoxIdsRef.current.length - 1];
          if (fallback) {
            actionsRef.current.selectBox(fallback);
            setSelectedObject({ type: "box", id: fallback });
          } else {
            actionsRef.current.clearSelection();
            clearUiSelection();
          }
        }
        return;
      }
      if (decoded.kind === "remate") {
        multiSelectedBoxIdsRef.current = selected
          .filter((id) => id.startsWith("box:"))
          .map((id) => id.replace(/^box:/, ""));
        if (selected.includes(encodedId)) {
          if (projectRef.current.selectedWorkspaceBoxId) {
            actionsRef.current.clearSelection();
          }
          setSelectedObject({ type: "remate", id: decoded.id });
        } else {
          const current = uiStore.getState().selectedObject;
          if (current.type === "remate" && current.id === decoded.id) {
            clearUiSelection();
          }
        }
        return;
      }
      if (decoded.kind === "rodape") {
        if (selected.includes(encodedId)) {
          if (projectRef.current.selectedWorkspaceBoxId) {
            actionsRef.current.clearSelection();
          }
          setSelectedObject({ type: "rodape", id: decoded.id });
        } else {
          const current = uiStore.getState().selectedObject;
          if (current.type === "rodape" && current.id === decoded.id) {
            clearUiSelection();
          }
        }
        return;
      }
      if (decoded.kind === "door" || decoded.kind === "drawer") {
        const layerId = decoded.id;
        const box = projectRef.current.workspaceBoxes.find((b) => {
          if (decoded.kind === "door") {
            return (b.doorsLayer ?? []).some((d) => d.id === layerId);
          }
          return (b.drawersLayer ?? []).some((d) => d.id === layerId);
        });
        if (box && selected.includes(encodedId)) {
          actionsRef.current.selectBox(box.id);
          setSelectedObject({ type: "box", id: box.id });
        }
      }
    });

    core?.setOnRemateSelected?.((remateId) => {
      if (remateId) {
        if (projectRef.current.selectedWorkspaceBoxId) {
          actionsRef.current.clearSelection();
        }
        setSelectedObject({ type: "remate", id: remateId });
        setSelectedTool("home");
        return;
      }
      if (uiStore.getState().selectedObject.type === "remate") {
        clearUiSelection();
      }
    });

    core?.setOnRodapeSelected?.((rodapeId) => {
      if (rodapeId) {
        if (projectRef.current.selectedWorkspaceBoxId) {
          actionsRef.current.clearSelection();
        }
        setSelectedObject({ type: "rodape", id: rodapeId });
        setSelectedTool("home");
        return;
      }
      if (uiStore.getState().selectedObject.type === "rodape") {
        clearUiSelection();
      }
    });

    const buildHematiBoxConfig = (boxId: string) => {
      const dims = buildFinishBoxDims(boxId);
      if (!dims) return null;
      const hematis = (projectRef.current.hematis ?? []).filter((h) => h.parentBoxId === boxId);
      return { ...dims, hematis };
    };

    const buildRodapeBoxConfig = (boxId: string) => {
      const dims = buildFinishBoxDims(boxId);
      if (!dims) return null;
      const rodapes = (projectRef.current.rodapes ?? []).filter((r) => r.parentBoxId === boxId);
      return { ...dims, rodapes };
    };

    core?.bindHematiBridge?.({
      getBoxHematiConfig: (boxId) => buildHematiBoxConfig(boxId),
      listBoxHematiConfigs: () =>
        projectRef.current.workspaceBoxes
          .map((box) => buildHematiBoxConfig(box.id))
          .filter((cfg): cfg is NonNullable<typeof cfg> => cfg != null && cfg.hematis.length > 0),
      getBoxWorldMatrix,
    });

    core?.bindRodapeBridge?.({
      getBoxRodapeConfig: (boxId) => buildRodapeBoxConfig(boxId),
      listBoxRodapeConfigs: () =>
        projectRef.current.workspaceBoxes
          .map((box) => buildRodapeBoxConfig(box.id))
          .filter((cfg): cfg is NonNullable<typeof cfg> => cfg != null && cfg.rodapes.length > 0),
      getBoxWorldMatrix,
    });

    core?.bindDivSepBridge?.({
      getDivSepDragContext: (boxId, kind, itemId) => {
        const ws = projectRef.current.workspaceBoxes.find((b) => b.id === boxId);
        if (!ws) return null;
        const box = {
          dimensoes: ws.dimensoes,
          espessura: ws.espessura,
          profundidadeExterna: ws.profundidadeExterna ?? ws.dimensoes.profundidade,
          portaTipo: ws.portaTipo,
          doorsLayer: ws.doorsLayer,
          costaAtiva: ws.costaAtiva,
          divisores: ws.divisores,
          separadores: ws.separadores,
        };
        if (kind === "div") {
          const item = (ws.divisores ?? []).find((d) => d.id === itemId);
          return item ? { box, item } : null;
        }
        const item = (ws.separadores ?? []).find((s) => s.id === itemId);
        return item ? { box, item } : null;
      },
    });

    core?.setOnRemateTransform?.((remateId, patch) => {
      actionsRef.current.updateRemate(remateId, patch);
    });
    core?.setOnHematiTransform?.((hematiId, patch) => {
      actionsRef.current.updateHemati(hematiId, patch);
    });
    core?.setOnRodapeTransform?.((rodapeId, patch) => {
      actionsRef.current.updateRodape(rodapeId, patch);
    });
    core?.setOnDivSepTransform?.(({ boxId, kind, itemId, positionMm }) => {
      actionsRef.current.selectBox(boxId);
      if (kind === "div") {
        actionsRef.current.updateDivisor(itemId, { positionMm });
      } else {
        actionsRef.current.updateSeparador(itemId, { positionMm });
      }
    });
  }, [viewerReady, setSelectedObject, setSelectedTool, clearUiSelection, viewerApi]);

  useEffect(() => {
    if (!viewerReady) return;
    viewerApi.syncOrlaVisuals?.();
    viewerApi.syncRemateVisuals?.();
    viewerApi.syncHematiVisuals?.();
    viewerApi.syncRodapeVisuals?.();
    if (viewerApi.getTransformControlsDragging?.()) return;
    viewerApi.refreshTransformControlsAttachment?.();
  }, [
    project.orlaPieces,
    project.orlaPresets,
    project.remates,
    project.hematis,
    project.rodapes,
    project.room,
    project.workspaceBoxes,
    project.boxes,
    settings.orlaRules,
    viewerReady,
    viewerApi,
  ]);

  useEffect(() => {
    if (!viewerReady) return;
    viewerApi.internalRuler?.syncFromProject?.(project.measurements?.unified ?? []);
  }, [project.measurements?.unified, viewerReady, viewerApi.internalRuler]);

  useEffect(() => {
    const clearKeyboardMoveTimers = () => {
      const state = keyboardMoveRef.current;
      if (state.accelTimeoutId != null) {
        window.clearTimeout(state.accelTimeoutId);
        state.accelTimeoutId = null;
      }
      if (state.repeatIntervalId != null) {
        window.clearInterval(state.repeatIntervalId);
        state.repeatIntervalId = null;
      }
      state.activeKey = null;
    };

    const isEditableTarget = (target: EventTarget | null): boolean => {
      if (!(target instanceof HTMLElement)) return false;
      const tag = target.tagName.toLowerCase();
      return tag === "input" || tag === "textarea" || target.isContentEditable;
    };

    const performRemateMoveStep = (
      remateId: string,
      key: "ArrowUp" | "ArrowDown" | "ArrowLeft" | "ArrowRight",
      stepMm: number,
      shiftKey = false
    ) => {
      viewerApi.applyRemateKeyboardTransform?.(remateId, key, { stepMm, shiftKey });
    };

    const performRodapeMoveStep = (
      rodapeId: string,
      key: "ArrowUp" | "ArrowDown" | "ArrowLeft" | "ArrowRight",
      stepMm: number
    ) => {
      const rodape = projectRef.current.rodapes?.find((r) => r.id === rodapeId);
      if (!rodape) return;

      const stepM = stepMm / 1000;
      let localU = 0;
      let localV = 0;
      if (key === "ArrowUp") localV = stepM;
      else if (key === "ArrowDown") localV = -stepM;
      else if (key === "ArrowLeft") localU = -stepM;
      else localU = stepM;

      const transform = rodape.transform ?? {
        xMm: 0,
        yMm: 0,
        zMm: 0,
        rotacaoXRad: 0,
        rotacaoYRad: 0,
        rotacaoZRad: 0,
      };
      const yaw = transform.rotacaoYRad ?? 0;
      const cos = Math.cos(yaw);
      const sin = Math.sin(yaw);
      const delta = new Vector3(
        localU * cos - localV * sin,
        localV,
        localU * sin + localV * cos
      );

      let nextTransform = { ...transform };

      if (rodape.parentBoxId) {
        const worldMatrix = viewerApi.getBoxWorldMatrix?.(rodape.parentBoxId) as Matrix4 | undefined;
        if (worldMatrix) {
          const inv = new Matrix4().copy(worldMatrix).invert();
          const deltaLocal = delta.clone().applyMatrix4(inv);
          nextTransform = {
            ...transform,
            xMm: transform.xMm + deltaLocal.x * 1000,
            yMm: transform.yMm + deltaLocal.y * 1000,
            zMm: transform.zMm + deltaLocal.z * 1000,
          };
        }
      } else {
        nextTransform = {
          ...transform,
          xMm: transform.xMm + delta.x * 1000,
          yMm: transform.yMm + delta.y * 1000,
          zMm: transform.zMm + delta.z * 1000,
        };
      }

      const current = projectRef.current;
      const nextPatch = { transform: nextTransform, placementFree: true as const };
      projectRef.current = {
        ...current,
        rodapes: (current.rodapes ?? []).map((r) =>
          r.id === rodapeId ? { ...r, ...nextPatch } : r
        ),
      };
      actionsRef.current.updateRodape(rodapeId, nextPatch);
      viewerApi.syncRodapeVisuals?.();
      viewerApi.resolveFinishCollisionAfterSync?.({ rodapeId });
    };

    const performMoveStep = (key: "ArrowUp" | "ArrowDown" | "ArrowLeft" | "ArrowRight", stepMm: number) => {
      const currentProject = projectRef.current;
      const boxId = currentProject.selectedWorkspaceBoxId;
      if (!boxId) return;
      const box = currentProject.workspaceBoxes.find((b) => b.id === boxId);
      if (!box || box.locked) return;
      const delta =
        key === "ArrowUp"
          ? { x: 0, y: stepMm }
          : key === "ArrowDown"
            ? { x: 0, y: -stepMm }
            : key === "ArrowLeft"
              ? { x: -stepMm, y: 0 }
              : { x: stepMm, y: 0 };
      actionsRef.current.updateWorkspaceBoxTransform(boxId, {
        x_mm: (box.posicaoX_mm ?? 0) + delta.x,
        y_mm: (box.posicaoY_mm ?? 0) + delta.y,
        manualPosition: true,
      });
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (isEditableTarget(event.target)) return;
      ctrlOrMetaPressedRef.current = event.ctrlKey || event.metaKey;
      const keyLower = event.key.toLowerCase();
      if (event.key === "Alt" && !event.repeat) {
        event.preventDefault();
        setShowKeyboardShortcutsHelp((prev) => !prev);
        return;
      }
      const ctrlOrMeta = event.ctrlKey || event.metaKey;
      if (ctrlOrMeta && !event.altKey && keyLower === "z") {
        event.preventDefault();
        if (event.shiftKey) {
          actionsRef.current.redo();
        } else {
          actionsRef.current.undo();
        }
        return;
      }
      if (ctrlOrMeta && !event.altKey && keyLower === "y") {
        event.preventDefault();
        actionsRef.current.redo();
        return;
      }
      if (event.key === "Delete" || event.key === "Backspace") {
        event.preventDefault();
        const uiSelection = uiStore.getState().selectedObject;
        if (uiSelection.type === "remate") {
          actionsRef.current.removeRemate(uiSelection.id);
          clearUiSelection();
          return;
        }
        const currentProject = projectRef.current;
        const validIds = new Set(currentProject.workspaceBoxes.map((box) => box.id));
        const multiSelectionIds = selectedObjects.length > 0
          ? selectedObjects
          : multiSelectedBoxIdsRef.current
              .filter((id) => validIds.has(id))
              .map((id) => boxSelectionId(id));
        const boxIdsToDelete = multiSelectionIds
          .map((encoded) => encoded.replace(/^box:/, ""))
          .filter((id) => validIds.has(id));
        const selectedId = currentProject.selectedWorkspaceBoxId;
        const idsToDelete = boxIdsToDelete.length > 0
          ? Array.from(new Set(boxIdsToDelete))
          : selectedId
            ? [selectedId]
            : [];
        if (idsToDelete.length === 0) {
          if (multiSelectionIds.some((id) => id.startsWith("remate:"))) {
            for (const encoded of multiSelectionIds.filter((id) => id.startsWith("remate:"))) {
              actionsRef.current.removeRemate(encoded.replace(/^remate:/, ""));
            }
            clearUiSelection();
            setSelectedObjects([]);
          }
          return;
        }
        for (const boxId of idsToDelete) {
          actionsRef.current.removeWorkspaceBoxById(boxId);
        }
        multiSelectedBoxIdsRef.current = [];
        setSelectedObjects([]);
        return;
      }
      if (event.key !== "ArrowUp" && event.key !== "ArrowDown" && event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      event.preventDefault();
      const key = event.key;
      const state = keyboardMoveRef.current;
      if (state.activeKey === key) return;
      clearKeyboardMoveTimers();
      state.activeKey = key;

      const uiSelection = uiStore.getState().selectedObject;
      const finishStepMm = 1;
      if (uiSelection.type === "remate") {
        performRemateMoveStep(uiSelection.id, key, finishStepMm, event.shiftKey);
        state.accelTimeoutId = window.setTimeout(() => {
          state.repeatIntervalId = window.setInterval(() => {
            if (keyboardMoveRef.current.activeKey !== key) return;
            performRemateMoveStep(uiSelection.id, key, finishStepMm, event.shiftKey);
          }, 40);
        }, 200);
        return;
      }
      if (uiSelection.type === "rodape") {
        performRodapeMoveStep(uiSelection.id, key, finishStepMm);
        state.accelTimeoutId = window.setTimeout(() => {
          state.repeatIntervalId = window.setInterval(() => {
            if (keyboardMoveRef.current.activeKey !== key) return;
            performRodapeMoveStep(uiSelection.id, key, finishStepMm);
          }, 40);
        }, 200);
        return;
      }

      performMoveStep(key, 1);
      state.accelTimeoutId = window.setTimeout(() => {
        state.repeatIntervalId = window.setInterval(() => {
          if (keyboardMoveRef.current.activeKey !== key) return;
          performMoveStep(key, 10);
        }, 40);
      }, 200);
    };

    const handleKeyUp = (event: KeyboardEvent) => {
      ctrlOrMetaPressedRef.current = event.ctrlKey || event.metaKey;
      const state = keyboardMoveRef.current;
      if (state.activeKey == null) return;
      if (event.key !== state.activeKey) return;
      clearKeyboardMoveTimers();
    };

    const handleWindowBlur = () => {
      ctrlOrMetaPressedRef.current = false;
      clearKeyboardMoveTimers();
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);
    window.addEventListener("blur", handleWindowBlur);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
      window.removeEventListener("blur", handleWindowBlur);
      clearKeyboardMoveTimers();
    };
  }, [viewerApi]);

  const workspacePositionKey = useMemo(
    () => JSON.stringify(project.workspaceBoxes.map((b) => [b.id, b.posicaoX_mm, b.posicaoY_mm, b.posicaoZ_mm])),
    [project.workspaceBoxes]
  );

  const prevBoxesRef = useRef<string>("");
  useEffect(() => {
    const key = workspacePositionKey;
    if (project.estaCarregando) {
      prevBoxesRef.current = key;
      return;
    }
    prevBoxesRef.current = key;
  }, [workspacePositionKey, project.estaCarregando]);

  useEffect(() => {
    if (viewerReady) {
      if (!hasShownViewerReadyToastRef.current) {
        hasShownViewerReadyToastRef.current = true;
        showToast("Viewer pronto.", "info", 1400);
      }
    } else {
      hasShownViewerReadyToastRef.current = false;
    }
  }, [viewerReady, showToast]);

return (
    <>
    <main
      className="workspace-root"
      style={{ position: "relative", zIndex: 0 }}
      aria-label="Área de design 3D"
      onPointerDown={() => {
        if (mouseMenuPosition) setMouseMenuPosition(null);
        setContextMenuLayerTarget(null);
        setContextSelectedBoxIds([]);
      }}
    >
      <div className="workspace-canvas">
        <div className="workspace-toolbars" style={{ display: "flex", flexDirection: "column", gap: 0 }}>
          <UnifiedTopToolbar
            onNovo={handleTopToolbarNovo}
            onProjetos={handleTopToolbarProjetos}
            activeTool={project.activeViewerTool ?? "select"}
            onToolSelect={(toolId, _eventKey) => handleToolSelect(toolId)}
            lockEnabled={lockEnabled}
            onToggleLock={toggleLock}
          />
          <ViewerToolbar confirmNewOpen={confirmNewOpen} setConfirmNewOpen={setConfirmNewOpen} />
        </div>
<div className="workspace-viewer" style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column", position: "relative" }}>
          <div
            ref={viewerSurfaceRef}
            style={{
              position: "relative",
              flex: 1,
              minHeight: 0,
            }}
          >
            <div
              ref={containerRef}
              onPointerDownCapture={(event) => {
                ctrlOrMetaPressedRef.current = event.ctrlKey || event.metaKey;
                pointerToggleSelectionRef.current = event.ctrlKey || event.metaKey;
              }}
              onMouseDownCapture={(event) => {
                pointerToggleSelectionRef.current = event.ctrlKey || event.metaKey;
              }}
              onClickCapture={(event) => {
                pointerToggleSelectionRef.current = event.ctrlKey || event.metaKey;
              }}
              onContextMenu={(event) => {
                event.preventDefault();
                const hit = viewerApi.getContextMenuLayerHit?.(event) ?? null;
                if (import.meta.env.DEV && hit?.type === "door" && hit.doorLayerId) {
                  devLogger.debug("[DOOR-MAT] Workspace onContextMenu — hit recebido (será usado no menu)", {
                    boxId: hit.boxId,
                    doorLayerId: hit.doorLayerId,
                    type: hit.type,
                  });
                }
                setContextMenuLayerTarget(hit);
                setContextSelectedBoxIds([...multiSelectedBoxIdsRef.current]);
                setMouseMenuPosition({ x: event.clientX, y: event.clientY });
              }}
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                overflow: "hidden",
              }}
            />
            <SelectionMarquee
              containerRef={containerRef}
              enabled={(project.activeViewerTool ?? "select") === "select" && viewerReady}
              canStartAtPointer={(event) => {
                return viewerApi.isPointerOnSelectableObject?.({
                  clientX: event.clientX,
                  clientY: event.clientY,
                }) !== true;
              }}
              getIdsInRect={(rect) => {
                const canvas = containerRef.current?.querySelector("canvas");
                if (!canvas || !viewerApi.getSelectionIdsInScreenRect) return [];
                return viewerApi.getSelectionIdsInScreenRect(rect, canvas);
              }}
              onSelectionComplete={(ids) => {
                setSelectedObjects(ids);
                multiSelectedBoxIdsRef.current = ids
                  .map((encoded) => encoded.replace(/^box:/, ""))
                  .filter((id) => projectRef.current.workspaceBoxes.some((b) => b.id === id));
                const lastBox = multiSelectedBoxIdsRef.current[multiSelectedBoxIdsRef.current.length - 1];
                if (lastBox) {
                  actions.selectBox(lastBox);
                  setSelectedObject({ type: "box", id: lastBox });
                }
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                pointerEvents: "none",
              }}
              aria-hidden
            >
              <BoxInfoOverlay />
              <InternalMeasurementsPanel />
              <IndustrialDesignPanel />
            </div>
          </div>
          {!viewerReady && (
            <div className="workspace-loading-overlay" aria-live="polite">
              <span className="workspace-loading-spinner" aria-hidden="true" />
              <span>A carregar viewer 3D...</span>
            </div>
          )}
          {mouseMenuPosition && (
            <ContextMenu
              position={mouseMenuPosition}
              onClose={() => {
                setMouseMenuPosition(null);
                setContextMenuLayerTarget(null);
                setContextSelectedBoxIds([]);
              }}
              contextMenuLayerTarget={contextMenuLayerTarget}
              onDoorMaterialChange={(boxId, doorLayerId, materialId) => {
                if (import.meta.env.DEV) {
                  devLogger.debug("[DOOR-MAT] 1 Workspace.onDoorMaterialChange", { boxId, doorLayerId, materialId, when: "before setState" });
                }
                actions.setDoorMaterial(boxId, doorLayerId, materialId);
                viewerApi.updateDoorMaterial?.(boxId, doorLayerId, materialId);
                if (import.meta.env.DEV) {
                  devLogger.debug("[DOOR-MAT] 2 Workspace.onDoorMaterialChange done (viewer updated)", { boxId, doorLayerId, materialId });
                }
              }}
              onDrawerMaterialChange={(boxId, drawerLayerId, materialId) => {
                actions.setDrawerMaterial(boxId, drawerLayerId, materialId);
                viewerApi.updateDrawerMaterial?.(boxId, drawerLayerId, materialId);
              }}
              selectedBoxIds={contextSelectedBoxIds}
              selectedObjectIds={selectedObjects}
            />
          )}
          {showKeyboardShortcutsHelp && (
            <div
              aria-live="polite"
              style={{
                position: "absolute",
                top: 12,
                right: 12,
                zIndex: 120,
                minWidth: 260,
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid rgba(255,255,255,0.18)",
                background: "rgba(8, 12, 26, 0.92)",
                color: "var(--text-main)",
                fontSize: 12,
                lineHeight: 1.45,
                pointerEvents: "none",
              }}
            >
              <div style={{ fontWeight: 700, marginBottom: 6 }}>Atalhos do teclado</div>
              <div>Ctrl+Z: Desfazer</div>
              <div>Ctrl+Y: Refazer</div>
              <div>Delete/Backspace: Excluir seleção</div>
              <div>Ctrl+Click: Adicionar/remover da seleção</div>
              <div>Setas: Mover caixa selecionada</div>
              <div>Alt: Mostrar/ocultar esta ajuda</div>
            </div>
          )}
        </div>
      </div>
    </main>
    </>
  );
}

import type { ChangeEvent } from "react";
import type { DrawerLayerItem, DrawerLayerMetadata } from "../../models/BoxLayers";
import type { WorkspaceBox } from "../../core/types";
import { getSettings } from "../../core/settings/settingsService";
import { listOfficialMaterials } from "../../core/materials/materials.api";
import GroupedMaterialSelect from "../settings/material/GroupedMaterialSelect";
import {
  DRAWER_HANDLE_POSITIONS,
  DRAWER_HANDLE_TYPES,
  DRAWER_METAL_BOX_TYPES,
  DRAWER_SLIDE_TYPES,
  isDrawerSlideTypeActive,
  isDrawerMetalBoxTypeActive,
  drawerSlideTypeOptionLabel,
  drawerMetalBoxTypeOptionLabel,
} from "../../core/drawers/drawerUiConstants";
import {
  getDefaultProfileForHandleType,
  listProfilesForHandleType,
  STANDARD_HANDLE_CENTER_DISTANCES_MM,
} from "../../core/drawers/drawerHandleCatalog";
import {
  isMetalBoxCatalogType,
  listMetalBoxProfilesForType,
  pickCompatibleMetalDepth,
  resolveMetalBoxHeightMm,
  resolveMetalBoxProfile,
} from "../../core/drawers/drawerMetalBoxCatalog";
import { validateDrawerLayerItem } from "../../core/drawers/drawerUiValidation";
import {
  resolveDrawerBodyHeightMm,
  resolveDrawerExternalFrontHeightMm,
  resolveDrawerInternalFrontHeightMm,
} from "../../core/drawers/drawerLayerCustomization";
import type {
  DrawerHandlePosition,
  DrawerHandleType,
  DrawerMetalBoxType,
  DrawerSlideType,
} from "../../core/settings/settingsSchema";

export type DrawerConfigPanelProps = {
  drawer: DrawerLayerItem;
  index: number;
  box: WorkspaceBox;
  showHardware?: boolean;
  onUpdate: (partial: Partial<DrawerLayerItem>) => void;
  /** Atualização imediata do material da frente no viewer 3D (sem rebuild estrutural). */
  onFrontMaterialChange?: (materialId: string) => void;
};

function mergeDrawerMetadata(
  current: DrawerLayerMetadata | undefined,
  patch: DrawerLayerMetadata
): DrawerLayerMetadata {
  return { ...current, ...patch };
}

function buildDrawerConfigPatch(
  drawer: DrawerLayerItem,
  patch: Partial<DrawerLayerItem> & { metadata?: DrawerLayerMetadata }
): Partial<DrawerLayerItem> {
  const metadata = mergeDrawerMetadata(drawer.metadata, {
    ...drawer.metadata,
    ...patch.metadata,
    slideType: (patch.slideType ?? drawer.slideType) as DrawerSlideType | undefined,
    metalBoxType: (patch.metalBoxType ?? drawer.metalBoxType) as DrawerMetalBoxType | undefined,
    softClose: patch.softClose ?? drawer.softClose,
    handleType: (patch.handleType ?? drawer.handleType) as DrawerHandleType | undefined,
    handlePosition: (patch.handlePosition ?? drawer.handlePosition) as DrawerHandlePosition | undefined,
    handleOffsetMm: patch.handleOffsetMm ?? drawer.handleOffsetMm,
    handleProfileId: patch.metadata?.handleProfileId ?? drawer.metadata?.handleProfileId,
    handleCenterDistanceMm: patch.metadata?.handleCenterDistanceMm ?? drawer.metadata?.handleCenterDistanceMm,
    handleOffsetXMm: patch.metadata?.handleOffsetXMm ?? drawer.metadata?.handleOffsetXMm,
    handleOffsetYMm: patch.metadata?.handleOffsetYMm ?? drawer.metadata?.handleOffsetYMm,
    handlePositionPercent: patch.metadata?.handlePositionPercent ?? drawer.metadata?.handlePositionPercent,
    drawerType: (patch.type ?? patch.drawerType ?? drawer.type ?? drawer.drawerType) as
      | "normal"
      | "pro"
      | undefined,
    nominalDepth: patch.metadata?.nominalDepth ?? drawer.metadata?.nominalDepth,
    metalBoxProfileId: patch.metadata?.metalBoxProfileId ?? drawer.metadata?.metalBoxProfileId,
    metalBoxHeightMm: patch.metadata?.metalBoxHeightMm ?? drawer.metadata?.metalBoxHeightMm,
    frontMaterial: patch.material ?? patch.metadata?.frontMaterial ?? drawer.material,
    frontHeightMm: patch.metadata?.frontHeightMm ?? drawer.metadata?.frontHeightMm,
    frontPieceName: patch.metadata?.frontPieceName ?? drawer.metadata?.frontPieceName,
    frontIntPieceName: patch.metadata?.frontIntPieceName ?? drawer.metadata?.frontIntPieceName,
    frontExtPieceName: patch.metadata?.frontExtPieceName ?? drawer.metadata?.frontExtPieceName,
    drawerGroupName: patch.metadata?.drawerGroupName ?? drawer.metadata?.drawerGroupName,
  });

  const bodyHeight = resolveDrawerBodyHeightMm(drawer);
  const nextFrontHeightMm = patch.metadata?.frontHeightMm ?? drawer.metadata?.frontHeightMm;
  const resolvedFrontHeight =
    nextFrontHeightMm != null && Number.isFinite(nextFrontHeightMm) && nextFrontHeightMm > 0
      ? nextFrontHeightMm
      : bodyHeight;

  return {
    ...patch,
    metadata,
    material: patch.material ?? drawer.material,
    materialId: patch.materialId ?? patch.material ?? drawer.materialId,
    height: resolvedFrontHeight,
    bodyHeight: patch.bodyHeight ?? drawer.bodyHeight ?? bodyHeight,
  };
}

export function getDrawerStatusBadges(drawer: DrawerLayerItem): string[] {
  const badges: string[] = [];
  const type = drawer.type ?? drawer.drawerType ?? "normal";
  if (type === "pro") badges.push("PRO");
  else badges.push("Normal");
  if (drawer.metalBoxType && drawer.metalBoxType !== "Nenhuma") {
    badges.push("Metálica");
  }
  if (drawer.softClose) badges.push("Soft-close");
  if (drawer.metadata?.hardwareSource === "individual") badges.push("Individual");
  else if (drawer.metadata?.hardwareSource === "global") badges.push("Global");
  return badges;
}

const alertStyle = (level: "warning" | "error") => ({
  fontSize: 11,
  padding: "6px 8px",
  borderRadius: 6,
  marginTop: 6,
  background: level === "error" ? "rgba(239,68,68,0.12)" : "rgba(234,179,8,0.12)",
  color: level === "error" ? "#fca5a5" : "#fde68a",
  border: `1px solid ${level === "error" ? "rgba(239,68,68,0.35)" : "rgba(234,179,8,0.35)"}`,
});

export default function DrawerConfigPanel({
  drawer,
  index,
  box,
  showHardware = true,
  onUpdate,
  onFrontMaterialChange,
}: DrawerConfigPanelProps) {
  const settings = getSettings().gavetas;
  const woodMaterials = listOfficialMaterials().filter((m) => m.industrial && m.visual);
  const alerts = validateDrawerLayerItem(drawer, box, settings);

  const drawerType = drawer.type ?? drawer.drawerType ?? "normal";
  const slideType = drawer.slideType ?? settings.gavetaTipoCorredica;
  const metalBoxType = drawer.metalBoxType ?? settings.gavetaTipoCaixaMetalica;
  const metalProfile = isMetalBoxCatalogType(metalBoxType)
    ? resolveMetalBoxProfile(
        metalBoxType,
        drawer.metadata?.metalBoxProfileId,
        drawer.metadata?.metalBoxHeightMm
      )
    : null;
  const metalHeightOptions = metalProfile?.allowedHeightsMm ?? [];
  const metalHeightMm =
    drawer.metadata?.metalBoxHeightMm ??
    (metalProfile ? resolveMetalBoxHeightMm(metalProfile) : settings.gavetaAlturaCaixaMetalicaMm);
  const depthOptions = metalProfile
    ? metalProfile.compatibleDepthsMm
    : settings.gavetaProfundidadesDisponiveisMm;
  const handleType = drawer.handleType ?? settings.gavetaTipoHandle;
  const handlePosition = drawer.handlePosition ?? settings.gavetaPosicaoHandle;
  const handleProfileId =
    drawer.metadata?.handleProfileId ?? getDefaultProfileForHandleType(handleType)?.id ?? "";
  const handleCenterDistanceMm =
    drawer.metadata?.handleCenterDistanceMm ??
    getDefaultProfileForHandleType(handleType)?.defaultCenterDistanceMm ??
    80;
  const handleOffsetX = drawer.metadata?.handleOffsetXMm ?? 0;
  const handleOffsetY = drawer.metadata?.handleOffsetYMm ?? drawer.handleOffsetMm ?? settings.gavetaOffsetHandleMm;
  const handlePositionPercent = drawer.metadata?.handlePositionPercent ?? 50;
  const profileOptions = listProfilesForHandleType(handleType);
  const nominalDepth = drawer.metadata?.nominalDepth ?? drawer.depth;
  const material = drawer.material ?? drawer.materialId ?? "";
  const bodyHeight = Math.round(resolveDrawerBodyHeightMm(drawer));
  const internalFrontHeight = Math.round(resolveDrawerInternalFrontHeightMm(drawer));
  const externalFrontHeight = Math.round(resolveDrawerExternalFrontHeightMm(drawer));
  const frontHeightOverride = drawer.metadata?.frontHeightMm;
  const frontPieceName = drawer.metadata?.frontExtPieceName ?? drawer.metadata?.frontPieceName ?? "";
  const frontIntPieceName = drawer.metadata?.frontIntPieceName ?? "";
  const drawerGroupName = drawer.metadata?.drawerGroupName ?? "";

  const update = (patch: Partial<DrawerLayerItem> & { metadata?: DrawerLayerMetadata }) => {
    onUpdate(buildDrawerConfigPatch(drawer, patch));
  };

  const parseOptionalPositiveMm = (raw: string): number | undefined => {
    const trimmed = raw.trim();
    if (!trimmed) return undefined;
    const n = Number(trimmed);
    return Number.isFinite(n) && n > 0 ? n : undefined;
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 8 }}>
      {alerts.map((alert, i) => (
        <div key={`${alert.level}-${i}`} style={alertStyle(alert.level)}>
          {alert.message}
        </div>
      ))}

      {showHardware && (
        <>
          <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Tipo de gaveta</span>
            <select
              className="select select-xs"
              value={drawerType}
              onChange={(e) =>
                update({
                  type: e.target.value as "normal" | "pro",
                  drawerType: e.target.value as "normal" | "pro",
                })
              }
            >
              <option value="normal">Normal</option>
              <option value="pro">PRO (caixa metálica)</option>
            </select>
          </label>

          <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Corrediça</span>
            <select
              className="select select-xs"
              value={slideType}
              onChange={(e) => update({ slideType: e.target.value as DrawerSlideType })}
            >
              {DRAWER_SLIDE_TYPES.map((option) => (
                <option key={option} value={option} disabled={!isDrawerSlideTypeActive(option)}>
                  {drawerSlideTypeOptionLabel(option)}
                </option>
              ))}
            </select>
          </label>

          <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Caixa metálica</span>
            <select
              className="select select-xs"
              value={metalBoxType}
              onChange={(e) => {
                const nextType = e.target.value as DrawerMetalBoxType;
                if (nextType === "Nenhuma") {
                  update({ metalBoxType: nextType, metadata: { metalBoxProfileId: undefined, metalBoxHeightMm: undefined } });
                  return;
                }
                const profiles = listMetalBoxProfilesForType(nextType);
                const profile = profiles[0] ?? null;
                const height = profile ? resolveMetalBoxHeightMm(profile) : settings.gavetaAlturaCaixaMetalicaMm;
                const depth = profile
                  ? pickCompatibleMetalDepth(profile, drawer.metadata?.nominalDepth ?? drawer.depth)
                  : drawer.metadata?.nominalDepth ?? drawer.depth;
                update({
                  metalBoxType: nextType,
                  slideType: profile?.defaultSlideType ?? drawer.slideType,
                  bodyHeight: height,
                  metadata: {
                    metalBoxProfileId: profile?.id,
                    metalBoxHeightMm: height,
                    nominalDepth: depth,
                  },
                });
              }}
            >
              {DRAWER_METAL_BOX_TYPES.map((option) => (
                <option
                  key={option}
                  value={option}
                  disabled={option !== "Nenhuma" && !isDrawerMetalBoxTypeActive(option)}
                >
                  {option === "Nenhuma" ? option : drawerMetalBoxTypeOptionLabel(option)}
                </option>
              ))}
            </select>
          </label>

          {metalBoxType !== "Nenhuma" && metalProfile && (
            <>
              {listMetalBoxProfilesForType(metalBoxType).length > 1 && (
                <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Perfil / série</span>
                  <select
                    className="select select-xs"
                    value={metalProfile.id}
                    onChange={(e) => {
                      const profile = listMetalBoxProfilesForType(metalBoxType).find((p) => p.id === e.target.value);
                      if (!profile) return;
                      const height = resolveMetalBoxHeightMm(profile, metalHeightMm);
                      update({
                        slideType: profile.defaultSlideType,
                        bodyHeight: height,
                        metadata: {
                          metalBoxProfileId: profile.id,
                          metalBoxHeightMm: height,
                          nominalDepth: pickCompatibleMetalDepth(
                            profile,
                            drawer.metadata?.nominalDepth ?? drawer.depth
                          ),
                        },
                      });
                    }}
                  >
                    {listMetalBoxProfilesForType(metalBoxType).map((profile) => (
                      <option key={profile.id} value={profile.id}>
                        {profile.nome}
                      </option>
                    ))}
                  </select>
                </label>
              )}

              <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Altura da caixa (mm)</span>
                <select
                  className="select select-xs"
                  value={metalHeightMm}
                  onChange={(e) => {
                    const height = Number(e.target.value) || metalHeightOptions[0];
                    update({
                      bodyHeight: height,
                      metadata: { metalBoxHeightMm: height },
                    });
                  }}
                >
                  {metalHeightOptions.map((h) => (
                    <option key={h} value={h}>
                      {h} mm
                    </option>
                  ))}
                </select>
              </label>

              <div style={alertStyle("warning")}>
                Peças internas de madeira omitidas — apenas frente + caixa metálica ({metalProfile.brand}).
              </div>
            </>
          )}

          {metalBoxType !== "Nenhuma" && !metalProfile && (
            <div style={alertStyle("warning")}>
              Peças internas da gaveta serão omitidas (caixa metálica).
            </div>
          )}

          <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
            <input
              type="checkbox"
              checked={Boolean(drawer.softClose)}
              onChange={(e) => update({ softClose: e.target.checked })}
            />
            Soft-close
          </label>

          <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
            <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Puxador / handle</span>
            <select
              className="select select-xs"
              value={handleType}
              onChange={(e) => {
                const nextType = e.target.value as DrawerHandleType;
                const defaultProfile = getDefaultProfileForHandleType(nextType);
                update({
                  handleType: nextType,
                  metadata: {
                    handleProfileId: defaultProfile?.id,
                    handleCenterDistanceMm: defaultProfile?.defaultCenterDistanceMm,
                  },
                });
              }}
            >
              {DRAWER_HANDLE_TYPES.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </select>
          </label>

          {handleType !== "Nenhum" && (
            <>
              {profileOptions.length > 1 && (
                <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Perfil de puxador</span>
                  <select
                    className="select select-xs"
                    value={handleProfileId}
                    onChange={(e) => {
                      const profile = profileOptions.find((p) => p.id === e.target.value);
                      update({
                        metadata: {
                          handleProfileId: e.target.value || undefined,
                          handleCenterDistanceMm: profile?.defaultCenterDistanceMm,
                        },
                      });
                    }}
                  >
                    {profileOptions.map((profile) => (
                      <option key={profile.id} value={profile.id}>
                        {profile.nome}
                      </option>
                    ))}
                  </select>
                </label>
              )}

              {handleType === "Puxador" && (
                <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11, color: "var(--text-muted)" }}>CC (mm)</span>
                  <select
                    className="select select-xs"
                    value={handleCenterDistanceMm}
                    onChange={(e) =>
                      update({
                        metadata: { handleCenterDistanceMm: Number(e.target.value) || 80 },
                      })
                    }
                  >
                    {STANDARD_HANDLE_CENTER_DISTANCES_MM.map((cc) => (
                      <option key={cc} value={cc}>
                        {cc} mm
                      </option>
                    ))}
                  </select>
                </label>
              )}

              <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Posição automática</span>
                <select
                  className="select select-xs"
                  value={handlePosition}
                  onChange={(e) =>
                    update({ handlePosition: e.target.value as DrawerHandlePosition })
                  }
                >
                  {DRAWER_HANDLE_POSITIONS.map((option) => (
                    <option key={option} value={option}>
                      {option === "Percentual" ? "% da altura" : option}
                    </option>
                  ))}
                </select>
              </label>

              {handlePosition === "Percentual" && (
                <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11, color: "var(--text-muted)" }}>% da altura (topo→base)</span>
                  <input
                    className="input input-xs"
                    type="number"
                    min={5}
                    max={95}
                    value={handlePositionPercent}
                    onChange={(e) =>
                      update({
                        metadata: { handlePositionPercent: Number(e.target.value) || 50 },
                      })
                    }
                  />
                </label>
              )}

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Offset X (mm)</span>
                  <input
                    className="input input-xs"
                    type="number"
                    value={handleOffsetX}
                    onChange={(e) =>
                      update({
                        metadata: { handleOffsetXMm: Number(e.target.value) || 0 },
                      })
                    }
                  />
                </label>
                <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Offset Y (mm)</span>
                  <input
                    className="input input-xs"
                    type="number"
                    value={handleOffsetY}
                    onChange={(e) =>
                      update({
                        handleOffsetMm: Number(e.target.value) || 0,
                        metadata: { handleOffsetYMm: Number(e.target.value) || 0 },
                      })
                    }
                  />
                </label>
              </div>
            </>
          )}
        </>
      )}

      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 11, color: "var(--text-muted)" }}>
          Profundidade nominal (Gaveta {index + 1})
        </span>
        <select
          className="select select-xs"
          value={nominalDepth}
          onChange={(e) =>
            update({
              metadata: { nominalDepth: Number(e.target.value) },
            })
          }
        >
          {depthOptions.map((depth) => (
            <option key={depth} value={depth}>
              {depth} mm
            </option>
          ))}
        </select>
      </label>

      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Nome da Gaveta</span>
        <input
          className="input input-xs"
          type="text"
          placeholder={`Gaveta ${index + 1}`}
          value={drawerGroupName}
          onChange={(e) =>
            update({
              metadata: {
                drawerGroupName: e.target.value.trim() || undefined,
              },
            })
          }
        />
      </label>

      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Nome da Frente Externa</span>
        <input
          className="input input-xs"
          type="text"
          placeholder="Automático (industrial)"
          value={frontPieceName}
          onChange={(e) =>
            update({
              metadata: {
                frontExtPieceName: e.target.value.trim() || undefined,
                frontPieceName: e.target.value.trim() || undefined,
              },
            })
          }
        />
      </label>

      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Nome da Frente Interna</span>
        <input
          className="input input-xs"
          type="text"
          placeholder="Automático (industrial)"
          value={frontIntPieceName}
          onChange={(e) =>
            update({
              metadata: {
                frontIntPieceName: e.target.value.trim() || undefined,
              },
            })
          }
        />
      </label>

      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 11, color: "var(--text-muted)" }}>
          Altura da Frente Externa (mm)
        </span>
        <input
          className="input input-xs"
          type="number"
          min={settings.gavetaAlturaMinimaMm}
          max={settings.gavetaAlturaMaximaMm}
          placeholder={`Padrão: ${bodyHeight}`}
          value={frontHeightOverride != null && frontHeightOverride > 0 ? frontHeightOverride : ""}
          onChange={(e) =>
            update({
              metadata: {
                frontHeightMm: parseOptionalPositiveMm(e.target.value),
              },
            })
          }
        />
      </label>

      <label style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Material da frente</span>
        <GroupedMaterialSelect
          materials={woodMaterials}
          value={material}
          onChange={(materialId) => {
            update({
              material: materialId,
              materialId,
              metadata: { frontMaterial: materialId },
            });
            onFrontMaterialChange?.(materialId);
          }}
          selectClassName="select select-xs"
        />
      </label>

      <div className="muted-text" style={{ fontSize: 10 }}>
        {metalProfile ? (
          <>
            Caixa metálica: {metalHeightMm} mm · Frente ext.: {externalFrontHeight} mm · Frente int.:{" "}
            {internalFrontHeight} mm · Profundidade: {Math.round(nominalDepth)} mm
          </>
        ) : (
          <>
            Frente ext.: {externalFrontHeight} mm · Frente int.: {internalFrontHeight} mm · Corpo:{" "}
            {bodyHeight} mm · Profundidade: {Math.round(drawer.depth)} mm
          </>
        )}
      </div>
    </div>
  );
}

export function DrawerCustomHeightsTable({
  box,
  onHeightChange,
}: {
  box: WorkspaceBox;
  onHeightChange: (drawerId: string, height: number) => void;
}) {
  const settings = getSettings().gavetas;
  const drawers = box.drawersLayer ?? [];
  const internalHeight = Math.max(1, box.dimensoes.altura - 10);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <div style={{ fontSize: 11, color: "var(--text-muted)" }}>
        Altura interna do módulo: {internalHeight} mm (mín. {settings.gavetaAlturaMinimaMm} / máx.{" "}
        {settings.gavetaAlturaMaximaMm} mm por gaveta)
      </div>
      <table style={{ width: "100%", fontSize: 12, borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th style={{ textAlign: "left", padding: 4 }}>Gaveta</th>
            <th style={{ textAlign: "left", padding: 4 }}>Altura (mm)</th>
          </tr>
        </thead>
        <tbody>
          {drawers.map((drawer, index) => (
            <tr key={drawer.id}>
              <td style={{ padding: 4 }}>{index + 1}</td>
              <td style={{ padding: 4 }}>
                <input
                  className="input input-xs"
                  type="number"
                  min={settings.gavetaAlturaMinimaMm}
                  max={settings.gavetaAlturaMaximaMm}
                  value={Math.round(drawer.bodyHeight ?? drawer.height)}
                  onChange={(e: ChangeEvent<HTMLInputElement>) =>
                    onHeightChange(drawer.id, Number(e.target.value) || settings.gavetaAlturaMinimaMm)
                  }
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useMemo } from "react";
import { useProject } from "../../context/useProject";
import { useMaterials } from "../../hooks/useMaterials";
import { buildCutlistItemsForIndustrialExport } from "../../core/fabrication/buildCutlistItemsForIndustrialExport";
import { computeChapasReal } from "../../core/industrial/computeChapasReal";
import { computeConsumoMateriais } from "../../core/industrial/computeConsumoMateriais";
import {
  financeiroChapasBadgeLabel,
  financeiroChapasEstimadoHint,
  isChapasModeEstimado,
  isChapasModeOficial,
} from "../../core/financeiro/financeiroChapasModeLabels";
import type { FinanceiroChapasMode } from "../../core/financeiro/financeiroUnificadoTypes";
import {
  buildIndustrialArmazemPdf,
  industrialArmazemPdfFileName,
} from "../../core/pdf/pdfIndustrialArmazem";
import Panel from "../ui/Panel";
import Button from "../ui/Button";
import {
  beginIndustrialFileGeneration,
  endIndustrialFileGeneration,
} from "../../core/fabrication/industrialGenerationSuspend";

export default function PainelChapasReal({ embedded }: { embedded?: boolean } = {}) {
  const { project } = useProject();
  const { materials } = useMaterials();
  const boxes = project.boxes ?? [];
  const projectName = project.projectName?.trim() || "Projeto";

  const items = useMemo(
    () =>
      buildCutlistItemsForIndustrialExport({
        boxes,
        rules: project.rules,
        materialId: project.materialId,
        projectName,
        remates: project.remates ?? [],
        rodapes: project.rodapes ?? [],
        extractedPartsByBoxId: project.extractedPartsByBoxId,
        industrialPieceEdits: project.industrialPieceEdits,
      }),
    [boxes, project, projectName]
  );

  const chapas = useMemo(
    () => computeChapasReal(items, projectName, boxes, { projectId: projectName }),
    [items, projectName, boxes]
  );

  const chapasUiMode: FinanceiroChapasMode | null =
    chapas.mode === "oficial_pro" || chapas.mode === "estimado" || chapas.mode === "real"
      ? chapas.mode
      : null;

  const exportPdf = () => {
    beginIndustrialFileGeneration();
    void (async () => {
      try {
        const consumo = computeConsumoMateriais(items, materials, projectName, boxes);
        const doc = await buildIndustrialArmazemPdf(projectName, chapas, consumo);
        doc.save(industrialArmazemPdfFileName(projectName));
      } finally {
        endIndustrialFileGeneration();
      }
    })();
  };

  return (
    <Panel title={embedded ? undefined : "Cálculo de Chapas Real"}>
      <p style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 0 }}>
        Distribuição real das peças nas chapas via motor de nesting industrial.
      </p>
      <div
        style={{
          display: "flex",
          gap: 16,
          marginBottom: 12,
          fontSize: 12,
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <span>
          Chapas: <strong>{chapas.totalSheets}</strong>
          {chapasUiMode ? (
            <span
              style={{
                marginLeft: 8,
                fontWeight: 600,
                color: isChapasModeOficial(chapasUiMode) ? "#16a34a" : "#ea580c",
                fontSize: 11,
              }}
            >
              {financeiroChapasBadgeLabel(chapasUiMode)}
            </span>
          ) : null}
        </span>
        <span>
          Desperdício: <strong>{chapas.totalWastePct.toFixed(1)}%</strong>
        </span>
      </div>
      {chapasUiMode && isChapasModeEstimado(chapasUiMode) ? (
        <p style={{ fontSize: 12, color: "#ea580c", fontWeight: 600, marginTop: 0 }}>
          {financeiroChapasEstimadoHint()}
        </p>
      ) : null}
      <Button variant="secondary" onClick={exportPdf} style={{ marginBottom: 12, fontSize: 12 }}>
        Gerar PDF — chapas_real
      </Button>
      <div style={{ overflowX: "auto" }}>
        {chapas.sheets.map((sheet) => (
          <div
            key={sheet.sheetIndex}
            style={{
              marginBottom: 12,
              padding: 10,
              border: "1px solid rgba(255,255,255,0.1)",
              borderRadius: 6,
            }}
          >
            <div style={{ fontSize: 12, fontWeight: 600, marginBottom: 6 }}>
              Chapa {sheet.sheetIndex} — {sheet.material} {sheet.espessuraMm}mm · {sheet.pieceCount} peças ·
              desperdício {sheet.wastePct.toFixed(1)}%
            </div>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11 }}>
              <thead>
                <tr>
                  {["Peça", "N QR", "Largura", "Altura"].map((h) => (
                    <th key={h} style={{ textAlign: "left", padding: 4, color: "var(--text-muted)" }}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {sheet.pieces.map((p, i) => (
                  <tr key={`${sheet.sheetIndex}-${i}`}>
                    <td style={{ padding: 4 }}>{p.nome}</td>
                    <td style={{ padding: 4, fontFamily: "monospace" }}>{p.nQr}</td>
                    <td style={{ padding: 4 }}>{p.largura} mm</td>
                    <td style={{ padding: 4 }}>{p.altura} mm</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))}
        {chapas.sheets.length === 0 ? (
          <p style={{ fontSize: 12, color: "var(--text-muted)" }}>
            Nesting indisponível — estimativa: {chapas.totalSheets} chapa(s).
          </p>
        ) : null}
      </div>
    </Panel>
  );
}

import { useMemo } from "react";
import { useProject } from "../../context/useProject";
import { useMaterials } from "../../hooks/useMaterials";
import { buildCutlistItemsForIndustrialExport } from "../../core/fabrication/buildCutlistItemsForIndustrialExport";
import { computeConsumoMateriais } from "../../core/industrial/computeConsumoMateriais";
import { computeChapasReal } from "../../core/industrial/computeChapasReal";
import {
  buildIndustrialArmazemPdf,
  industrialArmazemPdfFileName,
} from "../../core/pdf/pdfIndustrialArmazem";
import Panel from "../ui/Panel";
import Button from "../ui/Button";
import {
  beginIndustrialFileGeneration,
  endIndustrialFileGeneration,
} from "../../core/fabrication/industrialGenerationSuspend";

export default function PainelConsumoMateriais({ embedded }: { embedded?: boolean } = {}) {
  const { project } = useProject();
  const { materials } = useMaterials();
  const boxes = project.boxes ?? [];
  const projectName = project.projectName?.trim() || "Projeto";

  const items = useMemo(
    () =>
      buildCutlistItemsForIndustrialExport({
        boxes,
        rules: project.rules,
        materialId: project.materialId,
        projectName,
        remates: project.remates ?? [],
        rodapes: project.rodapes ?? [],
        extractedPartsByBoxId: project.extractedPartsByBoxId,
        industrialPieceEdits: project.industrialPieceEdits,
      }),
    [boxes, project, projectName]
  );

  const summary = useMemo(
    () => computeConsumoMateriais(items, materials, projectName, boxes),
    [items, materials, projectName, boxes]
  );

  const exportPdf = () => {
    beginIndustrialFileGeneration();
    void (async () => {
      try {
        const chapas = computeChapasReal(items, projectName, boxes, { projectId: projectName });
        const doc = await buildIndustrialArmazemPdf(projectName, chapas, summary);
        doc.save(industrialArmazemPdfFileName(projectName));
      } finally {
        endIndustrialFileGeneration();
      }
    })();
  };

  return (
    <Panel title={embedded ? undefined : "Consumo de Materiais"}>
      <p style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 0 }}>
        Consumo por chapa e por peça, com estimativa de desperdício (nesting quando disponível).
      </p>
      <div style={{ display: "flex", gap: 16, marginBottom: 12, fontSize: 12 }}>
        <span>
          Desperdício total: <strong>{summary.desperdicioTotalPct.toFixed(1)}%</strong>
        </span>
        <span>
          Peças: <strong>{summary.porPeca.length}</strong>
        </span>
        <span>
          Chapas: <strong>{summary.porChapa.length}</strong>
        </span>
      </div>
      <Button variant="secondary" onClick={exportPdf} style={{ marginBottom: 12, fontSize: 12 }}>
        Gerar PDF — consumo_materiais
      </Button>
      <div style={{ overflowX: "auto" }}>
        <h4 style={{ fontSize: 12, margin: "8px 0" }}>Por peça</h4>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11, marginBottom: 16 }}>
          <thead>
            <tr style={{ borderBottom: "1px solid rgba(255,255,255,0.12)" }}>
              {["Peça", "N QR", "Material", "Qtd", "Área m²", "Peso kg"].map((h) => (
                <th key={h} style={{ textAlign: "left", padding: 6, color: "var(--text-muted)" }}>
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {summary.porPeca.map((r) => (
              <tr key={r.pecaId} style={{ borderBottom: "1px solid rgba(255,255,255,0.06)" }}>
                <td style={{ padding: 6 }}>{r.peca}</td>
                <td style={{ padding: 6, fontFamily: "monospace" }}>{r.nQr}</td>
                <td style={{ padding: 6 }}>{r.material}</td>
                <td style={{ padding: 6 }}>{r.quantidade}</td>
                <td style={{ padding: 6 }}>{(r.areaMm2 / 1_000_000).toFixed(4)}</td>
                <td style={{ padding: 6 }}>{r.pesoKg.toFixed(3)}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <h4 style={{ fontSize: 12, margin: "8px 0" }}>Por chapa</h4>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11 }}>
          <thead>
            <tr style={{ borderBottom: "1px solid rgba(255,255,255,0.12)" }}>
              {["Chapa", "Material", "Esp.", "Usada m²", "Desperdício %"].map((h) => (
                <th key={h} style={{ textAlign: "left", padding: 6, color: "var(--text-muted)" }}>
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {summary.porChapa.map((r) => (
              <tr key={r.chapaIndex} style={{ borderBottom: "1px solid rgba(255,255,255,0.06)" }}>
                <td style={{ padding: 6 }}>{r.chapaIndex}</td>
                <td style={{ padding: 6 }}>{r.material}</td>
                <td style={{ padding: 6 }}>{r.espessuraMm} mm</td>
                <td style={{ padding: 6 }}>{(r.areaUsadaMm2 / 1_000_000).toFixed(4)}</td>
                <td style={{ padding: 6 }}>{r.desperdicioPct.toFixed(1)}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Panel>
  );
}

import { useMemo, useState } from "react";
import { useProject } from "../../context/useProject";
import { getCurrentProjectUser } from "../../core/projects/currentUser";
import {
  INDUSTRIAL_OPERATION_IDS,
  INDUSTRIAL_OPERATION_LABELS,
  type IndustrialOperationId,
} from "../../core/industrial/industrialPieceEditsTypes";
import Panel from "../ui/Panel";
import Button from "../ui/Button";
import { ModalPortal } from "../ui/ModalPortal";

export default function PainelOperacoesIndustriais({ embedded }: { embedded?: boolean } = {}) {
  const { project, actions } = useProject();
  const operacoes = project.industrialOperacoes ?? {};
  const [pendingOp, setPendingOp] = useState<IndustrialOperationId | null>(null);
  const [notas, setNotas] = useState("");

  const rows = useMemo(
    () =>
      INDUSTRIAL_OPERATION_IDS.map((id) => ({
        id,
        label: INDUSTRIAL_OPERATION_LABELS[id],
        state: operacoes[id],
      })),
    [operacoes]
  );

  const completedCount = rows.filter((r) => r.state?.completedAt).length;

  const openComplete = (id: IndustrialOperationId) => {
    setPendingOp(id);
    setNotas("");
  };

  const confirmComplete = () => {
    if (!pendingOp) return;
    actions.completeIndustrialOperacao(pendingOp, notas.trim() || undefined);
    setPendingOp(null);
    setNotas("");
  };

  const currentUser = getCurrentProjectUser();

  return (
    <Panel title={embedded ? undefined : "Operações Industriais"}>
      <p style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 0 }}>
        Registo de conclusão por operação (funcionário, timestamp, notas). Linha verde quando concluída.
        Sincroniza com o Painel Mestre e PIMO TRAK ao enviar para fábrica.
      </p>
      <div style={{ fontSize: 12, marginBottom: 10 }}>
        Progresso: <strong>{completedCount}</strong> / {rows.length} operações
      </div>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
        <thead>
          <tr style={{ borderBottom: "1px solid rgba(255,255,255,0.12)" }}>
            {["Operação", "Estado", "Funcionário", "Concluído em", "Notas", ""].map((h) => (
              <th key={h} style={{ textAlign: "left", padding: "8px", color: "var(--text-muted)" }}>
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const done = Boolean(row.state?.completedAt);
            return (
              <tr
                key={row.id}
                style={{
                  borderBottom: "1px solid rgba(255,255,255,0.06)",
                  background: done ? "rgba(34, 197, 94, 0.14)" : "transparent",
                }}
              >
                <td style={{ padding: "8px", fontWeight: 600 }}>{row.label}</td>
                <td style={{ padding: "8px" }}>{done ? "Concluída" : "Pendente"}</td>
                <td style={{ padding: "8px" }}>
                  {row.state?.employeeName ?? row.state?.employeeId ?? "—"}
                </td>
                <td style={{ padding: "8px" }}>
                  {row.state?.completedAt
                    ? new Date(row.state.completedAt).toLocaleString("pt-PT")
                    : "—"}
                </td>
                <td style={{ padding: "8px", maxWidth: 160, fontSize: 11 }}>
                  {row.state?.notas?.trim() || "—"}
                </td>
                <td style={{ padding: "8px" }}>
                  {!done ? (
                    <Button variant="secondary" onClick={() => openComplete(row.id)} style={{ fontSize: 11 }}>
                      Concluir
                    </Button>
                  ) : null}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      {pendingOp ? (
        <ModalPortal>
          <div
            className="modal-overlay"
            role="dialog"
            aria-modal
            onClick={() => setPendingOp(null)}
          >
            <div className="modal-card" style={{ width: 400, padding: 16 }} onClick={(e) => e.stopPropagation()}>
              <div className="modal-title" style={{ marginBottom: 8 }}>
                Concluir — {INDUSTRIAL_OPERATION_LABELS[pendingOp]}
              </div>
              <p style={{ fontSize: 12, margin: "0 0 8px", color: "var(--text-muted)" }}>
                Funcionário: <strong>{currentUser.ownerName}</strong>
              </p>
              <label style={{ fontSize: 12, display: "block", marginBottom: 12 }}>
                Notas (opcional)
                <textarea
                  value={notas}
                  onChange={(e) => setNotas(e.target.value)}
                  rows={3}
                  style={{ display: "block", width: "100%", marginTop: 4, resize: "vertical" }}
                  placeholder="Observações da operação..."
                />
              </label>
              <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
                <Button variant="ghost" onClick={() => setPendingOp(null)}>
                  Cancelar
                </Button>
                <Button variant="primary" onClick={confirmComplete}>
                  Confirmar conclusão
                </Button>
              </div>
            </div>
          </div>
        </ModalPortal>
      ) : null}
    </Panel>
  );
}

import { useMemo, useState } from "react";
import { useProject } from "../../context/useProject";
import { useMaterials } from "../../hooks/useMaterials";
import { buildCutlistItemsForIndustrialExport } from "../../core/fabrication/buildCutlistItemsForIndustrialExport";
import { buildResumoIndustriaisRows } from "../../core/industrial/industrialBottomSectionData";
import {
  validateIndustrialDimensions,
  computeIndustrialPieceMetrics,
} from "../../core/industrial/IndustrialPieceEditsService";
import Panel from "../ui/Panel";
import PieceObservacoesOverlay from "../layout/overlays/PieceObservacoesOverlay";
import { ModalPortal } from "../ui/ModalPortal";
import Button from "../ui/Button";

const inputStyle: React.CSSProperties = {
  width: 52,
  padding: "2px 4px",
  fontSize: 11,
  borderRadius: 4,
  border: "1px solid rgba(255,255,255,0.2)",
  background: "rgba(0,0,0,0.25)",
  color: "var(--text-main)",
};

export default function PainelResumoIndustriais({ embedded }: { embedded?: boolean } = {}) {
  const { project, actions } = useProject();
  const { materials } = useMaterials();
  const [obsPiece, setObsPiece] = useState<{ id: string; label: string } | null>(null);
  const [movePiece, setMovePiece] = useState<{ id: string; label: string } | null>(null);
  const [moveTarget, setMoveTarget] = useState("");
  const [deletePiece, setDeletePiece] = useState<{ id: string; label: string } | null>(null);
  const [deleteStep, setDeleteStep] = useState<0 | 1 | 2>(0);
  const [draftDims, setDraftDims] = useState<Record<string, { comp: string; larg: string; esp: string }>>({});

  const boxes = project.boxes ?? [];

  const items = useMemo(
    () =>
      buildCutlistItemsForIndustrialExport({
        boxes,
        rules: project.rules,
        materialId: project.materialId,
        projectName: project.projectName,
        remates: project.remates ?? [],
        rodapes: project.rodapes ?? [],
        extractedPartsByBoxId: project.extractedPartsByBoxId,
        industrialPieceEdits: project.industrialPieceEdits,
      }),
    [boxes, project]
  );

  const rows = useMemo(
    () =>
      buildResumoIndustriaisRows(
        items,
        boxes,
        project.pieceObservacoes,
        project.industrialPieceEdits,
        materials
      ),
    [items, boxes, project.pieceObservacoes, project.industrialPieceEdits, materials]
  );

  const totals = useMemo(
    () =>
      rows.reduce(
        (acc, r) => ({
          areaM2: acc.areaM2 + r.areaM2,
          pesoKg: acc.pesoKg + r.pesoKg,
        }),
        { areaM2: 0, pesoKg: 0 }
      ),
    [rows]
  );

  const previewMetrics = (itemId: string, item: (typeof items)[0]) => {
    const d = getDraft(itemId, item);
    const largura = Number(d.larg);
    const altura = Number(d.comp);
    const espessura = Number(d.esp);
    if (![largura, altura, espessura].every((v) => Number.isFinite(v) && v > 0)) {
      return computeIndustrialPieceMetrics(item, materials);
    }
    return computeIndustrialPieceMetrics(
      {
        ...item,
        dimensoes: { ...item.dimensoes, largura, altura, profundidade: espessura },
        espessura,
      },
      materials
    );
  };

  const getDraft = (itemId: string, item: (typeof items)[0]) => {
    const existing = draftDims[itemId];
    if (existing) return existing;
    return {
      comp: String(item.dimensoes.altura),
      larg: String(item.dimensoes.largura),
      esp: String(item.espessura ?? item.dimensoes.profundidade ?? ""),
    };
  };

  const commitDims = (itemId: string) => {
    const item = items.find((i) => i.id === itemId);
    if (!item) return;
    const d = getDraft(itemId, item);
    const altura = Number(d.comp);
    const largura = Number(d.larg);
    const espessura = Number(d.esp);
    const err = validateIndustrialDimensions({ largura, altura, espessura });
    if (err) {
      window.alert(err);
      return;
    }
    actions.updateIndustrialPieceDimensions(itemId, { largura, altura, espessura });
  };

  const confirmMove = () => {
    if (!movePiece || !moveTarget) return;
    actions.moveIndustrialPiece(movePiece.id, moveTarget);
    setMovePiece(null);
    setMoveTarget("");
  };

  const confirmDelete = () => {
    if (!deletePiece) return;
    if (deleteStep === 0) {
      setDeleteStep(1);
      return;
    }
    actions.deleteIndustrialPiece(deletePiece.id);
    setDeletePiece(null);
    setDeleteStep(0);
  };

  if (boxes.length === 0) {
    return (
      <Panel title={embedded ? undefined : "Resumo Industriais — Painel Mestre"}>
        <div style={{ fontSize: 12, color: "var(--text-muted)" }}>Adicione caixas para controlar peças industriais.</div>
      </Panel>
    );
  }

  return (
    <Panel title={embedded ? undefined : "Resumo Industriais — Painel Mestre"}>
      <p style={{ fontSize: 12, color: "var(--text-muted)", marginTop: 0 }}>
        Edite medidas (COMP/LARG/ESP) com validação industrial. Peso, área e consumo recalculam automaticamente.
        Refletem-se em cutlist, técnico, etiquetas, unified e PDFs industriais.
      </p>
      <div style={{ display: "flex", gap: 16, marginBottom: 10, fontSize: 12 }}>
        <span>
          Área total: <strong>{totals.areaM2.toFixed(4)} m²</strong>
        </span>
        <span>
          Peso total: <strong>{totals.pesoKg.toFixed(2)} kg</strong>
        </span>
        <span>
          Peças: <strong>{rows.length}</strong>
        </span>
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11 }}>
          <thead>
            <tr style={{ borderBottom: "1px solid rgba(255,255,255,0.12)" }}>
              {["Caixa", "Peça", "LARG", "COMP", "ESP", "Área m²", "Peso kg", "Observações", "Ações"].map((h) => (
                <th key={h} style={{ textAlign: "left", padding: "6px 8px", color: "var(--text-muted)" }}>
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, idx) => {
              const item = items[idx];
              const draft = getDraft(item.id, item);
              const metrics = previewMetrics(item.id, item);
              return (
                <tr
                  key={item.id}
                  style={{
                    borderBottom: "1px solid rgba(255,255,255,0.06)",
                    background: row.modified ? "rgba(250, 204, 21, 0.12)" : "transparent",
                  }}
                >
                  <td style={{ padding: "6px 8px" }}>{row.caixa}</td>
                  <td style={{ padding: "6px 8px" }}>{row.peca}</td>
                  <td style={{ padding: "6px 8px" }}>
                    <input
                      style={inputStyle}
                      value={draft.larg}
                      onChange={(e) =>
                        setDraftDims((prev) => ({
                          ...prev,
                          [item.id]: { ...getDraft(item.id, item), larg: e.target.value },
                        }))
                      }
                      onBlur={() => commitDims(item.id)}
                    />
                  </td>
                  <td style={{ padding: "6px 8px" }}>
                    <input
                      style={inputStyle}
                      value={draft.comp}
                      onChange={(e) =>
                        setDraftDims((prev) => ({
                          ...prev,
                          [item.id]: { ...getDraft(item.id, item), comp: e.target.value },
                        }))
                      }
                      onBlur={() => commitDims(item.id)}
                    />
                  </td>
                  <td style={{ padding: "6px 8px" }}>
                    <input
                      style={inputStyle}
                      value={draft.esp}
                      onChange={(e) =>
                        setDraftDims((prev) => ({
                          ...prev,
                          [item.id]: { ...getDraft(item.id, item), esp: e.target.value },
                        }))
                      }
                      onBlur={() => commitDims(item.id)}
                    />
                  </td>
                  <td style={{ padding: "6px 8px", color: "var(--text-muted)" }}>
                    {metrics.consumoM2.toFixed(4)}
                  </td>
                  <td style={{ padding: "6px 8px", color: "var(--text-muted)" }}>
                    {metrics.pesoKg.toFixed(3)}
                  </td>
                  <td style={{ padding: "6px 8px", maxWidth: 180 }}>{row.observacoes || "—"}</td>
                  <td style={{ padding: "6px 8px", whiteSpace: "nowrap" }}>
                    <button
                      type="button"
                      className="button button-ghost"
                      style={{ fontSize: 10, padding: "2px 6px", marginRight: 4 }}
                      onClick={() => setObsPiece({ id: item.id, label: `${row.caixa} — ${row.peca}` })}
                    >
                      Obs
                    </button>
                    <button
                      type="button"
                      className="button button-ghost"
                      style={{ fontSize: 10, padding: "2px 6px", marginRight: 4 }}
                      onClick={() => {
                        setMovePiece({ id: item.id, label: `${row.caixa} — ${row.peca}` });
                        setMoveTarget(boxes[0]?.id ?? "");
                      }}
                    >
                      Mover
                    </button>
                    <button
                      type="button"
                      className="button button-ghost"
                      style={{ fontSize: 10, padding: "2px 6px", color: "#f87171" }}
                      onClick={() => {
                        setDeletePiece({ id: item.id, label: `${row.caixa} — ${row.peca}` });
                        setDeleteStep(0);
                      }}
                    >
                      Apagar
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {obsPiece ? (
        <PieceObservacoesOverlay
          pieceId={obsPiece.id}
          pieceName={obsPiece.label}
          onClose={() => setObsPiece(null)}
        />
      ) : null}

      {movePiece ? (
        <ModalPortal>
          <div
            className="modal-overlay"
            role="dialog"
            aria-modal
            onClick={() => setMovePiece(null)}
          >
            <div className="modal-card" style={{ width: 360, padding: 16 }} onClick={(e) => e.stopPropagation()}>
              <div className="modal-title" style={{ marginBottom: 8 }}>
                Mover peça
              </div>
              <p style={{ fontSize: 12, margin: "0 0 12px" }}>{movePiece.label}</p>
              <label style={{ fontSize: 12, display: "block", marginBottom: 12 }}>
                Caixa de destino
                <select
                  value={moveTarget}
                  onChange={(e) => setMoveTarget(e.target.value)}
                  style={{ display: "block", width: "100%", marginTop: 4 }}
                >
                  {boxes.map((b) => (
                    <option key={b.id} value={b.id}>
                      {b.nome?.trim() || b.id}
                    </option>
                  ))}
                </select>
              </label>
              <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
                <Button variant="ghost" onClick={() => setMovePiece(null)}>
                  Cancelar
                </Button>
                <Button variant="primary" onClick={confirmMove}>
                  Mover
                </Button>
              </div>
            </div>
          </div>
        </ModalPortal>
      ) : null}

      {deletePiece ? (
        <ModalPortal>
          <div className="modal-overlay" role="dialog" aria-modal onClick={() => { setDeletePiece(null); setDeleteStep(0); }}>
            <div className="modal-card" style={{ width: 380, padding: 16 }} onClick={(e) => e.stopPropagation()}>
              <div className="modal-title" style={{ marginBottom: 8, color: "#f87171" }}>
                Apagar peça
              </div>
              <p style={{ fontSize: 12, margin: "0 0 12px" }}>{deletePiece.label}</p>
              <p style={{ fontSize: 12, color: "var(--text-muted)" }}>
                {deleteStep === 0 && "Confirmação 1/2 — esta ação remove a peça do fluxo industrial."}
                {deleteStep === 1 && "Confirmação 2/2 — confirme novamente para apagar definitivamente."}
              </p>
              <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
                <Button variant="ghost" onClick={() => { setDeletePiece(null); setDeleteStep(0); }}>
                  Cancelar
                </Button>
                <Button variant="primary" onClick={confirmDelete}>
                  {deleteStep === 0 ? "Continuar" : "Apagar definitivamente"}
                </Button>
              </div>
            </div>
          </div>
        </ModalPortal>
      ) : null}
    </Panel>
  );
}

import Panel from "../../ui/Panel";
import type { CornerOrientation } from "../../../core/cornerCabinet/cornerCabinetRules";
import {
  isCornerDireitaInferiorV2Model,
  resolveCornerOrientationFromBox,
} from "../../../core/cornerCabinet/cornerCabinetRules";
import type { WorkspaceBox } from "../../../core/types";

type Props = {
  box: WorkspaceBox;
  onOrientationChange: (orientation: CornerOrientation) => void;
};

const OPTIONS: { id: CornerOrientation; label: string }[] = [
  { id: "direita", label: "Direita" },
  { id: "esquerda", label: "Esquerda" },
];

export function isCornerOrientationPanelVisible(box: Pick<WorkspaceBox, "baseCabinetId">): boolean {
  return isCornerDireitaInferiorV2Model(box.baseCabinetId);
}

export default function CornerOrientationPanel({ box, onOrientationChange }: Props) {
  if (!isCornerOrientationPanelVisible(box)) return null;

  const current = resolveCornerOrientationFromBox(box);

  return (
    <Panel title="Direção do módulo">
      <p style={{ margin: "0 0 8px", fontSize: 13, opacity: 0.85 }}>
        Frente fixa, porta, furos e animação seguem a orientação escolhida (módulo único v2).
      </p>
      <div
        role="group"
        aria-label="Direção do módulo canto"
        style={{ display: "flex", gap: 8 }}
      >
        {OPTIONS.map((opt) => {
          const active = current === opt.id;
          return (
            <button
              key={opt.id}
              type="button"
              aria-pressed={active}
              onClick={() => {
                if (!active) onOrientationChange(opt.id);
              }}
              style={{
                flex: 1,
                padding: "8px 12px",
                borderRadius: 6,
                border: active ? "2px solid var(--accent, #3b82f6)" : "1px solid var(--border, #444)",
                background: active ? "var(--accent-muted, rgba(59,130,246,0.15))" : "transparent",
                color: "inherit",
                cursor: active ? "default" : "pointer",
                fontWeight: active ? 600 : 400,
              }}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </Panel>
  );
}

import { useEffect, useMemo, useState, type ChangeEvent, type CSSProperties } from "react";
import { useProject } from "../../../context/useProject";
import { useUiStore } from "../../../stores/uiStore";
import Panel from "../../ui/Panel";
import { listOfficialMaterials } from "../../../core/materials/materials.api";
import type {
  RemateCompletoRules,
  RemateMountSlot,
  RematePiece,
  RemateProductOptions,
  RemateProductType,
} from "../../../core/remate/rematePieceTypes";
import type { ProjectActions } from "../../../context/projectTypes";
import {
  REMATE_MOUNT_SLOT_LABELS,
  REMATE_PRODUCT_TYPE_LABELS,
} from "../../../core/remate/rematePieceTypes";
import {
  DEFAULT_AVISTA_WIDTH_MM,
  defaultCompletoRules,
  defaultMountSlotForProduct,
  inferProductTypeFromLegacy,
} from "../../../core/remate/remateProductRules";
import { getMaterialByIdOrLabel } from "../../../core/materials/service";
import WoodGrainRotationToggle from "../material/WoodGrainRotationToggle";
import WoodGrainLockToggle from "../material/WoodGrainLockToggle";
import GroupedMaterialSelect from "../material/GroupedMaterialSelect";
import { measureRemateGap, measureRemateGapToBox } from "../../../core/remate/remateGapMeasure";
import { usePimoViewerContext } from "../../../hooks/usePimoViewerContext";
import RemateRulesSection from "./RemateRulesSection";
import TampoCutoutPropertiesPanel from "./TampoCutoutPropertiesPanel";
import TampoUnionPanel from "./TampoUnionPanel";
import TampoAnglePanel from "./TampoAnglePanel";
import { OPPOSITE_MOUNT_SLOT } from "../../../core/remate/remateCloneUtils";
import { resolveRematePieceNomeForRemate } from "../../../core/remate/labels";
import { isLRemateExt, isLRemateInt } from "../../../core/remate/remateLGeometry";

type Props = { remateId: string };

function useTextField(
  value: string,
  onCommit: (next: string) => void
): {
  value: string;
  onChange: (e: ChangeEvent<HTMLInputElement>) => void;
  onBlur: () => void;
} {
  const [draft, setDraft] = useState(value);
  useEffect(() => {
    setDraft(value);
  }, [value]);
  return {
    value: draft,
    onChange: (e) => setDraft(e.target.value),
    onBlur: () => {
      const trimmed = draft.trim();
      if (!trimmed) {
        setDraft(value);
        return;
      }
      onCommit(trimmed);
      setDraft(trimmed);
    },
  };
}

function useNumericField(
  value: number,
  onCommit: (next: number) => void,
  min = 1
): {
  value: string;
  onChange: (e: ChangeEvent<HTMLInputElement>) => void;
  onBlur: () => void;
} {
  const [draft, setDraft] = useState(String(value));
  useEffect(() => {
    setDraft(String(value));
  }, [value]);
  return {
    value: draft,
    onChange: (e) => setDraft(e.target.value),
    onBlur: () => {
      const parsed = Number(draft);
      if (draft.trim() === "" || Number.isNaN(parsed)) {
        setDraft(String(value));
        return;
      }
      const clamped = Math.max(min, parsed);
      onCommit(clamped);
      setDraft(String(clamped));
    },
  };
}

const MOUNT_SLOTS: RemateMountSlot[] = ["FRENTE", "DIR", "ESQ", "CIMA", "FUNDO"];
const PRODUCTS: RemateProductType[] = [
  "AVISTA",
  "COMPLETO",
  "L",
  "RODAPE",
  "RODAPE_L",
  "TAMPO_COZINHA",
];

const lDimCardStyle: CSSProperties = {
  padding: "10px 12px",
  borderRadius: 6,
  border: "1px solid var(--border-muted, #333)",
  display: "flex",
  flexDirection: "column",
  gap: 8,
};

type LRemateDimensionsCardsProps = {
  ext: RematePiece;
  int: RematePiece | undefined;
  thicknessMm: number;
  actions: Pick<ProjectActions, "updateRemate">;
};

function LRemateDimensionsCards({ ext, int, thicknessMm, actions }: LRemateDimensionsCardsProps) {
  const extWidthField = useNumericField(ext.width ?? 1, (width) => {
    actions.updateRemate(ext.id, { width });
  });
  const extHeightField = useNumericField(ext.height ?? 1, (height) => {
    actions.updateRemate(ext.id, { height });
  });
  const intWidthField = useNumericField(int?.width ?? 1, (width) => {
    if (!int) return;
    actions.updateRemate(int.id, { width });
  });
  const intHeightField = useNumericField(int?.height ?? 1, (height) => {
    if (!int) return;
    actions.updateRemate(int.id, { height });
  });

  return (
    <>
      <div style={lDimCardStyle}>
        <div style={{ fontWeight: 600, fontSize: 12 }}>Remate L EXT (rem_L_ext)</div>
        <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
          Comprimento (mm)
          <input className="input input-sm" type="number" min={1} {...extWidthField} />
        </label>
        <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
          Largura (mm)
          <input className="input input-sm" type="number" min={1} {...extHeightField} />
        </label>
        <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>
          Espessura: {thicknessMm} mm (material)
        </p>
      </div>

      {int ? (
        <div style={lDimCardStyle}>
          <div style={{ fontWeight: 600, fontSize: 12 }}>Remate L INT (rem_L_int)</div>
          <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>
            Unida geometricamente à ext — medidas independentes.
          </p>
          <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
            Comprimento (mm)
            <input className="input input-sm" type="number" min={1} {...intWidthField} />
          </label>
          <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
            Largura (mm)
            <input className="input input-sm" type="number" min={1} {...intHeightField} />
          </label>
          <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>
            Espessura: {thicknessMm} mm (material)
          </p>
        </div>
      ) : null}
    </>
  );
}

export default function RematePropertiesPanel({ remateId }: Props) {
  const { project, actions } = useProject();
  const { viewerApi } = usePimoViewerContext();
  const setSelectedObject = useUiStore((s) => s.setSelectedObject);
  const selectedObject = useUiStore((s) => s.selectedObject);
  const remate = (project.remates ?? []).find((r) => r.id === remateId);
  const materials = useMemo(() => listOfficialMaterials().filter((m) => m.industrial), []);

  const parentBox = remate?.parentBoxId
    ? project.workspaceBoxes.find((b) => b.id === remate.parentBoxId)
    : null;

  const targetRemate =
    remate && selectedObject.type === "remate" && selectedObject.id !== remateId
      ? (project.remates ?? []).find((r) => r.id === selectedObject.id)
      : null;

  const selectedWorkspaceBox =
    remate && project.selectedWorkspaceBoxId && project.selectedWorkspaceBoxId !== remate.parentBoxId
      ? project.workspaceBoxes.find((b) => b.id === project.selectedWorkspaceBoxId)
      : null;

  const gapMeasure = useMemo(() => {
    if (!remate) return null;
    if (targetRemate) {
      return measureRemateGap(remate, { targetRemate });
    }
    if (parentBox) {
      return measureRemateGap(remate, { parentBox });
    }
    if (selectedWorkspaceBox) {
      return measureRemateGapToBox(remate, selectedWorkspaceBox);
    }
    return null;
  }, [
    remate,
    remate?.position.xMm,
    remate?.position.yMm,
    remate?.position.zMm,
    remate?.width,
    remate?.height,
    parentBox,
    targetRemate,
    selectedWorkspaceBox,
  ]);

  const widthField = useNumericField(remate?.width ?? 1, (width) => {
    if (!remate) return;
    actions.updateRemate(remate.id, { width });
  });
  const heightField = useNumericField(remate?.height ?? 1, (height) => {
    if (!remate) return;
    actions.updateRemate(remate.id, { height });
  });

  const boxNameById = useMemo(() => {
    const out: Record<string, string> = {};
    for (const box of project.workspaceBoxes) {
      if (box?.id) out[box.id] = typeof box.nome === "string" ? box.nome : box.id;
    }
    return out;
  }, [project.workspaceBoxes]);

  const autoNome = useMemo(() => {
    if (!remate) return "";
    return resolveRematePieceNomeForRemate(remate, boxNameById);
  }, [remate, boxNameById]);

  const lGroupPieces = useMemo(() => {
    if (!remate) return null;
    const pt = remate.productType ?? inferProductTypeFromLegacy(remate);
    if (pt !== "L" || !remate.parentGroupId) return null;
    const group = (project.remates ?? []).filter(
      (r) => r.parentGroupId === remate.parentGroupId && r.productType === "L"
    );
    const ext = group.find((r) => isLRemateExt(r));
    const int = group.find((r) => isLRemateInt(r));
    if (!ext) return null;
    return { ext, int };
  }, [remate, project.remates]);

  const nomeField = useTextField(autoNome, (trimmed) => {
    if (!remate) return;
    actions.updateRemate(remate.id, {
      nomePersonalizado: trimmed === autoNome ? undefined : trimmed,
    });
  });

  if (!remate) return null;

  const productType = remate.productType ?? inferProductTypeFromLegacy(remate);
  const productOptions = remate.productOptions ?? {};
  const faceEditable = productType === "AVISTA" || productType === "COMPLETO";
  const isMain = !remate.partRole || remate.partRole === "MAIN";
  const isCompleto = productType === "COMPLETO";
  const isTampo = productType === "TAMPO_COZINHA";

  const material = getMaterialByIdOrLabel(remate.materialPresetId);
  const thicknessMm = Number(material?.espessura) || 19;

  const feetHeightMm = parentBox?.feetEnabled !== false
    ? Number(parentBox?.feetHeight ?? (parentBox?.pe_cm ?? 10) * 10) || 0
    : 0;

  const patchOptions = (patch: RemateProductOptions) =>
    actions.updateRemate(remate.id, {
      productOptions: { ...productOptions, ...patch },
      followBox: Boolean(remate.parentBoxId),
    });

  const patchCompletoRules = (rulePatch: Partial<RemateCompletoRules>) => {
    const currentRules = productOptions.completoRules ?? defaultCompletoRules();
    patchOptions({ completoRules: { ...currentRules, ...rulePatch } });
  };

  const completoRules = productOptions.completoRules ?? defaultCompletoRules();

  return (
    <Panel title="Propriedades do Remate" description={autoNome}>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
          Nome da peça
          <input className="input input-sm" type="text" {...nomeField} />
        </label>
        <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
          Tipo de produto
          <select
            className="select input-sm"
            value={productType}
            onChange={(e) =>
              actions.updateRemate(remate.id, {
                productType: e.target.value as RemateProductType,
                mountSlot: defaultMountSlotForProduct(e.target.value as RemateProductType),
                followBox: Boolean(remate.parentBoxId),
              })
            }
          >
            {PRODUCTS.map((p) => (
              <option key={p} value={p}>
                {REMATE_PRODUCT_TYPE_LABELS[p]}
              </option>
            ))}
          </select>
        </label>

        {faceEditable ? (
          <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
            Face de montagem
            <select
              className="select input-sm"
              value={remate.mountSlot ?? defaultMountSlotForProduct(productType)}
              onChange={(e) =>
                actions.updateRemate(remate.id, {
                  mountSlot: e.target.value as RemateMountSlot,
                  followBox: Boolean(remate.parentBoxId),
                })
              }
            >
              {MOUNT_SLOTS.map((slot) => (
                <option key={slot} value={slot}>
                  {REMATE_MOUNT_SLOT_LABELS[slot]}
                </option>
              ))}
            </select>
          </label>
        ) : null}

        {productType === "AVISTA" ? (
          <>
            <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
              Largura avista (mm)
              <input
                className="input input-sm"
                type="number"
                min={10}
                value={productOptions.avistaWidthMm ?? DEFAULT_AVISTA_WIDTH_MM}
                onChange={(e) =>
                  patchOptions({
                    avistaWidthMm: Math.max(10, Number(e.target.value) || DEFAULT_AVISTA_WIDTH_MM),
                  })
                }
              />
            </label>
            <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
              <input
                type="checkbox"
                checked={productOptions.avistaFlushToDoor ?? false}
                onChange={(e) => patchOptions({ avistaFlushToDoor: e.target.checked })}
              />
              Encostar à porta (~20 mm)
            </label>
          </>
        ) : null}

        {productType === "COMPLETO" && isMain ? (
          <>
            <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
              Largura extra (mm)
              <input
                className="input input-sm"
                type="number"
                min={0}
                value={productOptions.coverageExtraMm ?? 0}
                onChange={(e) =>
                  patchOptions({ coverageExtraMm: Math.max(0, Number(e.target.value) || 0) })
                }
              />
            </label>
            <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
              <input
                type="checkbox"
                checked={productOptions.includeTopBottomRemates ?? false}
                onChange={(e) =>
                  patchOptions({ includeTopBottomRemates: e.target.checked })
                }
              />
              Remate cima + remate fundo
            </label>
            <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
              <input
                type="checkbox"
                checked={productOptions.asPuxador ?? false}
                onChange={(e) => patchOptions({ asPuxador: e.target.checked })}
              />
              Modo puxador
            </label>
          </>
        ) : null}

        {productType === "L" && remate.partIndex !== 2 ? (
          <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>
            Remate L — posição CIMA (topo). Variantes DIR/ESQ/FUNDO serão reintroduzidas numa fase posterior.
          </p>
        ) : null}

        {isTampo ? (
          <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>
            Tampo / Remate Especial — largura fixa 630 mm, matéria MDB Laminado 30, laminado de fábrica (sem orla clássica).
          </p>
        ) : null}

        {isTampo ? (
          <TampoCutoutPropertiesPanel
            remate={remate}
            onChangeCutouts={(cutouts) => actions.updateRemate(remate.id, { cutouts })}
          />
        ) : null}

        {isTampo ? (
          <TampoAnglePanel
            remate={remate}
            onChangeAngleConfig={(angleConfig) =>
              actions.updateRemate(remate.id, { angleConfig })
            }
          />
        ) : null}

        {isTampo ? (
          <TampoUnionPanel
            remate={remate}
            otherTampos={(project.remates ?? []).filter(
              (r) =>
                r.id !== remate.id &&
                (r.productType === "TAMPO_COZINHA" || r.tipo === "TAMPO")
            )}
            onChangeUnion={(union) => actions.updateRemate(remate.id, { union })}
          />
        ) : null}

        {remate.placementMode === "FREE" ? (
          <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>Posição livre</p>
        ) : null}

        {lGroupPieces ? (
          <LRemateDimensionsCards
            ext={lGroupPieces.ext}
            int={lGroupPieces.int}
            thicknessMm={thicknessMm}
            actions={actions}
          />
        ) : (
          <>
            <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
              Comprimento (mm)
              <input
                className="input input-sm"
                type="number"
                min={1}
                max={isTampo ? 3660 : undefined}
                {...widthField}
              />
            </label>
            <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
              Largura (mm)
              <input
                className="input input-sm"
                type="number"
                min={1}
                readOnly={isTampo}
                disabled={isTampo}
                {...heightField}
              />
            </label>
            <p style={{ margin: 0, fontSize: 11, color: "var(--text-muted)" }}>
              Espessura: {thicknessMm} mm (material)
            </p>
          </>
        )}

        {gapMeasure ? (
          <div
            style={{
              padding: "8px 10px",
              borderRadius: 6,
              border: "1px solid var(--border-muted, #333)",
              fontSize: 12,
              lineHeight: 1.5,
            }}
          >
            <div style={{ fontWeight: 600, marginBottom: 4 }}>Distância ({gapMeasure.targetLabel})</div>
            {gapMeasure.overlapping ? (
              <span style={{ color: "var(--text-muted)" }}>Peças sobrepostas (0 mm nos eixos)</span>
            ) : (
              <>
                <div>Distância X: {gapMeasure.gapXMm} mm</div>
                <div>Distância Y: {gapMeasure.gapYMm} mm</div>
              </>
            )}
          </div>
        ) : null}

        <label style={{ display: "flex", flexDirection: "column", gap: 4, fontSize: 12 }}>
          Material
          <GroupedMaterialSelect
            materials={materials}
            value={remate.materialPresetId}
            onChange={(materialId) =>
              actions.updateRemate(remate.id, { materialPresetId: materialId })
            }
            selectClassName="select input-sm"
            disabled={isTampo}
          />
        </label>

        <WoodGrainRotationToggle
          materialId={remate.materialPresetId}
          allowPieceRotation={remate.allowPieceRotation}
          onChange={(allow) => actions.updateRemate(remate.id, { allowPieceRotation: allow })}
        />

        <WoodGrainLockToggle
          materialId={remate.materialPresetId}
          lockWoodGrain={remate.lockWoodGrain}
          onChange={(lock) => actions.updateRemate(remate.id, { lockWoodGrain: lock })}
        />

        <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12 }}>
          <input
            type="checkbox"
            checked={remate.followBox}
            onChange={(e) => actions.updateRemate(remate.id, { followBox: e.target.checked })}
            disabled={!remate.parentBoxId}
          />
          Seguir módulo (mantém offset à face)
        </label>

        {/* Regras de dimensionamento — só para tipo COMPLETO */}
        {isCompleto && isMain ? (
          <RemateRulesSection
            rules={completoRules}
            feetHeightMm={feetHeightMm}
            onChange={patchCompletoRules}
          />
        ) : null}

        {remate.parentBoxId ? (
          <button
            type="button"
            className="btn"
            onClick={() => actions.resnapRemateToFace(remate.id)}
          >
            Reencostar à face
          </button>
        ) : null}

        <button
          type="button"
          className="btn"
          onClick={() => {
            const newId = actions.duplicateRemate(remate.id);
            if (newId) {
              setSelectedObject({ type: "remate", id: newId });
              viewerApi.selectRemate?.(newId);
            }
          }}
        >
          Duplicar Remate
        </button>

        {OPPOSITE_MOUNT_SLOT[remate.mountSlot ?? "FRENTE"] && productType !== "L" && !isTampo ? (
          <button
            type="button"
            className="btn"
            onClick={() => {
              const newId = actions.createOppositeRemate(remate.id);
              if (newId) {
                setSelectedObject({ type: "remate", id: newId });
                viewerApi.selectRemate?.(newId);
              }
            }}
          >
            Criar Remate Oposto
          </button>
        ) : null}

        <button type="button" className="btn btn-danger" onClick={() => actions.removeRemate(remate.id)}>
          Remover remate
        </button>
      </div>
    </Panel>
  );
}

import { useState } from "react";

