export function useShowroomExplodeDefaults(focusLevel: ProjetosFocusLevel) {
  const [boxExplode, setBoxExplode] = useState(false);
  const [boxIntensity, setBoxIntensity] = useState(0.45);
  const [pieceExplode, setPieceExplode] = useState(false);
  const [pieceIntensity, setPieceIntensity] = useState(0.35);
  const [focusSnapshot, setFocusSnapshot] = useState(focusLevel);

  if (focusLevel !== focusSnapshot) {
    setFocusSnapshot(focusLevel);
    if (focusLevel === "piece") setBoxExplode(false);
    if (focusLevel === "project") setPieceExplode(false);
  }

  return {
    boxExplode,
    boxIntensity,
    pieceExplode,
    pieceIntensity,
    setBoxExplode,
    setBoxIntensity,
    setPieceExplode,
    setPieceIntensity,
  };
}

import { useCallback, useMemo } from "react";
import { useProject } from "../../../context/useProject";
import { usePimoViewerContext } from "../../../hooks/usePimoViewerContext";
import { useWallStore } from "../../../stores/wallStore";import { uiStore, useUiStore } from "../../../stores/uiStore";
import { LEFT_TOOLBAR_IDS } from "../../layout/left-toolbar/LeftToolbar";
import {
  applyProjectRoomDimensions,
  createDefaultProjectRoom,
} from "../../../3d/viewer-engine/room/RoomEngine";
import { hasPersistedRoomWalls } from "../../../utils/roomWorkspaceBounds";
import { Icon } from "@/components/icons";

/** Atalho na toolbar: mesmas dimensões padrão ao criar sala instantaneamente. */
const DEFAULT_ROOM_WIDTH_M = 4;
const DEFAULT_ROOM_DEPTH_M = 3;
const DEFAULT_ROOM_HEIGHT_M = 2.4;

export default function RoomIconButton() {
  const { viewerApi } = usePimoViewerContext();
  const { actions } = useProject();
  const setSelectedTool = useUiStore((state) => state.setSelectedTool);
  const walls = useWallStore((state) => state.walls);

  const roomPresent = useMemo(() => {
    if (viewerApi?.getRoomExists?.()) return true;
    return hasPersistedRoomWalls(walls);
  }, [viewerApi, walls]);

  const isActive = roomPresent;

  const handleClick = useCallback(() => {
    if (!roomPresent) {
      const base = createDefaultProjectRoom();
      const room = applyProjectRoomDimensions({
        ...base,
        widthMm: DEFAULT_ROOM_WIDTH_M * 1000,
        depthMm: DEFAULT_ROOM_DEPTH_M * 1000,
        heightMm: DEFAULT_ROOM_HEIGHT_M * 1000,
      });
      actions.setProjectRoom(room);
      // Navigate to HOME so room settings appear in the Início section
      setSelectedTool(LEFT_TOOLBAR_IDS.HOME);
      const scheduleReposition = () => {
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            actions.repositionWorkspaceBoxesInsideRoom();
          });
        });
      };
      scheduleReposition();
      return;
    }
    // Room already exists: toggle to SALA tab to show/manage settings
    const currentTool = uiStore.getState().selectedTool;
    if (currentTool === LEFT_TOOLBAR_IDS.SALA) {
      setSelectedTool(LEFT_TOOLBAR_IDS.HOME);
    } else {
      setSelectedTool(LEFT_TOOLBAR_IDS.SALA);
    }
  }, [actions, roomPresent, setSelectedTool, viewerApi]);

  /** Mesmo encaixe que `unifiedBubbleStyle` na barra unificada. */
  const bubbleStyle = {
    width: 28,
    height: 28,
    display: "flex" as const,
    alignItems: "center" as const,
    justifyContent: "center" as const,
    border: "none" as const,
    borderRadius: 4,
    cursor: "pointer" as const,
    marginLeft: 3,
    color: "var(--status-done-color)",
    background: isActive ? "var(--toolbar-pressed-bg)" : "transparent",
  };

  return (
    <button
      type="button"
      title={roomPresent ? "Remover sala e fechar painel" : "Criar sala (4×3×2,4 m) e abrir painel"}
      aria-label={roomPresent ? "Remover sala" : "Criar sala"}
      aria-pressed={isActive}
      onClick={handleClick}
      style={bubbleStyle}
      onMouseEnter={(e) => {
        if (!isActive) e.currentTarget.style.background = "var(--viewer-toolbar-hover-bg)";
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.background = isActive ? "var(--toolbar-pressed-bg)" : "transparent";
      }}
    >
      <Icon name="room" size={24} aria-hidden />
    </button>
  );
}

/**
 * Contexto para a barra de informação inferior (BottomInfoToolbar).
 * P3.6 — Financeiro sem tabs legadas; secção única `unificado`.
 */

import { createContext, useCallback, useContext, useMemo, useState } from "react";

export type BottomInfoGroupId = "financeiro" | "industriais" | "operacoes";

/** IDs legados (sub-secções) — mantidos para compatibilidade de deep-links. */
export type BottomInfoLegacySectionId =
  | "resumo"
  | "totais"
  | "custos"
  | "pecasTotais"
  | "ferragensTotais"
  | "resumoIndustriais"
  | "operacoesIndustriais"
  | "consumoMateriais"
  | "chapasReal";

export type BottomInfoPanelId = BottomInfoGroupId | BottomInfoLegacySectionId | null;

/** P3.7 — Painel Unificado | Financeiro peças | Editar. */
export type FinanceiroSectionId = "unificado" | "pecas" | "editar";
export type IndustriaisSectionId =
  | "pecasTotais"
  | "ferragensTotais"
  | "consumoMateriais"
  | "chapasReal"
  | "resumoIndustriais"
  | "enviarFabrica";
export type OperacoesSectionId =
  | "todas"
  | "NESTING"
  | "CNC"
  | "DRILL"
  | "ORLAR"
  | "MONTAGEM"
  | "EMBALAGEM";

export type BottomInfoSectionId = FinanceiroSectionId | IndustriaisSectionId | OperacoesSectionId;

const DEFAULT_SECTION: Record<BottomInfoGroupId, BottomInfoSectionId> = {
  financeiro: "unificado",
  industriais: "pecasTotais",
  operacoes: "todas",
};

const LEGACY_TO_GROUP: Record<
  BottomInfoLegacySectionId,
  { group: BottomInfoGroupId; section: BottomInfoSectionId }
> = {
  // P3.6 — tabs financeiras antigas → Painel Unificado
  resumo: { group: "financeiro", section: "unificado" },
  totais: { group: "financeiro", section: "unificado" },
  custos: { group: "financeiro", section: "unificado" },
  pecasTotais: { group: "industriais", section: "pecasTotais" },
  ferragensTotais: { group: "industriais", section: "ferragensTotais" },
  consumoMateriais: { group: "industriais", section: "consumoMateriais" },
  chapasReal: { group: "industriais", section: "chapasReal" },
  resumoIndustriais: { group: "industriais", section: "resumoIndustriais" },
  operacoesIndustriais: { group: "operacoes", section: "todas" },
};

function resolveOpenTarget(id: Exclude<BottomInfoPanelId, null>): {
  group: BottomInfoGroupId;
  section: BottomInfoSectionId;
} {
  if (id === "financeiro" || id === "industriais" || id === "operacoes") {
    return { group: id, section: DEFAULT_SECTION[id] };
  }
  return LEGACY_TO_GROUP[id];
}

type BottomInfoContextValue = {
  /** Grupo aberto (null = fechado). */
  openPanel: BottomInfoGroupId | null;
  activeSection: BottomInfoSectionId;
  setOpenPanel: (_id: BottomInfoPanelId) => void;
  setActiveSection: (_section: BottomInfoSectionId) => void;
  togglePanel: (_id: Exclude<BottomInfoPanelId, null>) => void;
  openGroupSection: (_group: BottomInfoGroupId, _section?: BottomInfoSectionId) => void;
};

const BottomInfoContext = createContext<BottomInfoContextValue | null>(null);

function normalizeFinanceiroSection(section: BottomInfoSectionId | string): BottomInfoSectionId {
  // Compat: estados em memória / localStorage antigos (resumo/totais/custos)
  if (section === "resumo" || section === "totais" || section === "custos") {
    return "unificado";
  }
  return section as BottomInfoSectionId;
}

export function BottomInfoProvider({ children }: { children: React.ReactNode }) {
  const [openPanel, setOpenPanelState] = useState<BottomInfoGroupId | null>(null);
  const [activeSection, setActiveSectionState] = useState<BottomInfoSectionId>("unificado");

  const setActiveSection = useCallback((section: BottomInfoSectionId) => {
    setActiveSectionState(normalizeFinanceiroSection(section));
  }, []);

  const openGroupSection = useCallback(
    (group: BottomInfoGroupId, section?: BottomInfoSectionId) => {
      setOpenPanelState(group);
      setActiveSectionState(normalizeFinanceiroSection(section ?? DEFAULT_SECTION[group]));
    },
    []
  );

  const setOpenPanel = useCallback((id: BottomInfoPanelId) => {
    if (id === null) {
      setOpenPanelState(null);
      return;
    }
    const { group, section } = resolveOpenTarget(id);
    setOpenPanelState(group);
    setActiveSectionState(normalizeFinanceiroSection(section));
  }, []);

  const togglePanel = useCallback((id: Exclude<BottomInfoPanelId, null>) => {
    const { group, section } = resolveOpenTarget(id);
    setOpenPanelState((prev) => {
      if (prev === group) return null;
      setActiveSectionState(normalizeFinanceiroSection(section));
      return group;
    });
  }, []);

  const value = useMemo<BottomInfoContextValue>(
    () => ({
      openPanel,
      activeSection,
      setOpenPanel,
      setActiveSection,
      togglePanel,
      openGroupSection,
    }),
    [openPanel, activeSection, setOpenPanel, setActiveSection, togglePanel, openGroupSection]
  );

  return <BottomInfoContext.Provider value={value}>{children}</BottomInfoContext.Provider>;
}

export function useBottomInfo() {
  const ctx = useContext(BottomInfoContext);
  if (!ctx) throw new Error("useBottomInfo must be used within BottomInfoProvider");
  return ctx;
}

/**
 * Registo dos handlers undo/redo definidos no Workspace, consumíveis pelo Header (irmão na árvore).
 * Quando o Workspace não está montado, os cliques são no-op até haver registo.
 */

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type Dispatch,
  type ReactNode,
  type SetStateAction,
} from "react";

export type WorkspaceUndoRedoHandlers = {
  handleUndo: () => void;
  handleRedo: () => void;
};

type RegistryContextValue = {
  handleUndo: () => void;
  handleRedo: () => void;
  registerWorkspaceUndoRedo: Dispatch<SetStateAction<WorkspaceUndoRedoHandlers | null>>;
};

const WorkspaceUndoRedoRegistryContext = createContext<RegistryContextValue | null>(null);

export function WorkspaceUndoRedoRegistryProvider({ children }: { children: ReactNode }) {
  const [registered, setRegistered] = useState<WorkspaceUndoRedoHandlers | null>(null);

  const handleUndo = useCallback(() => {
    registered?.handleUndo();
  }, [registered]);

  const handleRedo = useCallback(() => {
    registered?.handleRedo();
  }, [registered]);

  const value = useMemo(
    () => ({
      handleUndo,
      handleRedo,
      registerWorkspaceUndoRedo: setRegistered,
    }),
    [handleUndo, handleRedo]
  );

  return (
    <WorkspaceUndoRedoRegistryContext.Provider value={value}>{children}</WorkspaceUndoRedoRegistryContext.Provider>
  );
}

export function useWorkspaceUndoRedoRegistry(): RegistryContextValue {
  const ctx = useContext(WorkspaceUndoRedoRegistryContext);
  if (!ctx) {
    throw new Error("useWorkspaceUndoRedoRegistry deve ser usado dentro de WorkspaceUndoRedoRegistryProvider");
  }
  return ctx;
}

/** Mesmo contexto, sem erro fora do provider (Header partilhado entre LegacyApp e rotas sem registry). */
export function useWorkspaceUndoRedoRegistryOptional(): RegistryContextValue | null {
  return useContext(WorkspaceUndoRedoRegistryContext);
}

/**
 * Hook compositor de ações do projeto.
 * Mantém apenas composição de hooks por domínio.
