/**
 * Lógica de autosave e carregamento a partir do autosave.
 * Extraído do ProjectProvider para reduzir complexidade.
 */

import { useCallback, useEffect, useRef } from "react";
import { safeGetItem, safeSetItem } from "../../utils/storage";
import { wallStore } from "../../stores/wallStore";
import { applyProjectRoomToWallStore, normalizeProjectRoom, wallStoreToProjectRoom } from "../../3d/viewer-engine/room/RoomEngine";
import type { ProjectState, ProjectSnapshot, RoomSnapshot } from "../projectTypes";
import { defaultState } from "../projectState";

const AUTOSAVE_STORAGE_KEY = "pimo_autosave";
const AUTO_SAVE_BASE_DEBOUNCE_MS = 1200;

function isProjectCompletelyDefaultForPersistence(proj: ProjectState): boolean {
  if ((proj.workspaceBoxes?.length ?? 0) > 0) return false;
  if ((proj.projectName?.trim() || "") !== defaultState.projectName) return false;
  if (wallStore.getState().walls.length >= 3) return false;
  return true;
}

export type ProjectPersistenceApi = {
  serializeForAutosave: (_state: ProjectState) => unknown;
  revive: (_snapshot: unknown) => ProjectState | null;
  captureRoomSnapshot: () => RoomSnapshot | null;
  /** Opcional: aplicar resultados ao estado restaurado (ex.: applyResultados). */
  applyResultados?: (_state: ProjectState) => ProjectState;
};

export type ProjectPersistenceOptions = {
  /** Se true, não lê/grava autosave nem beforeunload (modo design pipro). */
  disabled?: boolean;
};

export function useProjectPersistence(
  project: ProjectState,
  setProject: React.Dispatch<React.SetStateAction<ProjectState>>,
  viewerSync: { saveViewerSnapshot: () => unknown; restoreViewerSnapshot: (_snapshot: unknown) => void },
  api: ProjectPersistenceApi,
  options?: ProjectPersistenceOptions
) {
  const disabled = options?.disabled === true;
  const projectRef = useRef(project);
  projectRef.current = project;
  const autosaveTimerRef = useRef<number | null>(null);
  const lastAutosaveFingerprintRef = useRef<string>("");
  const pendingAutosaveRef = useRef(false);

  const performAutosave = useCallback(() => {
    if (disabled) return;
    const proj = projectRef.current;
    if (isProjectCompletelyDefaultForPersistence(proj)) return;
    if (proj.estaCarregando) {
      pendingAutosaveRef.current = true;
      return;
    }
    const snapshot: ProjectSnapshot = {
      projectState: api.serializeForAutosave(proj) as ProjectSnapshot["projectState"],
      viewerSnapshot: viewerSync.saveViewerSnapshot() as ProjectSnapshot["viewerSnapshot"],
      roomSnapshot: api.captureRoomSnapshot(),
    };
    const savedAt = new Date().toISOString();
    safeSetItem(
      AUTOSAVE_STORAGE_KEY,
      JSON.stringify({ snapshot, savedAt })
    );
    pendingAutosaveRef.current = false;
    setProject((prev) =>
      prev.lastAutosaveTime === savedAt ? prev : { ...prev, lastAutosaveTime: savedAt }
    );
  }, [viewerSync, setProject, api, disabled]);

  const scheduleAutosave = useCallback(
    (ms: number) => {
      if (autosaveTimerRef.current != null) {
        window.clearTimeout(autosaveTimerRef.current);
      }
      autosaveTimerRef.current = window.setTimeout(() => {
        autosaveTimerRef.current = null;
        performAutosave();
      }, ms);
    },
    [performAutosave]
  );

  useEffect(() => {
    if (disabled) return;
    const raw = safeGetItem(AUTOSAVE_STORAGE_KEY);
    if (!raw) return;
    let parsed: { snapshot?: ProjectSnapshot; savedAt?: string };
    try {
      parsed = JSON.parse(raw) as { snapshot?: ProjectSnapshot; savedAt?: string };
    } catch {
      return;
    }
    const snap = parsed?.snapshot;
    const projectState =
      snap && typeof snap === "object" && "projectState" in snap
        ? (snap as ProjectSnapshot).projectState
        : null;
    const viewerSnapshot =
      snap && typeof snap === "object" && "viewerSnapshot" in snap
        ? (snap as ProjectSnapshot).viewerSnapshot
        : null;
    const roomSnapshot =
      snap && typeof snap === "object" && "roomSnapshot" in snap
        ? (snap as ProjectSnapshot).roomSnapshot
        : undefined;
    const restored = projectState ? api.revive(projectState) : null;
    if (restored) {
      let next = api.applyResultados
        ? api.applyResultados({ ...restored, lastAutosaveTime: parsed.savedAt ?? restored.lastAutosaveTime ?? null })
        : { ...restored, lastAutosaveTime: parsed.savedAt ?? restored.lastAutosaveTime ?? null };
      if (next.room) {
        applyProjectRoomToWallStore(next.room);
      } else if (roomSnapshot?.walls?.length) {
        const promoted = wallStoreToProjectRoom(roomSnapshot.walls);
        const normalized = promoted ? normalizeProjectRoom(promoted) : null;
        if (normalized) {
          next = { ...next, room: normalized };
          applyProjectRoomToWallStore(normalized);
        } else {
          wallStore.getState().loadRoomConfig(roomSnapshot);
        }
      } else if (roomSnapshot === null) {
        wallStore.getState().clearRoom();
      }
      setProject(next);
    } else if (roomSnapshot !== undefined) {
      if (roomSnapshot) {
        wallStore.getState().loadRoomConfig(roomSnapshot);
      } else {
        wallStore.getState().clearRoom();
      }
    }
    if (viewerSnapshot) {
      viewerSync.restoreViewerSnapshot(viewerSnapshot);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once on mount
  }, []);

  useEffect(() => {
    if (disabled) return;
    const proj = project;
    if (isProjectCompletelyDefaultForPersistence(proj)) return;
    const fingerprint = JSON.stringify(api.serializeForAutosave(proj));
    if (fingerprint === lastAutosaveFingerprintRef.current) return;
    lastAutosaveFingerprintRef.current = fingerprint;
    const boxCount = proj.workspaceBoxes.length;
    const debounceMs = proj.estaCarregando
      ? AUTO_SAVE_BASE_DEBOUNCE_MS * 2
      : boxCount > 12
        ? AUTO_SAVE_BASE_DEBOUNCE_MS * 2
        : AUTO_SAVE_BASE_DEBOUNCE_MS;
    scheduleAutosave(debounceMs);
  }, [project, scheduleAutosave, api]);

  useEffect(() => {
    if (disabled) return;
    if (project.estaCarregando) return;
    if (pendingAutosaveRef.current) {
      scheduleAutosave(450);
    }
  }, [project.estaCarregando, scheduleAutosave, disabled]);

  useEffect(() => {
    return () => {
      if (autosaveTimerRef.current != null) {
        window.clearTimeout(autosaveTimerRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (disabled) return;
    const handler = (e: BeforeUnloadEvent) => {
      const proj = projectRef.current;
      if (!isProjectCompletelyDefaultForPersistence(proj)) {
        e.preventDefault();
        e.returnValue = "Você perderá o seu projeto atual. Deseja continuar?";
      }
    };
    window.addEventListener("beforeunload", handler);
    return () => window.removeEventListener("beforeunload", handler);
  }, [disabled]);

  return { performAutosave, scheduleAutosave };
}

import { useMemo } from "react";
import type { ProjectActions } from "../projectTypes";
import type { ProjectActionsExecutionContext } from "./projectActionsDeps";
import { applyResultados, appendChangelog } from "../projectState";
import { createRematePieces, refreshRemateMountSnap } from "../../core/remate/rematePieceFactory";
import { createRematesForBox } from "../../core/remate/remateFactory";
import { getMaterialByIdOrLabel } from "../../core/materials/service";
import type { CreateRematePieceInput, RemateMountSlot, RematePiece } from "../../core/remate/rematePieceTypes";
import { resolveMountSlot } from "../../core/remate/remateMountFrame";
import { applyProductPatch, computeDimensionsForProduct, inferProductTypeFromLegacy, normalizeProductOptions } from "../../core/remate/remateProductRules";
import {
  applyLRemateGroupCoupling,
  isLRematePiece,
  normalizeLRemateTransformPatch,
  resolveLRemateGroupCouplingLeadId,
  resolveLRemateTransformLeadId,
  snapLRemateGroupCorners,
} from "../../core/remate/remateLGeometry";
import { getRemateEnvelopeBoundsM } from "../../core/remate/rematePlacement";
import { createOppositeRematePiece, duplicateRematePiece } from "../../core/remate/remateCloneUtils";
import {
  invalidateMaterialCutlistCache,
  refreshViewerAfterMaterialSync,
} from "../../core/materials/materialSync";
import {
  applyTampoIndustrialDefaults,
  shouldApplyTampoRules,
  TAMPO_MATERIAL_ID,
  TAMPO_THICKNESS_MM,
  validateTampoIndustrial,
} from "../../core/remate/tampoCozinhaRules";
import {
  isTampoAngularConfig,
  TAMPO_ANGULAR_LAY_FLAT_X_RAD,
} from "../../core/remate/tampoAngle";

export type RemateActions = Pick<
  ProjectActions,
  | "createRematePiece"
  | "createStandaloneRematePiece"
  | "createBoxRemate"
  | "updateRemate"
  | "removeRemate"
  | "selectRematePiece"
  | "resnapRemateToFace"
  | "resetRemateSnap"
  | "duplicateRemate"
  | "createOppositeRemate"
>;

function boxDimsFromWorkspace(box: import("../../core/types").WorkspaceBox) {
  return {
    widthM: Math.max(0.001, (box.dimensoes?.largura ?? 600) / 1000),
    heightM: Math.max(0.001, (box.dimensoes?.altura ?? 720) / 1000),
    depthM: Math.max(0.001, (box.dimensoes?.profundidade ?? 600) / 1000),
  };
}

function refreshLRemateGroupSnap(
  remates: RematePiece[],
  groupId: string,
  box: import("../../core/types").WorkspaceBox,
  boxDimsM: ReturnType<typeof boxDimsFromWorkspace>
): RematePiece[] {
  const group = remates.filter((r) => r.parentGroupId === groupId && isLRematePiece(r));
  const ext = group.find((r) => r.partIndex === 1);
  const int = group.find((r) => r.partIndex === 2);
  if (!ext || !int) return remates;
  const bounds = getRemateEnvelopeBoundsM(boxDimsM.widthM, boxDimsM.heightM, boxDimsM.depthM, box);
  const snapped = snapLRemateGroupCorners(ext, int, bounds);
  return remates.map((r) => {
    if (r.id === snapped.ext.id) return snapped.ext;
    if (r.id === snapped.int.id) return snapped.int;
    return r;
  });
}

export function useRemateActions(ctx: ProjectActionsExecutionContext): RemateActions {
  const { updateProject, projectRef } = ctx;

  return useMemo(
    () => ({
      createRematePiece: (input) => {
        updateProject(
          (prev) => {
            const box = input.parentBoxId
              ? prev.workspaceBoxes.find((b) => b.id === input.parentBoxId)
              : null;
            let materialPresetId =
              input.materialPresetId || box?.material || prev.materialId || prev.material.tipo;
            let material = getMaterialByIdOrLabel(materialPresetId);
            let thicknessMm =
              Number(material?.espessura ?? box?.espessura ?? prev.material.espessura) || 19;
            if (shouldApplyTampoRules({ productType: input.productType, materialPresetId })) {
              materialPresetId = TAMPO_MATERIAL_ID;
              material = getMaterialByIdOrLabel(materialPresetId);
              thicknessMm = Number(material?.espessura) || TAMPO_THICKNESS_MM;
            }
            const created = createRematePieces(
              { ...input, materialPresetId },
              {
                box,
                allBoxes: prev.workspaceBoxes,
                materialPresetId,
                thicknessMm,
                boxDimsM: box ? boxDimsFromWorkspace(box) : undefined,
              }
            );
            return applyResultados({
              ...prev,
              remates: [...(prev.remates ?? []), ...created],
              selectedWorkspaceBoxId: input.parentBoxId ?? prev.selectedWorkspaceBoxId,
              changelog: appendChangelog(prev.changelog, {
                timestamp: new Date(),
                type: "box",
                message: `Remate criado: ${created.map((r) => r.name).join(", ")}`,
              }),
            });
          },
          true
        );
      },

      createStandaloneRematePiece: (input: CreateRematePieceInput) => {
        updateProject(
          (prev) => {
            let materialPresetId = input.materialPresetId || prev.materialId || prev.material.tipo;
            let material = getMaterialByIdOrLabel(materialPresetId);
            let thicknessMm = Number(material?.espessura ?? prev.material.espessura) || 19;
            if (shouldApplyTampoRules({ productType: input.productType, materialPresetId })) {
              materialPresetId = TAMPO_MATERIAL_ID;
              material = getMaterialByIdOrLabel(materialPresetId);
              thicknessMm = Number(material?.espessura) || TAMPO_THICKNESS_MM;
            }
            const created = createRematePieces(
              { ...input, followBox: false, materialPresetId },
              {
                allBoxes: prev.workspaceBoxes,
                materialPresetId,
                thicknessMm,
              }
            );
            return applyResultados({
              ...prev,
              remates: [...(prev.remates ?? []), ...created],
              changelog: appendChangelog(prev.changelog, {
                timestamp: new Date(),
                type: "box",
                message: `Remate standalone: ${created.map((r) => r.name).join(", ")}`,
              }),
            });
          },
          true
        );
      },

      createBoxRemate: (input) => {
        updateProject(
          (prev) => {
            const targetBoxId = input.parentBoxId ?? prev.selectedWorkspaceBoxId;
            const box = prev.workspaceBoxes.find((b) => b.id === targetBoxId);
            if (!box) return prev;
            const materialId = input.materialId || box.material || prev.materialId || prev.material.tipo;
            const material = getMaterialByIdOrLabel(materialId);
            const thicknessMm = Number(material?.espessura ?? box.espessura ?? prev.material.espessura) || 19;
            const existingCount = (prev.remates ?? []).filter((r) => r.parentBoxId === box.id).length;
            const created = createRematesForBox({
              box,
              input,
              materialId,
              thicknessMm,
              existingCount,
            });
            return applyResultados({
              ...prev,
              remates: [...(prev.remates ?? []), ...created],
              changelog: appendChangelog(prev.changelog, {
                timestamp: new Date(),
                type: "box",
                message: `Remate criado: ${created.map((r) => r.name).join(", ")}`,
              }),
            });
          },
          true
        );
      },

      updateRemate: (remateId, patch) => {
        updateProject(
          (prev) => {
            if (patch.materialPresetId != null) {
              invalidateMaterialCutlistCache(prev, {
                affectedBoxIds: (() => {
                  const remate = prev.remates?.find((r) => r.id === remateId);
                  return remate?.parentBoxId ? [remate.parentBoxId] : [];
                })(),
                invalidateGlobalCache: false,
              });
            }
            const transformTargetId = resolveLRemateTransformLeadId(
              remateId,
              prev.remates ?? [],
              patch
            );
            const source = prev.remates?.find((r) => r.id === transformTargetId);
            const normalizedPatch = source
              ? normalizeLRemateTransformPatch(source, patch)
              : patch;

            const userEditedDimensions =
              patch.width != null || patch.height != null || patch.depth != null;

            let remates = (prev.remates ?? []).map((remate) => {
              if (remate.id !== transformTargetId) return remate;
              const { depth: _depthPatchIgnored, ...patchWithoutDepth } = normalizedPatch;
              void _depthPatchIgnored;
              let nextRemate = applyProductPatch(remate, patchWithoutDepth);
              if (userEditedDimensions) {
                nextRemate = { ...nextRemate, userDimensionsLocked: true };
              }

              if (
                shouldApplyTampoRules({
                  productType: nextRemate.productType ?? patch.productType,
                  materialPresetId: nextRemate.materialPresetId,
                })
              ) {
                const candidate = applyTampoIndustrialDefaults({
                  ...nextRemate,
                  width: patch.width ?? nextRemate.width,
                  height: patch.height ?? nextRemate.height,
                });
                const validation = validateTampoIndustrial({
                  widthMm: candidate.width,
                  heightMm: candidate.height,
                  materialPresetId: candidate.materialPresetId,
                });
                if (!validation.ok && (patch.width != null || patch.height != null)) {
                  // Dims inválidas: manter medidas anteriores, forçar regras TAMPO
                  nextRemate = applyTampoIndustrialDefaults({
                    ...remate,
                    productType: "TAMPO_COZINHA",
                    materialPresetId: TAMPO_MATERIAL_ID,
                  });
                  return nextRemate;
                }
                nextRemate = candidate;
              }

                const box = nextRemate.parentBoxId
                  ? prev.workspaceBoxes.find((b) => b.id === nextRemate.parentBoxId)
                  : null;
                const mat = getMaterialByIdOrLabel(nextRemate.materialPresetId);
                const thicknessMm =
                  Number(mat?.espessura ?? box?.espessura ?? prev.material.espessura) ||
                  (shouldApplyTampoRules({
                    productType: nextRemate.productType,
                    materialPresetId: nextRemate.materialPresetId,
                  })
                    ? TAMPO_THICKNESS_MM
                    : 19);
                const shouldRecalcDims =
                  patch.productOptions != null ||
                  patch.productType != null ||
                  patch.mountSlot != null;
                if (
                  shouldRecalcDims &&
                  !nextRemate.userDimensionsLocked &&
                  !shouldApplyTampoRules({
                    productType: nextRemate.productType,
                    materialPresetId: nextRemate.materialPresetId,
                  })
                ) {
                  const productType = nextRemate.productType ?? inferProductTypeFromLegacy(nextRemate);
                  const opts = normalizeProductOptions(productType, nextRemate.productOptions);
                  const dims = computeDimensionsForProduct({
                    box: box ?? null,
                    productType,
                    mountSlot: nextRemate.mountSlot ?? "FRENTE",
                    thicknessMm,
                    productOptions: opts,
                    partRole: nextRemate.partRole,
                    partIndex: nextRemate.partIndex,
                  });
                  nextRemate = { ...nextRemate, ...dims, depth: thicknessMm };
                } else if (
                  shouldRecalcDims &&
                  !nextRemate.userDimensionsLocked &&
                  shouldApplyTampoRules({
                    productType: nextRemate.productType,
                    materialPresetId: nextRemate.materialPresetId,
                  })
                ) {
                  const dims = computeDimensionsForProduct({
                    box: box ?? null,
                    productType: "TAMPO_COZINHA",
                    mountSlot: nextRemate.mountSlot ?? "CIMA",
                    thicknessMm: TAMPO_THICKNESS_MM,
                    productOptions: nextRemate.productOptions,
                    partRole: nextRemate.partRole,
                    partIndex: nextRemate.partIndex,
                  });
                  nextRemate = applyTampoIndustrialDefaults({
                    ...nextRemate,
                    ...dims,
                  });
                } else if (
                  patch.width != null ||
                  patch.height != null ||
                  patch.materialPresetId != null
                ) {
                  nextRemate = { ...nextRemate, depth: thicknessMm };
                } else {
                  nextRemate = { ...nextRemate, depth: thicknessMm };
                }
                if (patch.followBox === true) {
                  nextRemate = { ...nextRemate, placementMode: "SNAPPED" };
                } else if (patch.followBox === false) {
                  nextRemate = { ...nextRemate, placementMode: "FREE" };
                }
                if (isTampoAngularConfig(nextRemate.angleConfig, nextRemate.height)) {
                  const rot = nextRemate.rotation;
                  const needsLayFlat =
                    !rot ||
                    (Math.abs(rot.xRad) < 1e-6 &&
                      Math.abs(rot.yRad) < 1e-6 &&
                      Math.abs(rot.zRad) < 1e-6);
                  nextRemate = {
                    ...nextRemate,
                    followBox: false,
                    parentBoxId: undefined,
                    placementMode: "FREE",
                    rotation: needsLayFlat
                      ? { xRad: TAMPO_ANGULAR_LAY_FLAT_X_RAD, yRad: 0, zRad: 0 }
                      : rot,
                  };
                }
                const shouldResnap =
                  nextRemate.followBox &&
                  nextRemate.placementMode !== "FREE" &&
                  (patch.tipo != null ||
                    patch.mountSlot != null ||
                    patch.productType != null ||
                    patch.productOptions != null ||
                    patch.followBox === true);
                if (shouldResnap && nextRemate.parentBoxId) {
                  const parentBox = prev.workspaceBoxes.find((b) => b.id === nextRemate.parentBoxId);
                  if (parentBox) {
                    nextRemate = refreshRemateMountSnap(nextRemate, parentBox, boxDimsFromWorkspace(parentBox));
                  }
                }
                return nextRemate;
              });

            let changelog = prev.changelog;
            const updated = remates.find((r) => r.id === transformTargetId);
            if (
              updated &&
              (patch.width != null || patch.height != null) &&
              shouldApplyTampoRules({
                productType: updated.productType,
                materialPresetId: updated.materialPresetId,
              })
            ) {
              const validation = validateTampoIndustrial({
                widthMm: patch.width ?? updated.width,
                heightMm: patch.height ?? updated.height,
                materialPresetId: updated.materialPresetId,
              });
              if (!validation.ok) {
                changelog = appendChangelog(prev.changelog, {
                  timestamp: new Date(),
                  type: "box",
                  message: validation.errors.join(" "),
                });
              }
            }

            const couplingLeadId = resolveLRemateGroupCouplingLeadId(
              transformTargetId,
              prev.remates ?? [],
              normalizedPatch
            );

            if (
              normalizedPatch.position != null ||
              normalizedPatch.rotation != null ||
              normalizedPatch.height != null ||
              normalizedPatch.width != null
            ) {
              remates = applyLRemateGroupCoupling(remates, couplingLeadId);
            }

            const next = applyResultados({
              ...prev,
              remates,
              changelog,
            });
            projectRef.current = next;
            if (patch.materialPresetId != null) {
              const remate = next.remates?.find((r) => r.id === remateId);
              refreshViewerAfterMaterialSync({
                affectedRemateIds: [remateId],
                affectedRodapeIds: [],
              });
              void remate;
            }
            return next;
          },
          true
        );
      },

      resnapRemateToFace: (remateId) => {
        updateProject(
          (prev) => {
            const remate = prev.remates?.find((r) => r.id === remateId);
            if (!remate?.parentBoxId) return prev;
            const box = prev.workspaceBoxes.find((b) => b.id === remate.parentBoxId);
            if (!box) return prev;
            const groupId = remate.parentGroupId;
            const dimsM = boxDimsFromWorkspace(box);
            if (groupId && isLRematePiece(remate)) {
              return applyResultados({
                ...prev,
                remates: refreshLRemateGroupSnap(prev.remates ?? [], groupId, box, dimsM),
              });
            }
            const idsToSnap = groupId
              ? (prev.remates ?? []).filter((r) => r.parentGroupId === groupId).map((r) => r.id)
              : [remateId];
            return applyResultados({
              ...prev,
              remates: (prev.remates ?? []).map((r) => {
                if (!idsToSnap.includes(r.id)) return r;
                return refreshRemateMountSnap(r, box, dimsM);
              }),
            });
          },
          true
        );
      },

      resetRemateSnap: (remateId, slot: RemateMountSlot) => {
        updateProject(
          (prev) => {
            const source = prev.remates?.find((r) => r.id === remateId);
            if (!source?.parentBoxId) return prev;
            const box = prev.workspaceBoxes.find((b) => b.id === source.parentBoxId);
            if (!box) return prev;
            const parentBoxId = source.parentBoxId;
            const dimsM = boxDimsFromWorkspace(box);
            return applyResultados({
              ...prev,
              remates: (prev.remates ?? []).map((r) => {
                if (r.parentBoxId !== parentBoxId) return r;
                if (resolveMountSlot(r) !== slot) return r;
                return refreshRemateMountSnap(r, box, dimsM);
              }),
            });
          },
          true
        );
      },

      removeRemate: (remateId) => {
        updateProject(
          (prev) => {
            const removed = prev.remates?.find((remate) => remate.id === remateId);
            const groupId = removed?.parentGroupId;
            return applyResultados({
              ...prev,
              remates: (prev.remates ?? []).filter(
                (remate) =>
                  remate.id !== remateId && (groupId ? remate.parentGroupId !== groupId : true)
              ),
              changelog: removed
                ? appendChangelog(prev.changelog, {
                    timestamp: new Date(),
                    type: "box",
                    message: `Remate removido: ${removed.name}`,
                  })
                : prev.changelog,
            });
          },
          true
        );
      },

      selectRematePiece: () => {
        // Seleção UI via viewer; noop no estado persistido.
      },

      duplicateRemate: (remateId) => {
        let newId: string | null = null;
        updateProject(
          (prev) => {
            const source = prev.remates?.find((r) => r.id === remateId);
            if (!source) return prev;
            const copy = duplicateRematePiece(source);
            newId = copy.id;
            return applyResultados({
              ...prev,
              remates: [...(prev.remates ?? []), copy],
              changelog: appendChangelog(prev.changelog, {
                timestamp: new Date(),
                type: "box",
                message: `Remate duplicado: ${copy.name}`,
              }),
            });
          },
          true
        );
        return newId;
      },

      createOppositeRemate: (remateId) => {
        let newId: string | null = null;
        updateProject(
          (prev) => {
            const source = prev.remates?.find((r) => r.id === remateId);
            if (!source) return prev;
            let opposite = createOppositeRematePiece(source);
            if (!opposite) return prev;

            if (opposite.followBox && opposite.placementMode !== "FREE" && opposite.parentBoxId) {
              const box = prev.workspaceBoxes.find((b) => b.id === opposite!.parentBoxId);
              if (box) {
                opposite = refreshRemateMountSnap(opposite, box, boxDimsFromWorkspace(box));
              }
            }

            newId = opposite.id;
            return applyResultados({
              ...prev,
              remates: [...(prev.remates ?? []), opposite],
              changelog: appendChangelog(prev.changelog, {
                timestamp: new Date(),
                type: "box",
                message: `Remate oposto: ${opposite.name}`,
              }),
            });
          },
          true
        );
        return newId;
      },
    }),
    [updateProject]
  );
}

import { describe, expect, it } from "vitest";
import type { CutPlacement } from "../cutLayoutTypes";
import type { V3Placement } from "../../../nesting-v3/nestingV3Types";
import {
  cutPlacementToV3Placement,
  v3PlacementToCutPlacement,
  physicalBlToV3TopLeft,
  v3TopLeftToPhysicalBl,
  solverUsableToPhysicalBl,
  physicalBlToSolverUsable,
  coordinatesWithinTolerance,
} from "./layoutCoordinateAdapter";

const TOL = 0.01;

describe("layoutCoordinateAdapter", () => {
  it("converte BL físico → TL canvas", () => {
    const pl: CutPlacement = {
      x_mm: 10,
      y_mm: 20,
      largura_mm: 100,
      altura_mm: 50,
      rotacao: 0,
      sheetIndex: 0,
      boxId: "box-1",
      partName: "Lateral",
      metadata: { v3PieceId: "v3-1" },
    };
    const v3 = cutPlacementToV3Placement(pl, 1000);
    expect(v3.pieceId).toBe("v3-1");
    expect(v3.xMm).toBe(10);
    expect(v3.yMm).toBe(930);
    expect(v3.rotated).toBe(false);
  });

  it("round-trip BL → TL → BL (≤ 0,01 mm)", () => {
    const sheetH = 2070;
    const pl: CutPlacement = {
      x_mm: 15.125,
      y_mm: 40.375,
      largura_mm: 600,
      altura_mm: 400.5,
      rotacao: 90,
      sheetIndex: 0,
      boxId: "box-1",
      partName: "Prateleira",
      metadata: { v3PieceId: "v3-2" },
    };
    const v3 = cutPlacementToV3Placement(pl, sheetH);
    const back = v3PlacementToCutPlacement(v3, pl.altura_mm, sheetH);
    expect(coordinatesWithinTolerance(back.x_mm, pl.x_mm, TOL)).toBe(true);
    expect(coordinatesWithinTolerance(back.y_mm, pl.y_mm, TOL)).toBe(true);
  });

  it("round-trip TL → BL → TL (≤ 0,01 mm)", () => {
    const sheetH = 2070;
    const pieceH = 400.5;
    const blX = 15.125;
    const blY = 40.375;
    const tl = physicalBlToV3TopLeft(blX, blY, pieceH, sheetH);
    const v3: V3Placement = {
      pieceId: "v3-2",
      sheetIndex: 0,
      xMm: tl.xMm,
      yMm: tl.yMm,
      rotated: true,
    };
    const bl = v3PlacementToCutPlacement(v3, pieceH, sheetH);
    const tlBack = physicalBlToV3TopLeft(bl.x_mm, bl.y_mm, pieceH, sheetH);
    expect(coordinatesWithinTolerance(tlBack.xMm, v3.xMm, TOL)).toBe(true);
    expect(coordinatesWithinTolerance(tlBack.yMm, v3.yMm, TOL)).toBe(true);
  });

  it("solver-usable ↔ physical BL com margem", () => {
    const margin = 10;
    const usable = { x: 5, y: 8 };
    const physical = solverUsableToPhysicalBl(usable.x, usable.y, margin);
    expect(physical.x_mm).toBe(15);
    expect(physical.y_mm).toBe(18);
    const back = physicalBlToSolverUsable(physical.x_mm, physical.y_mm, margin);
    expect(back.x).toBe(usable.x);
    expect(back.y).toBe(usable.y);
  });
});

import { describe, expect, it, afterEach, beforeEach } from "vitest";
import { divSepRulesStore } from "../../admin/rules/divSepRules/rulesStore";
import { DIV_SEP_RULES_DEFAULTS } from "../../admin/rules/divSepRules/rulesDefaults";
import { defaultRulesConfig } from "../rules/rulesConfig";
import { getDivSepInternalDims, resolveDivisorDimensions } from "./dimensions";
import { resolveSeparadorBottomY } from "./coupling";
import {
  boxUsesDivShelfMode,
  buildDivShelfDrilling,
  countDivShelfPanels,
  MIN_ABOVE_SEP_SHELF_HEIGHT_MM,
  resolveDivShelfAbsoluteCenterYs,
  resolveDivShelfGridYs,
  resolveDivShelfPlacementZones,
  resolvePrimaryDivShelfPlacementZone,
  resolveShelfWidthForDivSide,
  resolveVerticalCompartments,
} from "./shelfDrilling";
import { defaultDivisorItem, defaultSeparadorItem, makeDivSepTestBox, roundMm } from "./divSepTestHelpers";

const SHELF_RULES = {
  ...defaultRulesConfig,
  furos: {
    ...defaultRulesConfig.furos,
    tecnicos: {
      ...defaultRulesConfig.furos.tecnicos,
      prateleira: {
        ...defaultRulesConfig.furos.tecnicos.prateleira,
        margemTopo: 80,
        margemBase: 80,
        minFurosPorColuna: 4,
      },
    },
  },
};

function toAbsoluteLateralYs(espessura: number, ys: number[]): number[] {
  // LAT industrial: Y desde a base do painel inset → absoluto = y + espessura.
  return ys.map((y) => roundMm(y + espessura)).sort((a, b) => a - b);
}

function toAbsoluteDivYs(divBottomY: number, ys: number[]): number[] {
  // DIV industrial: Y desde a base do painel → absoluto = y + divBottomY.
  return ys.map((y) => roundMm(y + divBottomY)).sort((a, b) => a - b);
}

describe("buildDivShelfDrilling — prateleiras com DIV", () => {
  beforeEach(() => {
    divSepRulesStore.patch({ enableShelfHoles: true });
  });

  const sep = defaultSeparadorItem({ id: "sep-shelf", positionMm: 400 });
  const div = defaultDivisorItem({
    id: "div-shelf",
    positionMm: 281,
    prateleiraLado: "direita",
  });
  const box = makeDivSepTestBox({
    dimensoes: { largura: 600, altura: 900, profundidade: 560 },
    prateleiras: 2,
    separadores: [sep],
    divisores: [div],
    panelIds: {
      divisores: ["pid-div-shelf"],
    },
  });

  it("activa modo prateleira com DIV", () => {
    expect(boxUsesDivShelfMode(box)).toBe(true);
  });

  it("cria compartimentos verticais delimitados pelos SEP", () => {
    const zones = resolveVerticalCompartments(box);
    expect(zones.length).toBeGreaterThanOrEqual(1);
    expect(zones.some((zone) => zone.shelfEnabled)).toBe(true);
    expect(zones.some((zone) => !zone.shelfEnabled)).toBe(true);
  });

  it("fura apenas a lateral escolhida e o DIV", () => {
    const result = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES);
    expect(result).not.toBeNull();
    expect(result!.lateral_esquerda.length).toBe(0);
    expect(result!.lateral_direita.length).toBeGreaterThan(0);
    expect(result!.divisorio.get("pid-div-shelf")?.length).toBeGreaterThan(0);
  });

  it("alinha Y dos furos entre lateral e DIV", () => {
    const result = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES)!;
    const divBottomY = getDivSepInternalDims(box).espessura;
    const lateralYs = [
      ...new Set(toAbsoluteLateralYs(box.espessura, result.lateral_direita.map((h) => roundMm(h.y)))),
    ];
    const divYs = [
      ...new Set(toAbsoluteDivYs(divBottomY, (result.divisorio.get("pid-div-shelf") ?? []).map((h) => roundMm(h.y)))),
    ];
    expect(divYs).toEqual(lateralYs);
  });

  it("LAT e DIV têm exactamente os mesmos Y locais (1:1 na chapa)", () => {
    const result = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES)!;
    const latLocal = [...new Set(result.lateral_direita.map((h) => roundMm(h.y)))].sort((a, b) => a - b);
    const divLocal = [
      ...new Set((result.divisorio.get("pid-div-shelf") ?? []).map((h) => roundMm(h.y))),
    ].sort((a, b) => a - b);
    expect(latLocal.length).toBeGreaterThan(0);
    expect(divLocal).toEqual(latLocal);
    expect(divLocal[0]).toBe(latLocal[0]);
    expect(divLocal[divLocal.length - 1]).toBe(latLocal[latLocal.length - 1]);
  });

  it("usa passo industrial exacto de 32 mm por compartimento", () => {
    const result = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES)!;
    const cfg = SHELF_RULES.furos.tecnicos.prateleira;
    const absoluteYs = [...new Set(toAbsoluteLateralYs(box.espessura, result.lateral_direita.map((h) => roundMm(h.y))))];
    for (const zone of resolveVerticalCompartments(box).filter((z) => z.shelfEnabled)) {
      const minY = roundMm(zone.yMin + (cfg.margemBase ?? 0));
      const maxY = roundMm(zone.yMax - (cfg.margemTopo ?? 0));
      const zoneYs = absoluteYs.filter((y) => y >= minY && y <= maxY);
      const steps = zoneYs.slice(1).map((y, index) => roundMm(y - zoneYs[index]!));
      expect(new Set(steps)).toEqual(new Set([32]));
    }
  });

  it("deduplica furos laterais com múltiplos DIV no mesmo lado", () => {
    const multiDivBox = makeDivSepTestBox({
      dimensoes: { largura: 900, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [
        defaultDivisorItem({ id: "div-a", positionMm: 200, prateleiraLado: "direita" }),
        defaultDivisorItem({ id: "div-b", positionMm: 500, prateleiraLado: "direita" }),
      ],
    });
    const result = buildDivShelfDrilling(multiDivBox, multiDivBox.panelIds, SHELF_RULES)!;
    const signatures = new Set(
      result.lateral_direita.map((h) => [roundMm(h.x), roundMm(h.y), roundMm(h.diameter), roundMm(h.depth)].join("|"))
    );
    expect(signatures.size).toBe(result.lateral_direita.length);
  });

  it("respeita compartimentos com SEP sem furos fora da grelha util", () => {
    const result = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES)!;
    const zones = resolveVerticalCompartments(box).filter((zone) => zone.shelfEnabled);
    const absoluteYs = [
      ...new Set(toAbsoluteLateralYs(box.espessura, result.lateral_direita.map((h) => roundMm(h.y)))),
    ];
    const cfg = SHELF_RULES.furos.tecnicos.prateleira;
    for (const y of absoluteYs) {
      const inSomeZone = zones.some((zone) => {
        const minY = roundMm(zone.yMin + (cfg.margemBase ?? 0));
        const maxY = roundMm(zone.yMax - (cfg.margemTopo ?? 0));
        return y >= minY && y <= maxY;
      });
      expect(inSomeZone).toBe(true);
    }
  });

  it("calcula largura da prateleira sem atravessar o DIV", () => {
    const width = resolveShelfWidthForDivSide(box, div);
    expect(width).toBeGreaterThan(0);
    expect(width).toBeLessThan(box.dimensoes.largura - box.espessura * 2);
  });

  it("com DIV+SEP, nenhum furo de prateleira acima do SEP", () => {
    const linkedDiv = defaultDivisorItem({
      id: "div-linked-shelf",
      positionMm: 281,
      linkedSeparadorId: "sep-shelf",
      prateleiraLado: "direita",
    });
    const linkedBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [linkedDiv],
      panelIds: { divisores: ["pid-div-linked-shelf"] },
    });
    const result = buildDivShelfDrilling(linkedBox, linkedBox.panelIds, SHELF_RULES);
    expect(result).not.toBeNull();

    const sepBottomY = roundMm(resolveSeparadorBottomY(linkedBox, sep));
    const cfg = SHELF_RULES.furos.tecnicos.prateleira;
    const margemBase = cfg.margemBase ?? 0;
    const forbiddenMinY = roundMm(sepBottomY + margemBase);
    const disabledZones = resolveVerticalCompartments(linkedBox).filter((zone) => !zone.shelfEnabled);

    const absoluteYs = [
      ...new Set(
        toAbsoluteLateralYs(
          linkedBox.espessura,
          result!.lateral_direita.map((h) => roundMm(h.y))
        )
      ),
    ];

    expect(absoluteYs.length).toBeGreaterThan(0);
    expect(absoluteYs.every((y) => y < forbiddenMinY)).toBe(true);
    for (const y of absoluteYs) {
      const inDisabledZone = disabledZones.some((zone) => {
        const minY = roundMm(zone.yMin + margemBase);
        const maxY = roundMm(zone.yMax - (cfg.margemTopo ?? 0));
        return y >= minY && y <= maxY;
      });
      expect(inDisabledZone).toBe(false);
    }
  });

  it("com prateleiras, o DIV recebe furos no lado correspondente", () => {
    const right = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES)!;
    const rightHoles = right.divisorio.get("pid-div-shelf") ?? [];
    expect(rightHoles.length).toBeGreaterThan(0);
    expect(rightHoles.every((h) => h.face === "A")).toBe(true);

    const leftDiv = defaultDivisorItem({
      id: "div-left-shelf",
      positionMm: 281,
      prateleiraLado: "esquerda",
    });
    const leftBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [leftDiv],
      panelIds: { divisores: ["pid-div-left-shelf"] },
    });
    const left = buildDivShelfDrilling(leftBox, leftBox.panelIds, SHELF_RULES)!;
    expect(left.lateral_direita.length).toBe(0);
    expect(left.lateral_esquerda.length).toBeGreaterThan(0);
    const leftHoles = left.divisorio.get("pid-div-left-shelf") ?? [];
    expect(leftHoles.length).toBeGreaterThan(0);
    expect(leftHoles.every((h) => h.face === "B")).toBe(true);
  });

  it("DIV e lateral têm grelha idêntica", () => {
    const result = buildDivShelfDrilling(box, box.panelIds, SHELF_RULES)!;
    const divBottomY = getDivSepInternalDims(box).espessura;
    const lateralYs = [
      ...new Set(toAbsoluteLateralYs(box.espessura, result.lateral_direita.map((h) => roundMm(h.y)))),
    ];
    const divYs = [
      ...new Set(toAbsoluteDivYs(divBottomY, (result.divisorio.get("pid-div-shelf") ?? []).map((h) => roundMm(h.y)))),
    ];
    expect(divYs.length).toBeGreaterThan(0);
    expect(divYs).toEqual(lateralYs);
  });

  it("nenhum furo no DIV acima do SEP", () => {
    const linkedDiv = defaultDivisorItem({
      id: "div-no-above",
      positionMm: 281,
      linkedSeparadorId: "sep-shelf",
      prateleiraLado: "direita",
    });
    const linkedBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [linkedDiv],
      panelIds: { divisores: ["pid-div-no-above"] },
    });
    const result = buildDivShelfDrilling(linkedBox, linkedBox.panelIds, SHELF_RULES)!;
    const divBottomY = getDivSepInternalDims(linkedBox).espessura;
    const sepBottomY = roundMm(resolveSeparadorBottomY(linkedBox, sep));
    const divYs = [
      ...new Set(
        toAbsoluteDivYs(divBottomY, (result.divisorio.get("pid-div-no-above") ?? []).map((h) => roundMm(h.y)))
      ),
    ];
    expect(divYs.length).toBeGreaterThan(0);
    expect(divYs.every((y) => y < sepBottomY)).toBe(true);
  });

  it("usa panelId industrial divisorio-N quando panelIds.divisores está vazio", () => {
    const bare = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [defaultDivisorItem({ id: "uuid-only", prateleiraLado: "direita" })],
    });
    bare.panelIds = { ...bare.panelIds!, divisores: [] };
    const result = buildDivShelfDrilling(bare, bare.panelIds, SHELF_RULES)!;
    expect(result.divisorio.get("divisorio-1")?.length ?? 0).toBeGreaterThan(0);
    expect(result.divisorio.get("uuid-only")?.length ?? 0).toBeGreaterThan(0);
  });

  it(`desactiva zona acima do SEP sem DIV acima (mesmo se altura < ${MIN_ABOVE_SEP_SHELF_HEIGHT_MM} mm)`, () => {
    const zones = resolveVerticalCompartments(box);
    const topZone = zones[zones.length - 1]!;
    expect(topZone.yMax - topZone.yMin).toBeLessThan(MIN_ABOVE_SEP_SHELF_HEIGHT_MM);
    expect(topZone.shelfEnabled).toBe(false);
  });

  it("activa zona acima do SEP quando existe DIV ligado acima", () => {
    const sepLow = defaultSeparadorItem({ id: "sep-low", positionMm: 400 });
    const divAbove = defaultDivisorItem({
      id: "div-above-shelf",
      linkedSeparadorId: "sep-low",
      posicaoRelativaAoSep: "cima",
      positionMm: 281,
      prateleiraLado: "direita",
    });
    const tallBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 2000, profundidade: 560 },
      prateleiras: 2,
      separadores: [sepLow],
      divisores: [divAbove],
      panelIds: { divisores: ["pid-div-above"] },
    });
    const zones = resolveVerticalCompartments(tallBox);
    const topZone = zones[zones.length - 1]!;
    expect(topZone.shelfEnabled).toBe(true);

    const placement = resolveDivShelfPlacementZones(tallBox, divAbove);
    expect(placement.length).toBeGreaterThan(0);
    expect(placement.some((z) => z.yMin >= topZone.yMin - 0.5)).toBe(true);

    const result = buildDivShelfDrilling(tallBox, tallBox.panelIds, SHELF_RULES);
    expect(result).not.toBeNull();
    const sepBottomY = roundMm(resolveSeparadorBottomY(tallBox, sepLow));
    const absYs = toAbsoluteLateralYs(
      tallBox.espessura,
      result!.lateral_direita.map((h) => roundMm(h.y))
    );
    expect(absYs.some((y) => y > sepBottomY)).toBe(true);
  });

  it("prateleiraYsMm escolhe posições exactas na grelha", () => {
    const linkedDiv = defaultDivisorItem({
      id: "div-exact",
      positionMm: 281,
      linkedSeparadorId: "sep-shelf",
      prateleiraLado: "direita",
    });
    const linkedBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [linkedDiv],
    });
    const grid = resolveDivShelfGridYs(linkedBox, linkedDiv, SHELF_RULES);
    expect(grid.length).toBeGreaterThanOrEqual(2);
    const chosen = [grid[0]!, grid[2] ?? grid[1]!];
    const withExact = {
      ...linkedDiv,
      prateleiraYsMm: chosen,
    };
    const ys = resolveDivShelfAbsoluteCenterYs(linkedBox, withExact, 2, SHELF_RULES);
    expect(ys).toEqual(chosen.slice(0, 2));
  });

  it("com N prateleiras e DIV+SEP, countDivShelfPanels = N (sem duplicar acima do SEP)", () => {
    const linkedDiv = defaultDivisorItem({
      id: "div-count",
      positionMm: 281,
      linkedSeparadorId: "sep-shelf",
      prateleiraLado: "direita",
    });
    const linkedBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [linkedDiv],
    });
    expect(resolveVerticalCompartments(linkedBox).length).toBeGreaterThanOrEqual(2);
    expect(resolveDivShelfPlacementZones(linkedBox, linkedDiv).length).toBeGreaterThanOrEqual(1);
    expect(countDivShelfPanels(linkedBox)).toBe(2);
  });

  it("placement zones nunca incluem a zona acima do SEP", () => {
    const linkedDiv = defaultDivisorItem({
      id: "div-no-above-zone",
      linkedSeparadorId: "sep-shelf",
      prateleiraLado: "direita",
    });
    const linkedBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 3,
      separadores: [sep],
      divisores: [linkedDiv],
    });
    const sepBottom = resolveSeparadorBottomY(linkedBox, sep);
    const zones = resolveDivShelfPlacementZones(linkedBox, linkedDiv);
    expect(zones.length).toBeGreaterThan(0);
    expect(zones.every((z) => z.yMax <= sepBottom + 0.5)).toBe(true);
    expect(zones.every((z) => z.shelfEnabled)).toBe(true);
    expect(countDivShelfPanels(linkedBox)).toBe(3);
  });

  it("Y absolutos das N prateleiras ficam todos abaixo do SEP (zero acima)", () => {
    const linkedDiv = defaultDivisorItem({
      id: "div-abs-ys",
      linkedSeparadorId: "sep-shelf",
      prateleiraLado: "direita",
    });
    const linkedBox = makeDivSepTestBox({
      dimensoes: { largura: 600, altura: 900, profundidade: 560 },
      prateleiras: 2,
      separadores: [sep],
      divisores: [linkedDiv],
    });
    const sepBottom = resolveSeparadorBottomY(linkedBox, sep);
    const allZones = resolveVerticalCompartments(linkedBox);
