    const esqEdge = esq.filter((h) => h.tipo === "cavilha" && !h.topDrillable);
    const dirEdge = dir.filter((h) => h.tipo === "cavilha" && !h.topDrillable);
    expect(esqEdge.every((h) => h.x === LAT.largura)).toBe(true);
    expect(dirEdge.every((h) => h.x === 0)).toBe(true);
