    expect(frente.every((h) => h.tipo === "cavilha" && h.profundidade === 30)).toBe(true);
    expect([...new Set(frente.map((h) => h.y))].sort((a, b) => a - b)).toEqual(
      [...new Set(costaCav.map((h) => h.y))].sort((a, b) => a - b)
    );
  });
});

