/**
 * Sugestões de «tipo» para o datalist de Painéis (camada visual).
 * Não alimenta totais Unificado nem lineOverrides.
 */

import type { ProjectState } from "@/context/projectTypes";
import type { ProductionRelease } from "@/core/industrial/productionRelease";
import type { RematePiece } from "@/core/remate/rematePieceTypes";

import { buildPaineisChapasDetalhe } from "./paineisChapasDetalhe";

function pushUnique(out: string[], seen: Set<string>, raw: unknown) {
  const s = String(raw ?? "").trim();
  if (!s || seen.has(s)) return;
  seen.add(s);
  out.push(s);
}

/** Rótulo amigável a partir de productType industrial (só sugestão). */
export function labelFromRemateProductType(
  productType: string | undefined
): string | null {
  if (!productType) return null;
  switch (productType) {
    case "TAMPO_COZINHA":
      return "TAMPO";
    case "RODAPE":
    case "RODAPE_L":
      return "RODAPE";
    case "AVISTA":
      return "AVISTA";
    case "COMPLETO":
      return "COMPLETO";
    case "L":
      return "L";
    default: {
      const t = productType.replace(/_/g, " ").trim();
      return t || null;
    }
  }
}

export function collectSugestoesFromRemates(
  remates: RematePiece[] | null | undefined
): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const r of remates ?? []) {
    pushUnique(out, seen, r.tipo);
    pushUnique(out, seen, labelFromRemateProductType(r.productType));
  }
  return out;
}

/**
 * Aceita nomes de peça curtos (ex. TAMPO, LATERAL_ESQ).
 * Rejeita medidas, códigos longos e texto livre com espaços/números dimensionais.
 */
export function isCutlistNomeSugestaoSegura(nome: string): boolean {
  const s = String(nome || "").trim();
  if (!s || s.length > 28) return false;
  // Medidas / unidades / preços
  if (/\d+\s*[x×]\s*\d+/i.test(s)) return false;
  if (/\b(mm|cm|m²|m2|eur|€)\b/i.test(s)) return false;
  if (/\d{3,}/.test(s)) return false; // códigos/IDs numéricos longos
  // Preferir token industrial: letras/underscore, opcionalmente um sufixo curto
  if (!/^[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ0-9_\-]{0,27}$/.test(s)) return false;
  // Evitar nomes que são só material genérico em minúsculas com espaços (já cobertos)
  return true;
}

/** Tipos/nomes de peça na cutlist — `tipo` sempre; `nome` só se passar o filtro anti-ruído. */
export function collectSugestoesFromCutlistTipos(
  state: ProjectState | null | undefined
): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  const items = Array.isArray(state?.cutList) ? state!.cutList : [];
  for (const item of items) {
    const tipo = String(item.tipo ?? "").trim();
    const nome = String(item.nome ?? "").trim();
    if (tipo) pushUnique(out, seen, tipo);
    if (nome && isCutlistNomeSugestaoSegura(nome)) {
      pushUnique(out, seen, nome);
    }
  }
  return out;
}

/**
 * Fontes (dedupe mantém a 1ª ocorrência):
 * 1) Materiais de chapa do detalhe nesting
 * 2) Remates: tipo + productType (TAMPO, …)
 * 3) Cutlist: tipo / nome filtrado
 * 4) Rodapés (id/nome se existirem)
 */
export function collectPaineisSugestoesProjeto(
  projectId: string,
  state: ProjectState | null | undefined
): string[] {
  const out: string[] = [];
  const seen = new Set<string>();

  if (projectId.trim()) {
    try {
      for (const t of buildPaineisChapasDetalhe(projectId, state).map(
        (d) => d.tipo
      )) {
        pushUnique(out, seen, t);
      }
    } catch {
      /* ignore — só sugestões */
    }
  }

  for (const t of collectSugestoesFromRemates(state?.remates)) {
    pushUnique(out, seen, t);
  }

  for (const t of collectSugestoesFromCutlistTipos(state)) {
    pushUnique(out, seen, t);
  }

  for (const r of state?.rodapes ?? []) {
    pushUnique(out, seen, "RODAPE");
    if (r.nomePersonalizado && isCutlistNomeSugestaoSegura(r.nomePersonalizado)) {
      pushUnique(out, seen, r.nomePersonalizado);
    } else if (r.name && isCutlistNomeSugestaoSegura(r.name)) {
      pushUnique(out, seen, r.name);
    }
  }

  return out;
}

/**
 * F2 — sugestões só a partir do productionRelease (última geração TCN).
 * Não lê remates/cutlist live do ProjectState.
 */
export function collectPaineisSugestoesFromRelease(
  release: ProductionRelease | null | undefined
): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  if (!release) return out;
  for (const sheet of release.chapas?.sheets ?? []) {
    pushUnique(out, seen, sheet.material);
    for (const piece of sheet.pieces ?? []) {
      const nome = String(piece.nome ?? "").trim();
      if (/tampo/i.test(nome)) pushUnique(out, seen, "TAMPO");
      if (isCutlistNomeSugestaoSegura(nome)) pushUnique(out, seen, nome);
    }
  }
  return out;
}

/**
 * Importacao leve PIMO TRAK - apenas leitura de work-orders/tasks.
 * Nao altera ordens nem estados industriais.
 */

import { fetchWorkOrderDetail, fetchWorkOrders } from "@/industrial/api/workOrderActions";
import type { IndustrialWorkOrderTask } from "@/industrial/work-orders/types";

import {
  emptyMetricas,
  emptyMontagem,
  emptyProducao,
  makeReportId,
  type ProjectReportMetricas,
  type ProjectReportMontagem,
  type ProjectReportProducao,
  type ReportOperador,
} from "./types";

export type TrakImportSnapshot = {
  metricas: ProjectReportMetricas;
  producaoPatch: Pick<
    ProjectReportProducao,
    "dataInicio" | "dataFim" | "horasEfetivas" | "operadores"
  >;
  montagemPatch: Pick<ProjectReportMontagem, "dataInicio" | "dataFim" | "instaladores">;
  ordersCount: number;
};

function toDateInput(iso: string | undefined): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toISOString().slice(0, 10);
}

function hoursBetween(start?: string, end?: string): number {
  if (!start || !end) return 0;
  const a = Date.parse(start);
  const b = Date.parse(end);
  if (!Number.isFinite(a) || !Number.isFinite(b) || b <= a) return 0;
  return Math.round(((b - a) / 3_600_000) * 100) / 100;
}

function isMontagemStation(station: string, operationType?: string): boolean {
  const s = station.toLowerCase();
  const op = (operationType ?? "").toLowerCase();
  return s === "montagem" || op === "montagem";
}

function emptySnapshot(): TrakImportSnapshot {
  return {
    metricas: emptyMetricas(),
    producaoPatch: {
      dataInicio: "",
      dataFim: "",
      horasEfetivas: 0,
      operadores: [],
    },
    montagemPatch: {
      dataInicio: "",
      dataFim: "",
      instaladores: [],
    },
    ordersCount: 0,
  };
}

/**
 * Le work-orders + tasks do projeto e deriva metricas / datas / horas / operadores.
 * Falhas de rede/Supabase devolvem snapshot vazio (campos manuais cobrem).
 */
export async function importTrakSnapshot(projectId: string): Promise<TrakImportSnapshot> {
  const id = projectId.trim();
  if (!id) return emptySnapshot();

  try {
    const orders = await fetchWorkOrders({ projectId: id });
    const details = await Promise.all(
      orders.slice(0, 40).map(async (order) => {
        try {
          return await fetchWorkOrderDetail(order.id);
        } catch {
          return { order, tasks: [] as IndustrialWorkOrderTask[] };
        }
      })
    );

    const metricas = emptyMetricas();
    metricas.ordensTrabalho = orders.length;
    metricas.tarefasConcluidas = orders.filter((o) => o.status === "completed").length;

    const rejectedTasks = details.flatMap((d) =>
      d.tasks.filter((t) => t.status === "rejected")
    );
    metricas.erros = rejectedTasks.length;

    const operatorMap = new Map<string, ReportOperador>();
    let prodStart = "";
    let prodEnd = "";
    let montStart = "";
    let montEnd = "";
    let horasProd = 0;
    let horasMont = 0;

    const bumpDate = (cur: string, iso: string | undefined, mode: "min" | "max") => {
      const next = toDateInput(iso);
      if (!next) return cur;
      if (!cur) return next;
      return mode === "min" ? (next < cur ? next : cur) : next > cur ? next : cur;
    };

    for (const { order, tasks } of details) {
      const station = order.station;
      for (const task of tasks) {
        const montagem = isMontagemStation(station, task.operationType);
        if (montagem) {
          montStart = bumpDate(montStart, task.startedAt ?? order.createdAt, "min");
          montEnd = bumpDate(montEnd, task.completedAt ?? order.updatedAt, "max");
          horasMont += hoursBetween(task.startedAt, task.completedAt);
        } else {
          prodStart = bumpDate(prodStart, task.startedAt ?? order.createdAt, "min");
          prodEnd = bumpDate(prodEnd, task.completedAt ?? order.updatedAt, "max");
          horasProd += hoursBetween(task.startedAt, task.completedAt);
        }

        const opId = (task.operatorId ?? "").trim();
        if (!opId) continue;
        const prev = operatorMap.get(opId);
        const h = hoursBetween(task.startedAt, task.completedAt);
        const tarefa = `${station}/${task.operationType}`;
        if (prev) {
          prev.horas = Math.round((prev.horas + h) * 100) / 100;
          if (!prev.tarefas.includes(tarefa)) {
            prev.tarefas = prev.tarefas ? `${prev.tarefas}; ${tarefa}` : tarefa;
          }
        } else {
          operatorMap.set(opId, {
            id: makeReportId("op"),
            nome: opId,
            horas: h,
            tarefas: tarefa,
          });
        }
      }

      // fallback datas da ordem se nao houver tasks
      if (tasks.length === 0) {
        if (isMontagemStation(station)) {
          montStart = bumpDate(montStart, order.createdAt, "min");
          montEnd = bumpDate(montEnd, order.updatedAt, "max");
        } else {
          prodStart = bumpDate(prodStart, order.createdAt, "min");
          prodEnd = bumpDate(prodEnd, order.updatedAt, "max");
        }
      }
    }

    const operadores = Array.from(operatorMap.values());
    metricas.colaboradores = operadores.length;

    // Separar instaladores (tarefas montagem) vs producao: por agora mesma lista se so houver operatorId
    const instaladores = operadores.filter((o) =>
      o.tarefas.toLowerCase().includes("montagem")
    );

    return {
      metricas,
      producaoPatch: {
        dataInicio: prodStart,
        dataFim: prodEnd,
        horasEfetivas: Math.round(horasProd * 100) / 100,
        operadores,
      },
      montagemPatch: {
        dataInicio: montStart,
        dataFim: montEnd,
        instaladores: instaladores.length ? instaladores : [],
      },
      ordersCount: orders.length,
    };
  } catch {
    return emptySnapshot();
  }
}

/** Aplica patch TRAK respeitando manualPaths. */
export function applyTrakToReportParts(
  existing: {
    metricas: ProjectReportMetricas;
    producao: ProjectReportProducao;
    montagem: ProjectReportMontagem;
  },
  snap: TrakImportSnapshot,
  isManual: (path: string) => boolean
): {
  metricas: ProjectReportMetricas;
  producao: ProjectReportProducao;
  montagem: ProjectReportMontagem;
} {
  // Ordens / tarefas: cache TRAK (erros/melhorias/colaboradores sao derivados depois).
  const metricas = { ...existing.metricas };
  metricas.ordensTrabalho = Math.max(metricas.ordensTrabalho, snap.metricas.ordensTrabalho);
  metricas.tarefasConcluidas = Math.max(
    metricas.tarefasConcluidas,
    snap.metricas.tarefasConcluidas
  );

  const producao = { ...existing.producao };
  if (!isManual("producao.dataInicio") && !producao.dataInicio) {
    producao.dataInicio = snap.producaoPatch.dataInicio;
  }
  if (!isManual("producao.dataFim") && !producao.dataFim) {
    producao.dataFim = snap.producaoPatch.dataFim;
  }
  if (!isManual("producao.horasEfetivas") && !producao.horasEfetivas) {
    producao.horasEfetivas = snap.producaoPatch.horasEfetivas;
  }
  if (!isManual("producao.operadores") && producao.operadores.length === 0) {
    producao.operadores = snap.producaoPatch.operadores;
  }

  const montagem = { ...existing.montagem };
  if (!isManual("montagem.dataInicio") && !montagem.dataInicio) {
    montagem.dataInicio = snap.montagemPatch.dataInicio;
  }
  if (!isManual("montagem.dataFim") && !montagem.dataFim) {
    montagem.dataFim = snap.montagemPatch.dataFim;
  }
  if (!isManual("montagem.instaladores") && montagem.instaladores.length === 0) {
    montagem.instaladores = snap.montagemPatch.instaladores;
  }

  return { metricas, producao, montagem };
}

/** Helper tipado para seed inicial. */
export function trakIntoEmptyProducao(snap: TrakImportSnapshot): ProjectReportProducao {
  return {
    ...emptyProducao(),
    dataInicio: snap.producaoPatch.dataInicio,
    dataFim: snap.producaoPatch.dataFim,
    horasEfetivas: snap.producaoPatch.horasEfetivas,
    operadores: snap.producaoPatch.operadores,
  };
}

export function trakIntoEmptyMontagem(snap: TrakImportSnapshot): ProjectReportMontagem {
  return {
    ...emptyMontagem(),
    dataInicio: snap.montagemPatch.dataInicio,
    dataFim: snap.montagemPatch.dataFim,
    instaladores: snap.montagemPatch.instaladores,
  };
}

import { useEffect, useState } from "react";

import { buildApiUrl } from "../../config/api";
import type { ViewerRenderOptions, ViewerRenderResult } from "../../context/projectTypes";

import { buildProjectsUrl } from "./projectsApi";
import { authHeaders, canUseRemoteProjectsApi } from "./remoteApiAuth";

const THUMBS_BASE = "/api/projects/thumbs";
/** Mínimo para considerar uma imagem gerada válida (evita POST vazio). */
const MIN_THUMB_BYTES = 64;

export type ProjectThumbnailRenderScene = (
  options: ViewerRenderOptions
) => Promise<ViewerRenderResult | null>;

/** Alinhado a coerce_safe_filename no PHP — nunca envia name vazio/ilegal. */
export function coerceSafeProjectThumbName(projectName: string): string | null {
  let name = String(projectName ?? "").trim();
  if (!name) return null;
  name = name.replace(/\.\./g, "");
  name = name.replace(/[\/\\<>:"|?*\x00]+/g, "_").replace(/^[.\s_]+|[.\s_]+$/g, "");
  if (!name) return null;
  if (name.length > 160) name = name.slice(0, 160).trim();
  return name || null;
}

function safeProjectFileName(projectName: string): string {
  return coerceSafeProjectThumbName(projectName) ?? "";
}

export function buildProjectThumbnailPath(projectName: string, ext: "webp" | "jpg" = "jpg"): string {
  const name = safeProjectFileName(projectName);
  return `${THUMBS_BASE}/${encodeURIComponent(name)}.${ext}`;
}

/**
 * Resolução síncrona: só data URLs / URLs absolutas já utilizáveis em <img>.
 * Paths `/api/projects/thumbs/...` NÃO são devolvidos aqui — exigem Bearer (ver hook B1).
 */
export function resolveProjectThumbnailSrc(
  projectName: string,
  thumbnailDataUrl?: string | null,
  cacheKey?: string
): string | null {
  const trimmed = typeof thumbnailDataUrl === "string" ? thumbnailDataUrl.trim() : "";
  if (trimmed) {
    if (trimmed.startsWith("data:") || /^https?:\/\//i.test(trimmed) || trimmed.startsWith("blob:")) {
      const withCache =
        cacheKey && !trimmed.startsWith("data:") && !trimmed.startsWith("blob:") && !trimmed.includes("?")
          ? `${trimmed}?v=${encodeURIComponent(cacheKey)}`
          : trimmed;
      return withCache;
    }
    if (trimmed.startsWith("/") && !trimmed.includes("/api/projects/thumbs")) {
      const withCache =
        cacheKey && !trimmed.includes("?")
          ? `${trimmed}?v=${encodeURIComponent(cacheKey)}`
          : trimmed;
      return buildApiUrl(withCache);
    }
    // Path de thumbs API — não usar directamente em <img> (sem Authorization).
  }

  void projectName;
  return null;
}

/** Fetch autenticado de `/api/projects/thumbs/...` → blob URL (revogar no cleanup do caller). */
export async function fetchAuthenticatedThumbnailBlobUrl(
  projectName: string,
  cacheKey?: string
): Promise<string | null> {
  if (!canUseRemoteProjectsApi()) return null;
  const name = safeProjectFileName(projectName);
  if (!name) return null;

  const tryExt = async (ext: "jpg" | "webp"): Promise<string | null> => {
    const path = buildProjectThumbnailPath(name, ext);
    const suffix = cacheKey ? `?v=${encodeURIComponent(cacheKey)}` : "";
    const url = `${buildApiUrl(path)}${suffix}`;
    try {
      const response = await fetch(url, { headers: authHeaders(), method: "GET" });
      if (!response.ok) return null;
      const contentType = String(response.headers.get("content-type") || "").toLowerCase();
      if (contentType.includes("application/json")) return null;
      const blob = await response.blob();
      if (!isValidThumbnailBlob(blob)) return null;
      return URL.createObjectURL(blob);
    } catch {
      return null;
    }
  };

  return (await tryExt("jpg")) ?? (await tryExt("webp"));
}

/**
 * Hook B1: preferir thumbnailDataUrl; senão fetch com Bearer → blob URL.
 * Placeholder (null) em falha pontual — sem erros ruidosos.
 */
type ThumbnailBlobState = {
  projectName: string;
  cacheKey: string | undefined;
  url: string | null;
};

export function useAuthenticatedProjectThumbnailSrc(
  projectName: string,
  thumbnailDataUrl?: string | null,
  cacheKey?: string
): string | null {
  const syncSrc = resolveProjectThumbnailSrc(projectName, thumbnailDataUrl, cacheKey);
  const [blobState, setBlobState] = useState<ThumbnailBlobState | null>(null);

  useEffect(() => {
    if (syncSrc || !canUseRemoteProjectsApi()) return;

    let cancelled = false;
    let createdUrl: string | null = null;

    void fetchAuthenticatedThumbnailBlobUrl(projectName, cacheKey).then((url) => {
      if (cancelled) {
        if (url) URL.revokeObjectURL(url);
        return;
      }
      createdUrl = url;
      setBlobState({ projectName, cacheKey, url });
    });

    return () => {
      cancelled = true;
      if (createdUrl) URL.revokeObjectURL(createdUrl);
    };
  }, [projectName, thumbnailDataUrl, cacheKey, syncSrc]);

  const blobSrc =
    blobState &&
    blobState.projectName === projectName &&
    blobState.cacheKey === cacheKey
      ? blobState.url
      : null;

  return syncSrc ?? blobSrc;
}

export function isValidThumbnailBlob(blob: Blob | null | undefined): blob is Blob {
  if (!blob || typeof blob.size !== "number") return false;
  if (blob.size < MIN_THUMB_BYTES) return false;
  const type = String(blob.type || "").toLowerCase();
  if (type && !type.startsWith("image/")) return false;
  return true;
}

export function isValidThumbnailDataUrl(dataUrl: string | null | undefined): boolean {
  if (typeof dataUrl !== "string") return false;
  const trimmed = dataUrl.trim();
  if (!trimmed.startsWith("data:image/")) return false;
  const comma = trimmed.indexOf(",");
  if (comma < 0) return false;
  const b64 = trimmed.slice(comma + 1).trim();
  // ~base64 de pelo menos MIN_THUMB_BYTES
  return b64.length >= Math.ceil((MIN_THUMB_BYTES * 4) / 3);
}

export async function projectThumbnailExists(
  projectName: string
): Promise<{ exists: boolean; url: string | null }> {
  const name = coerceSafeProjectThumbName(projectName);
  if (!name) return { exists: false, url: null };
  if (!canUseRemoteProjectsApi()) return { exists: false, url: null };

  const params = new URLSearchParams({ action: "thumb", name });
  try {
    const response = await fetch(buildProjectsUrl(params), {
      method: "HEAD",
      headers: authHeaders(),
    });
    if (response.ok) {
      return {
        exists: true,
        url: buildApiUrl(buildProjectThumbnailPath(name)),
      };
    }
    const getResponse = await fetch(buildProjectsUrl(params), {
      headers: authHeaders(),
    });
    if (!getResponse.ok) return { exists: false, url: null };
    const payload = (await getResponse.json()) as { exists?: boolean; url?: string };
    const url = typeof payload.url === "string" ? payload.url : null;
    return {
      exists: Boolean(payload.exists),
      url: url ? (url.startsWith("/") ? buildApiUrl(url) : url) : null,
    };
  } catch {
    return { exists: false, url: null };
  }
}

export async function dataUrlToBlob(dataUrl: string): Promise<Blob | null> {
  try {
    const response = await fetch(dataUrl);
    const blob = await response.blob();
    return isValidThumbnailBlob(blob) ? blob : null;
  } catch {
    return null;
  }
}

async function blobToDataUrl(blob: Blob): Promise<string | null> {
  try {
    return await new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : null);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(blob);
    });
  } catch {
    return null;
  }
}

export async function captureWorkspaceProjectThumbnail(
  renderScene: ProjectThumbnailRenderScene
): Promise<Blob | null> {
  const result = await renderScene({
    size: "medium",
    mode: "pbr",
    background: "project-transparent",
    preset: "iso1",
    format: "jpg",
    quality: 0.92,
    advancedRealism: true,
    watermark: false,
  });
  if (!result?.dataUrl || !isValidThumbnailDataUrl(result.dataUrl)) return null;
  return dataUrlToBlob(result.dataUrl);
}

/**
 * Upload de thumbnail só com imagem válida.
 * Preferência: JSON dataUrl (evita multipart vazio em proxies); fallback multipart.
 */
export async function uploadProjectThumbnail(
  projectName: string,
  blob: Blob
): Promise<string | null> {
  const name = coerceSafeProjectThumbName(projectName);
  if (!name || !isValidThumbnailBlob(blob)) return null;
  if (!canUseRemoteProjectsApi()) return null;

  const ext = blob.type.includes("webp") ? "webp" : "jpg";
  const params = new URLSearchParams({ action: "thumb", name });

  const parseUrl = async (response: Response): Promise<string | null> => {
    const payload = (await response.json().catch(() => null)) as
      | { url?: string; status?: string; message?: string }
      | null;
    if (!response.ok) return null;
    const url = typeof payload?.url === "string" ? payload.url : buildProjectThumbnailPath(name, ext);
    return url.startsWith("/") ? buildApiUrl(url) : url;
  };

  try {
    const dataUrl = await blobToDataUrl(blob);
    if (!dataUrl || !isValidThumbnailDataUrl(dataUrl)) return null;

    // Caminho principal: JSON com dataUrl (payload explícito, sem ficheiro vazio)
    const jsonResponse = await fetch(buildProjectsUrl(params), {
      method: "POST",
      headers: authHeaders({ "Content-Type": "application/json; charset=utf-8" }),
      body: JSON.stringify({ name, dataUrl, mime: blob.type || "image/jpeg" }),
    });
    if (jsonResponse.ok) {
      return parseUrl(jsonResponse);
    }

    // Fallback multipart só se o JSON falhar (ex.: limite de body)
    const form = new FormData();
    form.append("name", name);
    form.append("file", blob, `${name}.${ext}`);
    const multipartResponse = await fetch(buildProjectsUrl(params), {
      method: "POST",
      headers: authHeaders(),
      body: form,
    });
    return parseUrl(multipartResponse);
  } catch {
    return null;
  }
}

export async function ensureProjectThumbnailUploaded(
  projectName: string,
  blob: Blob
): Promise<string | null> {
  if (!isValidThumbnailBlob(blob)) return null;
  if (!canUseRemoteProjectsApi()) return null;
  const existing = await projectThumbnailExists(projectName);
  if (existing.exists) return existing.url;
  return uploadProjectThumbnail(projectName, blob);
}

